  // ── D. 可見診斷面板(iPad 拍照用) ─────────────────────────────────
  window._fbDiagLogs = [];
  // ★ v3.3.7 — 記錄頁面載入時刻,給 onAuthStateChanged race 保護使用
  //   不能等 onAuthStateChanged 才設(那時就太晚了,race 視窗已經過了)
  if(!window._pageLoadedAt) window._pageLoadedAt = Date.now();
  window._fbDiag = function(msg, level){
    try{
      const ts = new Date();
      const hh = String(ts.getHours()).padStart(2,'0');
      const mm = String(ts.getMinutes()).padStart(2,'0');
      const ss = String(ts.getSeconds()).padStart(2,'0');
      const ms = String(ts.getMilliseconds()).padStart(3,'0');
      const line = `[${hh}:${mm}:${ss}.${ms}] ${msg}`;
      window._fbDiagLogs.push({ line, level: level || 'info' });
      // 同步輸出到 console
      const fn = (level === 'error') ? console.error
              : (level === 'warn')  ? console.warn  : console.log;
      fn('[FBDiag]', line);
      // 自動寫到面板(若已建立)
      _fbDiagPaint();
    }catch(_){}
  };
  function _fbDiagPaint(){
    try{
      const el = document.getElementById('_fb-diag-panel');
      if(!el) return;
      const body = el.querySelector('._fb-diag-body');
      if(!body) return;
      body.innerHTML = window._fbDiagLogs.map(o => {
        const c = (o.level === 'error') ? '#ff8866'
                : (o.level === 'warn')  ? '#ffcc44' : '#88dd88';
        return `<div style="color:${c};font-family:monospace;font-size:11px;line-height:1.4;border-bottom:1px solid #333;padding:2px 0;word-break:break-all;">${o.line.replace(/[<>&]/g, c=>({ '<':'&lt;','>':'&gt;','&':'&amp;' }[c]))}</div>`;
      }).join('');
      // 自動捲到最底
      body.scrollTop = body.scrollHeight;
    }catch(_){}
  }
  window._fbShowDiag = function(){
    try{
      let el = document.getElementById('_fb-diag-panel');
      if(!el){
        el = document.createElement('div');
        el.id = '_fb-diag-panel';
        el.style.cssText = 'position:fixed;right:8px;bottom:8px;width:min(420px,92vw);max-height:60vh;'
          + 'background:rgba(0,0,0,0.92);border:2px solid #4488ff;border-radius:10px;z-index:99999;'
          + 'box-shadow:0 4px 24px rgba(0,0,0,0.6);display:flex;flex-direction:column;overflow:hidden;';
        el.innerHTML = `
          <div style="display:flex;align-items:center;gap:6px;padding:6px 10px;background:#1a3a6b;color:#cfe7ff;font-weight:700;font-size:13px;">
            🔍 登入診斷面板
            <span style="flex:1"></span>
            <button id="_fb-diag-copy" style="background:#2a5aa0;color:#fff;border:0;border-radius:4px;padding:3px 8px;font-size:12px;cursor:pointer;">複製</button>
            <button id="_fb-diag-close" style="background:#6a2a2a;color:#fff;border:0;border-radius:4px;padding:3px 8px;font-size:12px;cursor:pointer;">關閉</button>
          </div>
          <div class="_fb-diag-body" style="flex:1;overflow-y:auto;padding:6px 8px;background:#0a0a0a;"></div>`;
        document.body.appendChild(el);
        el.querySelector('#_fb-diag-close').onclick = () => el.remove();
        el.querySelector('#_fb-diag-copy').onclick = () => {
          const txt = window._fbDiagLogs.map(o => o.line).join('\n');
          try{
            if(navigator.clipboard && navigator.clipboard.writeText){
              navigator.clipboard.writeText(txt).then(
                () => { el.querySelector('#_fb-diag-copy').textContent = '✓ 已複製'; },
                () => { _fbDiagFallbackCopy(txt, el); }
              );
            }else{ _fbDiagFallbackCopy(txt, el); }
          }catch(_){ _fbDiagFallbackCopy(txt, el); }
        };
      }
      _fbDiagPaint();
    }catch(_){}
  };
  function _fbDiagFallbackCopy(txt, el){
    try{
      const ta = document.createElement('textarea');
      ta.value = txt;
      ta.style.cssText = 'position:fixed;top:-1000px;left:0;';
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
      if(el) el.querySelector('#_fb-diag-copy').textContent = '✓ 已複製';
    }catch(_){}
  }

  _fbDiag('boot:_fbApp 已建立, UA=' + (navigator.userAgent || '').slice(0, 80));
  // ★ FIX 20260517(gg) — 印 URL/origin/authDomain,協助診斷 redirect 回不來
