          const _existMaxLv = Math.max(0, ...Object.values(_existHL).filter(v => typeof v === 'number'));
          const _newHL = data.heroLevels || {};
          const _newUnlocked = Array.isArray(data.unlockedHeroes) ? data.unlockedHeroes.length : 0;
          const _newMaxLv = Math.max(0, ...Object.values(_newHL).filter(v => typeof v === 'number'));
          // 大幅倒退 → 拒絕
