  // ══════════════════════════════════════════════════════════════════
  // ★ v3.5.0 — 下載安裝授權管理(管理員批准制)
  // ──────────────────────────────────────────────────────────────────
  // 設計:
  //   1. 玩家「下載安裝完整遊戲」按鈕預設不顯示
  //   2. 玩家可透過「向管理員申請下載權限」按鈕送出申請(寫入 downloadPermissions/{uid})
  //   3. 管理員在後台批准 → status='approved' + grantedAt + expiresAt(24小時後)
  //   4. 玩家畫面 onSnapshot 監聽自己的權限文件,獲批後按鈕自動顯示
  //   5. 24小時後到期 → 自動失效(讀取時驗證 expiresAt)
  //
  // 資料結構: downloadPermissions/{uid}
  //   { uid, email, displayName, status, requestedAt, grantedAt, grantedBy,
  //     expiresAt, revokedAt, revokedBy, note }
  //
  // status 列舉:
  //   - 'pending'  : 玩家已申請,等待管理員批准
  //   - 'approved' : 管理員已批准,在 expiresAt 之前可下載
  //   - 'expired'  : 過期(此狀態由 client 端 lazy 判斷,不主動寫入)
  //   - 'revoked'  : 管理員手動撤銷
  // ══════════════════════════════════════════════════════════════════

  // ★★ v5.143.0（老師裁定 2026-09-05「下載安裝改成自動進行下載免申請」）— 免申請單一開關 ★★
  //   true ⇒ 任何已登入玩家一律視為「已核准、永不過期」：
  //     ・_fbGetDownloadPermission／_fbWatchDownloadPermission 直接回合成的核准物件（零 Firestore 讀取、零寫入）
  //     ・既有所有消費點（下載按鈕顯示／_tryStartFullDownload 守門／_showPwaGuide 守門／維修模式保留登入／
  //       bootPWA 放行三條件／登入後 3.5 秒自動 boot）全部**自動**走「已核准」分支，一行不必改
  //     ・「📩 申請下載權限」鈕因狀態恆為 approved 自然隱藏；到期提醒不排程
  //   false ⇒ 完整退回 v3.5.0 管理員批准制（後台「⬇️ 下載安裝權限」卡與後端函式全部保留，可隨時切回）。
  //   ⚠ 流量提醒：v3.5.17 批准制的初衷是「老師一台一台核准＝一台一台裝」避免 26 台同時撞校網 NAT；
  //     改自動後，同一節課同時首次登入的裝置會同時開始預載（各約 43MB）。
  window._LXPS_DL_PERM_FREE = true;
  // ★ v5.143.0 老師更正（2026-09-05）：免申請 ≠ 啟動時自動下載。
  //   true ⇒ 免申請合成的核准（_auto:true）**只讓「⬇️ 下載安裝」按鈕出現**，不觸發任何自動預載：
  //     ・bootPWA 不把 _auto 核准算進放行條件（沒裝過的裝置維持 sw-light 輕量模式）
  //     ・登入 3.5 秒自動 boot／權限監聽「剛核准就 boot」兩條自動路徑對 _auto 核准一律跳過
  //     ・只有玩家按下「⬇️ 下載安裝」→ _tryStartFullDownload 設 window._lxpsManualDownloadStart=true → 才 boot 完整 PWA 並開始預載
  //   已裝過的裝置（INSTALLED_KEY 有值）維持既有「背景補抓」行為不受影響。
  window._LXPS_DL_MANUAL_ONLY = true;
  window._lxpsManualDownloadStart = false;
  window._lxpsAutoDlPerm = function(uid){
    var _exp = Date.now() + 3650 * 86400000;   // 十年，實質永不過期
    return { uid: uid, status: 'approved', expiresAt: _exp, remainingMs: _exp - Date.now(), grantedBy: 'auto', _auto: true };
  };

  // 玩家送出下載權限申請
  window._fbRequestDownloadPermission = async function(uid, email, displayName){
    if(!uid){ console.warn('[下載授權] uid 為空,跳過'); return false; }
    try {
      const _now = Date.now();
      // 用 setDoc(merge) — 若已存在 pending/approved 也不破壞既有資料
      // 若先前是 revoked/expired,這次重新申請會把 status 改回 pending
      await setDoc(doc(_fbDb, 'downloadPermissions', uid), {
        uid: uid,
        email: (email || '').toLowerCase(),
        displayName: displayName || '',
        status: 'pending',
        requestedAt: _now,
        // 不動既有 grantedAt/expiresAt — 留給管理員批准時覆寫
      }, { merge: true });
      console.log('[下載授權] 已送出申請,uid=' + uid);
      return true;
    } catch(e){
      console.error('[下載授權] 申請寫入失敗', e);
      return false;
    }
  };

  // 取得單一玩家的下載權限狀態(含過期自動判定)
  // 回傳: { status, grantedAt, expiresAt, remainingMs, ... } 或 null(無申請紀錄)
  window._fbGetDownloadPermission = async function(uid){
    if(!uid) return null;
    if(window._LXPS_DL_PERM_FREE === true) return window._lxpsAutoDlPerm(uid);   // ★ v5.143.0 免申請
    try {
      const snap = await getDoc(doc(_fbDb, 'downloadPermissions', uid));
      if(!snap.exists()) return null;
      const d = snap.data();
      // 判斷是否過期(approved 但 expiresAt 已過)
      if(d.status === 'approved' && d.expiresAt && d.expiresAt < Date.now()){
        d.status = 'expired';
        d.remainingMs = 0;
      } else if(d.status === 'approved' && d.expiresAt){
        d.remainingMs = Math.max(0, d.expiresAt - Date.now());
      }
      return d;
    } catch(e){
      console.warn('[下載授權] 讀取失敗', e);
      return null;
    }
  };

  // 即時監聽單一玩家的下載權限變化(玩家自己用)
  // 回傳一個 unsubscribe 函式
  window._fbWatchDownloadPermission = function(uid, onChange){
    if(!uid) return () => {};
    if(window._LXPS_DL_PERM_FREE === true){   // ★ v5.143.0 免申請：不開 onSnapshot，直接回一次核准
      try{ setTimeout(function(){ try{ onChange(window._lxpsAutoDlPerm(uid)); }catch(_e){} }, 0); }catch(_){}
      return () => {};
    }
    return onSnapshot(
      doc(_fbDb, 'downloadPermissions', uid),
      (snap) => {
        if(!snap.exists()){ onChange(null); return; }
        const d = snap.data();
        if(d.status === 'approved' && d.expiresAt && d.expiresAt < Date.now()){
          d.status = 'expired';
          d.remainingMs = 0;
        } else if(d.status === 'approved' && d.expiresAt){
          d.remainingMs = Math.max(0, d.expiresAt - Date.now());
        }
        onChange(d);
      },
      (err) => { console.warn('[下載授權] 監聽失敗', err); }
    );
  };

  // 管理員批准下載權限(預設 24 小時有效)
  window._fbGrantDownloadPermission = async function(targetUid, adminEmail, hours, note){
    if(!targetUid){ throw new Error('targetUid 必填'); }
    const _hours = (typeof hours === 'number' && hours > 0) ? hours : 24;
    const _now = Date.now();
    const _expires = _now + _hours * 3600 * 1000;
    await setDoc(doc(_fbDb, 'downloadPermissions', targetUid), {
      status: 'approved',
      grantedAt: _now,
      grantedBy: adminEmail || 'unknown',
      expiresAt: _expires,
      note: note || '',
    }, { merge: true });
    console.log('[下載授權] 已批准,uid=' + targetUid + ',到期=' + new Date(_expires).toLocaleString());
    return _expires;
  };

  // 管理員撤銷下載權限
  window._fbRevokeDownloadPermission = async function(targetUid, adminEmail, reason){
    if(!targetUid){ throw new Error('targetUid 必填'); }
    await setDoc(doc(_fbDb, 'downloadPermissions', targetUid), {
      status: 'revoked',
      revokedAt: Date.now(),
      revokedBy: adminEmail || 'unknown',
      note: reason || '',
    }, { merge: true });
    console.log('[下載授權] 已撤銷,uid=' + targetUid);
    return true;
  };

  // 取得全部下載權限紀錄(管理員面板用)
  window._fbListDownloadPermissions = async function(){
    try {
      const snap = await getDocs(collection(_fbDb, 'downloadPermissions'));
      const _now = Date.now();
      const _list = [];
      snap.forEach(d => {
        const _data = d.data();
        // 自動標記過期(不寫回 Firestore,只在回傳時加註)
        if(_data.status === 'approved' && _data.expiresAt && _data.expiresAt < _now){
          _data._displayStatus = 'expired';
        } else {
          _data._displayStatus = _data.status;
        }
        _list.push(_data);
      });
      // 排序:pending 在最前,然後 approved,再然後其他;同類別按 requestedAt 倒序
      const _rank = { pending: 0, approved: 1, expired: 2, revoked: 3 };
      _list.sort((a, b) => {
        const _ra = _rank[a._displayStatus] ?? 9;
        const _rb = _rank[b._displayStatus] ?? 9;
        if(_ra !== _rb) return _ra - _rb;
        return (b.requestedAt || 0) - (a.requestedAt || 0);
      });
      return _list;
    } catch(e){
      console.error('[下載授權] 列表讀取失敗', e);
      throw e;
    }
  };

  // 即時監聽所有下載權限紀錄(管理員面板用)
  window._fbWatchAllDownloadPermissions = function(onChange){
    return onSnapshot(
      collection(_fbDb, 'downloadPermissions'),
      (snap) => {
        const _now = Date.now();
        const _list = [];
        snap.forEach(d => {
          const _data = d.data();
          if(_data.status === 'approved' && _data.expiresAt && _data.expiresAt < _now){
            _data._displayStatus = 'expired';
          } else {
            _data._displayStatus = _data.status;
          }
          _list.push(_data);
        });
        const _rank = { pending: 0, approved: 1, expired: 2, revoked: 3 };
        _list.sort((a, b) => {
          const _ra = _rank[a._displayStatus] ?? 9;
          const _rb = _rank[b._displayStatus] ?? 9;
          if(_ra !== _rb) return _ra - _rb;
          return (b.requestedAt || 0) - (a.requestedAt || 0);
        });
        onChange(_list);
      },
      (err) => console.warn('[下載授權] 列表監聽失敗', err)
    );
  };

  // ══════════════════════════════════════════════════════════════════
  // ★ v3.15.6(2026-06-14) — 畢業帳號資料轉移(實名制 GM 審核)後端 API
  // ──────────────────────────────────────────────────────────────────
  // 學生端:_fbSubmitAccountTransferRequest / _fbGetMyAccountTransferRequest
  // GM 端:_fbListAccountTransferRequests / _fbMigrateAccountData /
  //        _fbBackupNewAccountBeforeMigration / _fbRestoreNewAccountPreMigration /
  //        _fbAccountSnapshot / _fbResolveAccountTransfer
  // 安全核心(老師需求「回不去舊帳號」的後路):
  //   ① 遷移只「讀舊、寫新」,絕不改舊帳號 → 舊資料永遠是可重搬的「母本」
  //   ② 停權舊帳號是「最後一步」,且由 GM 端在複製驗證成功後才執行
  //   ③ 覆蓋新帳號前先備份(_premig_*),可一鍵還原
  // ══════════════════════════════════════════════════════════════════
  window._fbSubmitAccountTransferRequest = async function(newUid, newEmail, payload){
    if(!newUid){ console.warn('[帳號轉移] uid 為空,跳過'); return false; }
    payload = payload || {};
    try{
      await setDoc(doc(_fbDb, 'accountTransferRequests', newUid), {
        newUid: newUid,
        newEmail: (newEmail || '').toLowerCase(),
        realName: payload.realName || '',
        gradYear: payload.gradYear || '',
        classSeat: payload.classSeat || '',
        oldEmail: (payload.oldEmail || '').toLowerCase(),
        status: 'pending',
        createdAt: Date.now()
      }, { merge: true });
      console.log('[帳號轉移] 已送出申請,newUid=' + newUid);
      return true;
    }catch(e){ console.error('[帳號轉移] 申請寫入失敗', e); return false; }
  };

  window._fbGetMyAccountTransferRequest = async function(uid){
    if(!uid) return null;
    try{ const s = await getDoc(doc(_fbDb, 'accountTransferRequests', uid)); return s.exists() ? s.data() : null; }
    catch(e){ console.warn('[帳號轉移] 讀自己申請失敗', e); return null; }
  };

  window._fbListAccountTransferRequests = async function(){
    try{
      const snap = await getDocs(collection(_fbDb, 'accountTransferRequests'));
      const out = []; snap.forEach(d => out.push(Object.assign({ id: d.id }, d.data())));
      out.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      return out;
    }catch(e){ console.error('[帳號轉移] 列表失敗', e); return []; }
  };

  // 讀某帳號關鍵指標(供 GM 比較新舊進度;對應覆蓋保護)
  window._fbAccountSnapshot = async function(uid){
    try{
      const p = await getDoc(doc(_fbDb, 'players', uid));
      if(!p.exists()) return { exists: false };
      const d = p.data();
      const _hl = d.heroLevels || {};
      const _unlocked = (Array.isArray(d.unlockedHeroes) && d.unlockedHeroes.length) || Object.keys(_hl).length || 0;
      let _maxLv = 0, _totalLv = 0;
      for(const k in _hl){ const v = _hl[k] || 0; _totalLv += v; if(v > _maxLv) _maxLv = v; }
      const _coins = (typeof d.knowledgeCoins === 'number') ? d.knowledgeCoins
                   : (typeof d.coins === 'number' ? d.coins : 0);
      return { exists: true, coins: _coins, unlocked: _unlocked, maxLv: _maxLv, totalLv: _totalLv,
               displayName: d.displayName || '', suspended: !!d._suspended };
    }catch(e){ return { exists: false, error: String(e) }; }
  };

  // 遷移前備份新帳號(players 主檔 + saves/live + saves/safe → _premig_* 備份槽)
  window._fbBackupNewAccountBeforeMigration = async function(newUid){
    if(!newUid) throw new Error('newUid 必填');
    try{ const p = await getDoc(doc(_fbDb, 'players', newUid));
         if(p.exists()) await setDoc(doc(_fbDb, 'players', newUid, 'saves', '_premig_main'), p.data()); }catch(_){}
    const _bk = async (slot, dest) => {
      try{ const s = await getDoc(doc(_fbDb, 'players', newUid, 'saves', slot));
           if(s.exists()) await setDoc(doc(_fbDb, 'players', newUid, 'saves', dest), s.data()); }catch(_){}
    };
    await _bk('live', '_premig_live');
    await _bk('safe', '_premig_safe');
    console.log('[帳號轉移] 已備份新帳號遷移前狀態,newUid=' + newUid);
    return true;
  };

  // 還原新帳號到遷移前(把 _premig_* 備份寫回 players 主檔 + saves)
  window._fbRestoreNewAccountPreMigration = async function(newUid){
    if(!newUid) throw new Error('newUid 必填');
    let _n = 0;
    try{ const m = await getDoc(doc(_fbDb, 'players', newUid, 'saves', '_premig_main'));
         if(m.exists()){ await setDoc(doc(_fbDb, 'players', newUid), m.data()); _n++; } }catch(_){}
    const _rs = async (src, slot) => {
      try{ const s = await getDoc(doc(_fbDb, 'players', newUid, 'saves', src));
           if(s.exists()){ await setDoc(doc(_fbDb, 'players', newUid, 'saves', slot), s.data()); _n++; } }catch(_){}
    };
    await _rs('_premig_live', 'live');
    await _rs('_premig_safe', 'safe');
    console.log('[帳號轉移] 已還原新帳號到遷移前,newUid=' + newUid + ',還原 ' + _n + ' 份');
    return _n;
  };

  // 核心遷移:複製舊 uid → 新 uid(全搬:players 主檔 + saves/live + saves/safe + arenaTeams + wbDamageDetail)
  //   ★ 只讀舊、寫新,絕不改舊帳號(母本永久保留)。回傳各項複製結果供 GM 驗證。
  window._fbMigrateAccountData = async function(oldUid, newUid){
    if(!oldUid || !newUid) throw new Error('oldUid / newUid 必填');
    if(oldUid === newUid) throw new Error('新舊 uid 相同,無需遷移');
    const _r = { playersDoc: false, saveLive: false, saveSafe: false, arenaTeams: false, wbDamage: false };
    // 1) players 主檔(整份複製到新 uid)
    const _oldP = await getDoc(doc(_fbDb, 'players', oldUid));
    if(!_oldP.exists()) throw new Error('舊帳號 players 主檔不存在(oldUid 可能有誤)');
    // ★ v3.15.18(2026-06-16) 修「新帳號無法登入」根因 ──────────────────────────
    //   主檔整份複製會把舊帳號的「帳號控管 / 連線 session」欄位也一起搬進新帳號。
    //   本核准流程「最後一步」會停權舊帳號;若舊帳號在「複製這一刻」就已是停權狀態
    //   (例:重跑遷移→第一次已把舊帳號停權;或畢業帳號早被停權),則 _suspended=true
    //   會被原封不動帶進新帳號 → 新帳號一誕生就被「登入停權閘門」(_suspended===true)
    //   擋下,顯示「🚫 帳號暫停存取」,學生回報「無法用新帳號登入」。
    //   修法:遷移只搬「遊戲進度」,主動剝除「停權 6 欄位 + 連線 session 2 欄位」。
    //   → 新帳號永遠以「未停權」誕生;session 由新帳號自己重建(_fbCreateSession 會覆寫)。
    const _srcData = _oldP.data();
    ['_suspended', '_suspendedAt', '_suspendedBy', '_suspendReason',
     '_unsuspendedAt', '_unsuspendedBy',
     'activeSession', 'sessionAt'].forEach(function(k){ delete _srcData[k]; });
    // ★ v3.16.61 — 修「轉移後新帳號無法登入」殘留根因:存檔內含 ownerUid(這份存檔屬於哪個 uid)。
    //   遷移整份複製會把舊帳號的 ownerUid 一起搬進新帳號 → 新帳號登入時 gameCloudLoad 的 Layer B
    //   發現 data.ownerUid(舊uid)≠ 現在登入 uid(新uid)→ 判定「外來資料」拒絕套用 → 卡「載入失敗」視窗。
    //   修法:把新帳號主檔 + 兩槽存檔的 ownerUid 一律改寫成新 uid(只讀舊寫新,不碰母本)。
    _srcData.ownerUid = newUid;
    await setDoc(doc(_fbDb, 'players', newUid), _srcData);
    _r.playersDoc = true;
    // 2) saves/live + saves/safe(同步把槽內 ownerUid 改成新 uid,否則三槽合併後 Layer B 仍會擋)
    const _copySlot = async (slot, key) => {
      const s = await getDoc(doc(_fbDb, 'players', oldUid, 'saves', slot));
      if(s.exists()){
        const _slotData = Object.assign({}, s.data(), { ownerUid: newUid });
        await setDoc(doc(_fbDb, 'players', newUid, 'saves', slot), _slotData); _r[key] = true;
      }
    };
    await _copySlot('live', 'saveLive');
    await _copySlot('safe', 'saveSafe');
    // 3) arenaTeams/{uid}(改 uid 欄為新 uid)
    try{ const a = await getDoc(doc(_fbDb, 'arenaTeams', oldUid));
         if(a.exists()){ const _d = Object.assign({}, a.data(), { uid: newUid }); await setDoc(doc(_fbDb, 'arenaTeams', newUid), _d); _r.arenaTeams = true; } }catch(_){}
    // 4) wbDamageDetail/{uid}(改 uid 欄為新 uid)
    try{ const w = await getDoc(doc(_fbDb, 'wbDamageDetail', oldUid));
         if(w.exists()){ const _d = Object.assign({}, w.data(), { uid: newUid }); await setDoc(doc(_fbDb, 'wbDamageDetail', newUid), _d); _r.wbDamage = true; } }catch(_){}
    console.log('[帳號轉移] 遷移完成 oldUid=' + oldUid + ' → newUid=' + newUid, _r);
    return _r;
  };

  // GM 標記轉移結果(approved/rejected + 中繼資料)
  window._fbResolveAccountTransfer = async function(newUid, status, extra){
    if(!newUid) throw new Error('newUid 必填');
    extra = extra || {};
    const _patch = { status: status, resolvedAt: Date.now(),
                     resolvedBy: (_fbAuth.currentUser && _fbAuth.currentUser.email) || 'unknown' };
    if(extra.oldUid) _patch.oldUid = extra.oldUid;
    if(extra.migratedAt) _patch.migratedAt = extra.migratedAt;
    if(typeof extra.gmNote === 'string') _patch.gmNote = extra.gmNote;
    await setDoc(doc(_fbDb, 'accountTransferRequests', newUid), _patch, { merge: true });
    return true;
  };

  window._fbDeleteAccountTransferRequest = async function(newUid){
    if(!newUid) throw new Error('newUid 必填');
    await deleteDoc(doc(_fbDb, 'accountTransferRequests', newUid));
    return true;
  };

  // ══════════════════════════════════════════════════════════════════
  // ★ v3.15.99(2026-06-24)— 小英雄會員資料(首次登入建立 + 可編輯同步雲端)
  // ──────────────────────────────────────────────────────────────────
  // 情境:
  //   玩家首次登入(memberProfileComplete 未設)→ 關卡頁自動彈「會員資料建立」,
  //   填妥 7 欄位送出 → 寫 players/{自己uid} 三個欄位:
  //     memberProfile(資料本體)、memberProfileComplete:true(關閉再彈)、
  //     memberProfileRewarded:true(一次性獎勵守門)。
  //   之後可在關卡頁「會員帳號與救援申請」→「編輯會員資料」隨時改(不再發獎)。
  //   GM 後台讀 players/{uid}.memberProfile 即可統計/辨識玩家身分。
  //
  // ★ 安全 / 規則:
  //   - 資料寫進玩家「自己的」players/{uid}(非新集合),走既有
  //     「玩家自己 + 不寫停權欄位」update 規則,memberProfile 三欄皆非停權欄位,
  //     → 自動放行,「無需新增 firestore.rules」。
  //   - 一次性獎勵(水晶/幣/SSR券)由 memberProfileRewarded 守門:送出前讀雲端
  //     現值,已 rewarded 則絕不重發(編輯既有資料也不會再發)。旗標先寫雲端、
  //     再本地發獎+存檔 → at-most-once(寧可極端網路失敗時少發、由 GM 補,
  //     也不重複發,呼應帳號救援「不採信前端、杜絕刷資源」精神)。
  //   - 會員暱稱(nickname)是「GM 專用識別欄位」,與遊戲內公開暱稱
  //     (window._playerNickname,排行榜會遮罩)無關,不對其他玩家顯示。
  // ══════════════════════════════════════════════════════════════════
  // 玩家身分(可複選)
  window._MEMBER_IDENTITY_OPTS = [
    '力行國小學生', '力行國小教師/職員', '力行國小學生家長', '力行國小志工',
    '力行國小畢業校友', '外校學生', '外校教師/職員', '外校學生家長',
    '教育界夥伴', '遊戲產業專家', '社會人士'
  ];
  // 在學就讀年級(選填;第一項空字串=未選/不適用)
  window._MEMBER_GRADE_OPTS = [
    '', '幼兒園',
    '國小一年級', '國小二年級', '國小三年級', '國小四年級', '國小五年級', '國小六年級',
    '國中一年級', '國中二年級', '國中三年級',
    '高中/職一年級', '高中/職二年級', '高中/職三年級',
    '大學一年級', '大學二年級', '大學三年級', '大學四年級',
    '研究所', '博士班'
  ];
  // 真實性別(必填)
  window._MEMBER_GENDER_OPTS = ['男', '女', '保密'];
  // 主要遊玩平台(可複選)
