  // ════════════════════════════════════════════════════════════════════
  // ★ v4.7.0(2026-07-04)新增 — GM「🐾 寵物紀錄」查詢 + 「🎁 指定補發寵物」
  //   對應 admin_panel.js v4.7.0 玩家活動記錄查詢卡的「🐾 寵物紀錄」鈕。
  //   ① _fbShowPlayerPetRecords(emailOrUid):反查 uid(比照召喚紀錄:email /
  //      lsps學號 / uid)→ getDocFromServer 讀 players/{uid} 權威主檔 +
  //      ticketLedger/{uid} → GM 彈窗:馴養總覽(N/28·稀有度分佈)/寵物明細
  //      (Lv/EXP/好感/跟隨)/互動累計(餵對/撫摸/玩耍勝·讀 medalStats)/
  //      寵物獎章 14 枚/馴養帳本(來源+uid12·自動紅底標「⚠非本人 uid」=
  //      共用平板污染線索)/寵物券帳本(領用+抽到哪隻)。唯讀不寫,零風險。
  //   ② _fbAdminGrantPetToPlayer(uid, petName, lv):彈窗底部指定補發。
  //      比照英雄 admin_grant 補發哲學:只增不減(已馴養者僅取 max(lv)·
  //      絕不降級·不動好感/跟隨/EXP 較高值)、主檔必寫 + saves/live·safe
  //      「存在才」同寫(三槽載入對 tamedPets 是跨槽 union → 主檔寫入即
  //      數學上充分;不創建殘缺槽 doc)、map+_s 雙寫(載入 _s 優先,漏寫 _s
  //      會被舊字串蓋回=補發隱形)、馴養帳本補一筆 src:'admin_grant'
  //      (帶 uid12+by=合法來源佐證)、petsEverCollected 一併 union(圖鑑
  //      收錄)、寄登入彈窗通知玩家(pendingAdminNotifications 既有路徑)。
  //   ⚠ 玩家「在線中」補發存在與英雄補發同型的整包覆寫 race → 建議玩家
  //      離線時操作;union 載入 + 三槽同寫已把風險壓到最低。
  //   Firestore 權限:isAdmin 對 players/{uid}+saves 全權(既有規則),
  //      ticketLedger GM 可讀(需部署 firestore.rules;未部署顯示提示)。
  // ════════════════════════════════════════════════════════════════════
  window._fbReadPlayerPetRecords = async function(emailOrUid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    const _raw = String(emailOrUid || '').trim();
    if(!_raw) throw new Error('請提供 email 或 uid');
    let _uid = '', _email = '', _byEmail = '';
    if(_raw.indexOf('@') >= 0){ _byEmail = _raw.toLowerCase(); }
    else if(/^lsps\d+$/i.test(_raw)){ _byEmail = _raw.toLowerCase() + '@stu.lsps.tp.edu.tw'; }
    if(_byEmail){
      _email = _byEmail;
      const _q = query(collection(_fbDb, 'players'), where('email', '==', _email));
      const _snap = await getDocs(_q);
      if(_snap.empty) throw new Error('查無此玩家:' + _email);
      _snap.forEach(function(d){ if(!_uid) _uid = d.id; });
    } else {
      _uid = _raw;
    }
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _mainSnap = await _gds(doc(_fbDb, 'players', _uid));
    const _mainEx = (typeof _mainSnap.exists === 'function') ? _mainSnap.exists() : !!_mainSnap.exists;
    if(!_mainEx) throw new Error('查無此玩家 doc:' + _uid);
    const _d = _mainSnap.data() || {};
    if(!_email) _email = _d.email || '';
    // ── 各欄位取值口徑與 _applySafeData 完全一致:_s 字串優先,fallback map ──
    const _fromS = function(sKey, mKey, isArr){
      let v = null;
      if(typeof _d[sKey] === 'string'){ try{ const p = JSON.parse(_d[sKey]); if(p && (isArr ? Array.isArray(p) : (typeof p === 'object'))) v = p; }catch(_){} }
      if(!v && _d[mKey] && (isArr ? Array.isArray(_d[mKey]) : (typeof _d[mKey] === 'object'))) v = _d[mKey];
      return v || (isArr ? [] : {});
    };
    const _pets  = _fromS('tamedPets_s', 'tamedPets', false);
    const _hist  = _fromS('_petTameHistory_s', '_petTameHistory', true);
    const _stats = _fromS('medalStats_s', 'medalStats', false);
    const _daily = _fromS('petHouseDaily_s', 'petHouseDaily', false);
    let _slots = null;
    if(typeof _d.petHouseSlots_s === 'string'){ try{ const _hs = JSON.parse(_d.petHouseSlots_s); if(Array.isArray(_hs)) _slots = _hs; }catch(_){} }
    if(!_slots && Array.isArray(_d.petHouseSlots)) _slots = _d.petHouseSlots;
    _slots = _slots || [null, null, null];
    const _pMedals = (_d.playerMedals && typeof _d.playerMedals === 'object') ? _d.playerMedals : {};
    // 寵物券帳本(規則未部署/讀失敗 → null,前端顯示提示;無資料 → 空陣列)
    let _ledger = null;
    try{
      const _lSnap = await _gds(doc(_fbDb, 'ticketLedger', _uid));
      const _lEx = (typeof _lSnap.exists === 'function') ? _lSnap.exists() : !!_lSnap.exists;
      if(_lEx){
        const _ld = _lSnap.data() || {};
        _ledger = (Array.isArray(_ld.list) ? _ld.list : []).filter(function(e){ return e && typeof e.item === 'string' && e.item.indexOf('pet_') === 0; });
      } else { _ledger = []; }
    }catch(_eL){ _ledger = null; }
    return { uid:_uid, email:_email, pets:_pets, hist:_hist, stats:_stats, daily:_daily, slots:_slots, medals:_pMedals, ledger:_ledger };
  };

  window._fbShowPlayerPetRecords = async function(emailOrUid){
    let _data;
    try{ _data = await window._fbReadPlayerPetRecords(emailOrUid); }
    catch(e){ try{ alert('查詢失敗:' + (e && e.message ? e.message : e)); }catch(_){} return; }
    const _esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
    const _old = document.getElementById('_gm-pet-records-popup');
    if(_old) _old.remove();
    const _R = window.PET_RARITY || {};
    const _allPets = Object.keys(_R);
    const _rOrder = { SSR:0, SR:1, R:2 };
    const _rCol = { SSR:'#ffd33b', SR:'#b48cff', R:'#8fd0ff' };
    const _icoOf = function(pn){
      try{
        const eq = (typeof CARRY_PET_DB !== 'undefined') ? CARRY_PET_DB.find(function(e){ return (e.pet || e.n) === pn; }) : null;
        return (eq && eq.icon) || '🐾';
      }catch(_){ return '🐾'; }
    };
    const _byRarity = function(a, b){
      const ra = (_rOrder[_R[a]] !== undefined) ? _rOrder[_R[a]] : 9;
      const rb = (_rOrder[_R[b]] !== undefined) ? _rOrder[_R[b]] : 9;
      return (ra - rb) || a.localeCompare(b, 'zh-Hant');
    };
    const _pets = _data.pets || {};
    const _tamedNames = Object.keys(_pets);
    let _cSSR = 0, _cSR = 0, _cR = 0, _tSSR = 0, _tSR = 0, _tR = 0;
    _allPets.forEach(function(pn){
      const r = _R[pn];
      if(r === 'SSR'){ _tSSR++; if(_pets[pn]) _cSSR++; }
      else if(r === 'SR'){ _tSR++; if(_pets[pn]) _cSR++; }
      else { _tR++; if(_pets[pn]) _cR++; }
    });
    const _st = _data.stats || {};
    const _feed = Number(_st.petFeedOk) || 0, _pat = Number(_st.petPat) || 0, _win = Number(_st.petPlayWin) || 0;
    const _petMedalIds = ['pet_tame_first','pet_tame_7','pet_tame_14','pet_tame_10','pet_tame_20','pet_tame_30','pet_tame_all','pet_tame_ssr_all','pet_lv20_first','pet_aff_100_first','pet_feed_20','pet_pat_20','pet_play_first','pet_play_20','pet_memory_fast','pet_hide_5click','pet_burst_first'];
    const _defOf = function(id){
      try{
        if(typeof MEDAL_DEFS !== 'undefined'){
          const m = MEDAL_DEFS.find(function(x){ return x.id === id; });
          if(m) return m;
        }
      }catch(_){}
      return { icon:'🏅', name:id };
    };
    let _mGot = 0, _mChips = '';
    _petMedalIds.forEach(function(id){
      const on = !!(_data.medals && _data.medals[id]);
      if(on) _mGot++;
      const m = _defOf(id);
      _mChips += '<span style="display:inline-block;margin:2px 3px;padding:2px 8px;border-radius:7px;font-size:13px;font-weight:700;'
        + (on ? 'background:rgba(255,211,59,0.14);border:1px solid rgba(255,211,59,0.55);color:#ffd33b;' : 'background:rgba(255,255,255,0.04);border:1px solid rgba(160,160,180,0.3);color:#77778a;')
        + '">' + m.icon + ' ' + _esc(m.name) + (on ? '' : '(未)') + '</span>';
    });
    const _srcLabel = function(src){
      return src === 'battle_tame' ? '戰鬥馴養'
        : src === 'pet_ticket' ? '寵物召喚卷'
        : src === 'summon' ? '召喚星空'
        : src === 'admin_grant' ? '老師補發'
        : _esc(src || '?');
    };
    // ★ v4.14.0 — 隨機素質分布(讀 rec.seed·retrainVer;缺 seed=legacy fallback hash(name))
    const _siStr = function(pn, rec){
      try{
        const b = (typeof window._petRandStatBonus === 'function') ? window._petRandStatBonus(pn, (rec.lv|0)||1, rec) : null;
        if(!b) return '—';
        return '體+' + (b.hp|0) + ' 攻+' + (b.atk|0) + ' 特+' + (b.sp|0) + ' 速+' + (b.spd|0);
      }catch(_){ return '—'; }
    };
    let _petRows = '';
    if(!_tamedNames.length){
      _petRows = '<div style="text-align:center;color:#9a9aac;padding:14px;font-size:15px;">尚未馴養任何寵物。</div>';
    } else {
      _tamedNames.slice().sort(_byRarity).forEach(function(pn){
        const rec = _pets[pn] || {};
        const r = _R[pn] || '?';
        const col = _rCol[r] || '#cfcfe6';
        _petRows += '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;border-top:1px solid rgba(140,220,180,0.15);padding:5px 2px;font-size:14px;">'
          + '<span style="min-width:150px;color:' + col + ';font-weight:800;">' + _icoOf(pn) + ' ' + _esc(pn) + ' <span style="font-size:11px;opacity:0.85;">[' + _esc(r) + ']</span></span>'
          + '<span style="color:#cfe8d8;">Lv.<b style="color:#fff;">' + ((rec.lv|0) || 1) + '</b></span>'
          + '<span style="color:#9ac0aa;font-size:12px;">EXP ' + ((rec.exp|0) || 0) + '/100</span>'
          + '<span style="color:#ff9ac0;">💖' + ((rec.aff|0) || 0) + '</span>'
          + '<span style="color:#a0b8ff;font-size:12px;">' + (rec.followTo ? ('跟隨:' + _esc(rec.followTo)) : '未跟隨') + '</span>'
          + '<span style="color:#d8b878;font-size:12px;width:100%;">🎲 隨機素質 ' + _siStr(pn, rec) + ' <span style="opacity:0.7;">(重擲 ' + ((rec.retrainVer|0)||0) + ' 次' + (typeof rec.seed === 'number' ? '' : '·legacy') + ')</span></span>'
          + '</div>';
      });
    }
    // 重置下拉:僅列「已馴養」寵物(重置需已馴養)
    let _resetOpts = '';
    _tamedNames.slice().sort(_byRarity).forEach(function(pn){
      const rec = _pets[pn] || {};
      _resetOpts += '<option value="' + _esc(pn) + '">[' + _esc(_R[pn] || '?') + '] ' + _esc(pn) + '(Lv.' + ((rec.lv|0) || 1) + ')</option>';
    });
    const _uid12 = String(_data.uid).slice(0, 12);
    let _histRows = '';
    const _histArr = Array.isArray(_data.hist) ? _data.hist.slice().reverse() : [];
    if(!_histArr.length){
      _histRows = '<div style="text-align:center;color:#9a9aac;padding:10px;font-size:14px;">(無馴養帳本紀錄)</div>';
    } else {
      _histArr.forEach(function(e){
        if(!e) return;
        const dt = new Date(e.at || 0);
        const ds = (dt.getMonth() + 1) + '/' + dt.getDate() + ' ' + String(dt.getHours()).padStart(2, '0') + ':' + String(dt.getMinutes()).padStart(2, '0');
        const foreign = !!(e.uid && _uid12 && e.uid !== _uid12);
        _histRows += '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:13px;border-top:1px solid rgba(140,220,180,0.12);padding:4px 2px;'
          + (foreign ? 'background:rgba(255,60,60,0.12);border-left:3px solid #ff5555;' : '')
          + '"><span style="color:#9ac0aa;min-width:88px;">🕐 ' + ds + '</span>'
          + '<span style="color:#eaffea;font-weight:700;">' + _icoOf(e.pet) + ' ' + _esc(e.pet) + '</span>'
          + '<span style="color:#ffd9a0;">' + _srcLabel(e.src) + (e.by ? ('・' + _esc(e.by)) : '') + '</span>'
          + '<span style="color:#8a9aac;font-size:11px;">uid:' + _esc(e.uid || '?') + '</span>'
          + (foreign ? '<span style="color:#ff8888;font-weight:800;font-size:12px;">⚠ 非本人 uid(共用裝置污染線索)</span>' : '')
          + '</div>';
      });
    }
    let _ledRows = '';
    if(_data.ledger === null){
      _ledRows = '<div style="color:#ffb080;font-size:13px;padding:6px 2px;">(讀取失敗:ticketLedger 規則可能尚未部署 → 見 firestore.rules;玩家本機帳本仍在記錄)</div>';
    } else if(!_data.ledger.length){
      _ledRows = '<div style="color:#9a9aac;font-size:13px;padding:6px 2px;">(無寵物券帳本紀錄)</div>';
    } else {
      _data.ledger.slice().reverse().forEach(function(e){
        const dt = new Date(e.at || 0);
        const ds = (dt.getMonth() + 1) + '/' + dt.getDate() + ' ' + String(dt.getHours()).padStart(2, '0') + ':' + String(dt.getMinutes()).padStart(2, '0');
        _ledRows += '<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:13px;border-top:1px solid rgba(180,160,255,0.12);padding:4px 2px;">'
          + '<span style="color:#9ac0aa;min-width:88px;">🕐 ' + ds + '</span>'
          + '<span style="color:' + (e.ev === 'use' ? '#ffd580' : '#a0ffc0') + ';font-weight:800;">' + (e.ev === 'use' ? '使用' : '獲得') + '</span>'
          + '<span style="color:#eaeaff;">' + _esc(e.item) + ((e.n|0) > 1 ? ' ×' + (e.n|0) : '') + '</span>'
          + (e.result ? '<span style="color:#cbb8ff;">→ ' + _esc(e.result) + '</span>' : '')
          + '</div>';
      });
    }
    let _dailyStr = '(今日尚無互動)';
    try{
      const _rec = (_data.daily && _data.daily.rec) || {};
      const _parts = [];
      Object.keys(_rec).forEach(function(pn){
        const r = _rec[pn] || {};
        const acts = [];
        if(r.pat) acts.push('撫摸');
        if(r.fed) acts.push('餵食');
        if(r.play) acts.push('玩耍');
        if(acts.length) _parts.push(_esc(pn) + '(' + acts.join('/') + ')');
      });
      if(_parts.length) _dailyStr = _esc((_data.daily && _data.daily.d) || '') + ':' + _parts.join('、');
      else if(_data.daily && _data.daily.d) _dailyStr = _esc(_data.daily.d) + ':(無)';
    }catch(_){}
    let _opts = '';
    _allPets.slice().sort(_byRarity).forEach(function(pn){
      const has = _pets[pn];
      _opts += '<option value="' + _esc(pn) + '">[' + _esc(_R[pn] || '?') + '] ' + _esc(pn) + (has ? '(已馴養 Lv.' + ((has.lv|0) || 1) + ')' : '') + '</option>';
    });
    const _pop = document.createElement('div');
    _pop.id = '_gm-pet-records-popup';
    _pop.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,6,4,0.8);backdrop-filter:blur(4px);padding:18px;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    _pop.innerHTML = '<div style="background:linear-gradient(160deg,rgba(12,32,22,0.98),rgba(18,46,32,0.98));border:2.5px solid rgba(140,230,180,0.8);border-radius:16px;padding:20px 22px;max-width:min(96vw,760px);max-height:92vh;overflow-y:auto;-webkit-overflow-scrolling:touch;box-shadow:0 10px 50px rgba(60,180,120,0.4);text-align:left;">'
      + '<div style="font-size:23px;font-weight:900;color:#c8ffdc;text-align:center;letter-spacing:2px;margin-bottom:4px;">🐾 玩家寵物紀錄(GM)</div>'
      + '<div style="font-size:13px;color:#9adcb4;text-align:center;margin-bottom:12px;word-break:break-all;">' + _esc(_data.email || '(無 email)') + ' ・ uid:' + _esc(_data.uid || '') + '</div>'
      + '<div style="background:rgba(0,16,8,0.4);border:1px solid rgba(120,255,180,0.3);border-radius:10px;padding:12px 14px;margin-bottom:12px;">'
        + '<div style="font-size:15px;color:#d8ffe8;">已馴養 <b style="color:#fff;font-size:18px;">' + _tamedNames.length + '</b> / ' + _allPets.length
        + '(SSR ' + _cSSR + '/' + _tSSR + '・SR ' + _cSR + '/' + _tSR + '・R ' + _cR + '/' + _tR + ')</div>'
        + '<div style="font-size:14px;color:#cfe8d8;margin-top:6px;">互動累計:🍽 餵對 <b>' + _feed + '</b>・🤚 撫摸 <b>' + _pat + '</b>・🎾 玩耍勝 <b>' + _win + '</b></div>'
        + '<div style="font-size:14px;color:#cfe8d8;margin-top:6px;">小屋入住:' + (_esc((_data.slots || []).filter(function(x){ return x; }).join('、')) || '(空)') + '</div>'
        + '<div style="font-size:14px;color:#cfe8d8;margin-top:6px;">今日互動:' + _dailyStr + '</div>'
      + '</div>'
      + '<div style="font-size:14px;color:#aef0c8;font-weight:800;margin:8px 0 3px;">🏅 寵物獎章(' + _mGot + '/14):</div><div style="margin-bottom:10px;">' + _mChips + '</div>'
      + '<div style="font-size:14px;color:#aef0c8;font-weight:800;margin:8px 0 3px;">🐾 已馴養寵物明細:</div>' + _petRows
      + '<div style="font-size:14px;color:#aef0c8;font-weight:800;margin:12px 0 3px;">📒 馴養帳本(新→舊,最多 200 筆;紅底=帳本 uid 非本人=共用裝置污染線索):</div>'
      + '<div style="max-height:220px;overflow-y:auto;border:1px solid rgba(140,220,180,0.2);border-radius:8px;padding:4px 8px;background:rgba(0,10,6,0.3);">' + _histRows + '</div>'
      + '<div style="font-size:14px;color:#aef0c8;font-weight:800;margin:12px 0 3px;">🎟️ 寵物券帳本(領用紀錄・→後面=抽到哪隻):</div>'
      + '<div style="max-height:160px;overflow-y:auto;border:1px solid rgba(180,160,255,0.2);border-radius:8px;padding:4px 8px;background:rgba(4,4,16,0.3);">' + _ledRows + '</div>'
      + '<div style="margin-top:14px;border:1.5px dashed rgba(255,210,120,0.6);border-radius:10px;padding:10px 12px;background:rgba(30,22,4,0.35);">'
        + '<div style="font-size:15px;color:#ffd9a0;font-weight:900;margin-bottom:6px;">🎁 指定補發寵物(GM)</div>'
        + '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">'
          + '<select id="_gm-pet-grant-sel" style="padding:7px 10px;font-size:14px;border-radius:8px;background:#0e2418;color:#eaffea;border:1px solid rgba(140,230,180,0.5);max-width:280px;">' + _opts + '</select>'
          + '<label style="font-size:13px;color:#cfe8d8;">Lv <input id="_gm-pet-grant-lv" type="number" min="1" max="20" value="1" style="width:64px;padding:6px;font-size:14px;border-radius:8px;background:#0e2418;color:#fff;border:1px solid rgba(140,230,180,0.5);"></label>'
          + '<button onclick="window._gmPetGrantClick(\'' + _esc(_data.uid) + '\')" style="padding:8px 18px;font-size:15px;font-weight:900;border-radius:9px;cursor:pointer;background:linear-gradient(135deg,#c8963c,#8a5f1a);border:1.5px solid rgba(255,220,140,0.7);color:#fff;">🎁 補發</button>'
        + '</div>'
        + '<div style="font-size:12px;color:#c0b090;margin-top:6px;line-height:1.5;">只增不減:已馴養者僅提升等級(取較大值),絕不降級、不動好感/跟隨;寫入馴養帳本 src=admin_grant(合法來源佐證)並寄登入通知給玩家。建議玩家「離線時」操作,避免整包存檔覆寫 race。</div>'
      + '</div>'
      + '<div style="margin-top:12px;border:1.5px dashed rgba(150,210,255,0.6);border-radius:10px;padding:10px 12px;background:rgba(6,20,32,0.4);">'
        + '<div style="font-size:15px;color:#a8d8ff;font-weight:900;margin-bottom:6px;">♻️ 重置寵物隨機素質(GM 補償)</div>'
        + (_tamedNames.length
            ? ('<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">'
                + '<select id="_gm-pet-reset-sel" style="padding:7px 10px;font-size:14px;border-radius:8px;background:#0e1e2e;color:#eaf4ff;border:1px solid rgba(150,210,255,0.5);max-width:280px;">' + _resetOpts + '</select>'
                + '<button onclick="window._gmPetResetClick(\'' + _esc(_data.uid) + '\')" style="padding:8px 18px;font-size:15px;font-weight:900;border-radius:9px;cursor:pointer;background:linear-gradient(135deg,#3c8ac8,#1a5f8a);border:1.5px solid rgba(140,210,255,0.7);color:#fff;">♻️ 重置</button>'
              + '</div>'
              + '<div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;margin-top:8px;font-size:13px;color:#cfe4f8;">'
                + '<label style="cursor:pointer;"><input type="radio" name="_gm-pet-reset-mode" value="reroll" checked style="vertical-align:middle;"> 🎲 重擲隨機素質<span style="color:#9ac0dd;">(等級/經驗/好感全保留)</span></label>'
                + '<label style="cursor:pointer;"><input type="radio" name="_gm-pet-reset-mode" value="full" style="vertical-align:middle;"> 🔄 完全重置<span style="color:#9ac0dd;">(退 Lv.1、經驗歸零、重擲素質;好感保留)</span></label>'
              + '</div>'
              + '<div style="font-size:12px;color:#90b0c0;margin-top:6px;line-height:1.5;">重擲=換一組隨機素質分配(乙案 seed);完全重置額外把等級退回 Lv.1。兩者皆保留好感度與跟隨對象,並三槽同寫(壓過舊高等紀錄)、寄登入通知給玩家。建議玩家「離線時」操作。</div>')
            : '<div style="font-size:13px;color:#90a0b0;">該玩家尚無已馴養寵物,無可重置對象。</div>')
      + '</div>'
      + '<div style="text-align:center;margin-top:14px;"><button onclick="document.getElementById(\'_gm-pet-records-popup\').remove()" style="padding:9px 30px;font-size:17px;font-weight:700;background:rgba(60,160,110,0.7);border:2px solid rgba(160,255,200,0.7);color:#fff;border-radius:9px;cursor:pointer;font-family:inherit;letter-spacing:2px;">關閉</button></div>'
      + '</div>';
    document.body.appendChild(_pop);
  };

  // 彈窗「🎁 補發」點擊入口(讀 select/Lv → confirm → 執行 → 重整彈窗)
  window._gmPetGrantClick = async function(uid){
    try{
      const _sel = document.getElementById('_gm-pet-grant-sel');
      const _lvEl = document.getElementById('_gm-pet-grant-lv');
      const _pn = _sel ? String(_sel.value || '') : '';
      let _lv = _lvEl ? parseInt(_lvEl.value, 10) : 1;
      if(!(_lv >= 1)) _lv = 1;
      if(_lv > 20) _lv = 20;
      if(!_pn){ alert('請先選擇要補發的寵物'); return; }
      if(!confirm('確定要補發寵物「' + _pn + '」(Lv.' + _lv + ')給這位玩家嗎?\n(只增不減:若已馴養且等級較高,不會降級)')) return;
      const _res = await window._fbAdminGrantPetToPlayer(uid, _pn, _lv);
      alert('✅ 補發完成:' + _pn + '\n' + ((_res && _res.msg) ? _res.msg : ''));
      try{ window._fbShowPlayerPetRecords(uid); }catch(_){}
    }catch(e){
      alert('補發失敗:' + (e && e.message ? e.message : e));
    }
  };

  window._fbAdminGrantPetToPlayer = async function(uid, petName, lv){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _pn = String(petName || '');
    const _R = window.PET_RARITY || {};
    if(!_R[_pn]) throw new Error('無效的寵物名稱:' + _pn);
    let _lv = parseInt(lv, 10);
    if(!(_lv >= 1)) _lv = 1;
    if(_lv > 20) _lv = 20;
    const _by = (_fbAuth && _fbAuth.currentUser && _fbAuth.currentUser.email) || 'admin';
    const _now = Date.now();
    const _uid12 = String(uid).slice(0, 12);
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    const _wrote = [], _skipped = [];
    let _finalLv = _lv, _existedBefore = false, _prevLv = 0;
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){
        if(_t.mustExist) throw new Error('查無玩家主檔:' + uid);
        _skipped.push(_t.label);   // 槽不存在 → 不創建殘缺槽 doc(union 載入下主檔寫入已充分)
        continue;
      }
      const _d = _snap.data() || {};
      // 讀取口徑與 _applySafeData 一致:_s 優先,fallback map(深拷貝避免污染 snapshot)
      let _pets = null;
      if(typeof _d.tamedPets_s === 'string'){ try{ const _p = JSON.parse(_d.tamedPets_s); if(_p && typeof _p === 'object') _pets = _p; }catch(_){} }
      if(!_pets && _d.tamedPets && typeof _d.tamedPets === 'object'){ try{ _pets = JSON.parse(JSON.stringify(_d.tamedPets)); }catch(_){ _pets = null; } }
      _pets = _pets || {};
      let _hist = null;
      if(typeof _d._petTameHistory_s === 'string'){ try{ const _h = JSON.parse(_d._petTameHistory_s); if(Array.isArray(_h)) _hist = _h; }catch(_){} }
      if(!_hist && Array.isArray(_d._petTameHistory)){ try{ _hist = JSON.parse(JSON.stringify(_d._petTameHistory)); }catch(_){ _hist = null; } }
      _hist = _hist || [];
      const _ever = Array.isArray(_d.petsEverCollected) ? _d.petsEverCollected.slice() : [];
      // ── 只增不減 merge ──
      const _cur = _pets[_pn];
      if(!_cur){
        _pets[_pn] = { lv: _lv, exp: 0, followTo: null, aff: 0 };
      } else {
        _existedBefore = true;
        _prevLv = Math.max(_prevLv, (_cur.lv|0) || 1);
        if(_lv > ((_cur.lv|0) || 1)){ _cur.lv = _lv; _cur.exp = 0; }
        // 好感 / 跟隨 / 較高等級:一律保留不動
      }
      _hist.push({ pet: _pn, at: _now, src: 'admin_grant', uid: _uid12, by: _by });
      if(_hist.length > 200) _hist = _hist.slice(-200);
      if(_ever.indexOf(_pn) < 0) _ever.push(_pn);
      await setDoc(_t.ref, {
        tamedPets: _pets,
        tamedPets_s: JSON.stringify(_pets),
        _petTameHistory: _hist,
        _petTameHistory_s: JSON.stringify(_hist),
        petsEverCollected: _ever
      }, { merge: true });
      _wrote.push(_t.label);
      if(_t.mustExist){ _finalLv = ((_pets[_pn] && _pets[_pn].lv)|0) || _lv; }
    }
    // 通知玩家(登入彈窗;失敗不影響補發本體)
    try{
      if(typeof window._fbAdminSendNotificationToPlayer === 'function'){
        await window._fbAdminSendNotificationToPlayer(uid, {
          title: '🐾 老師補發寵物',
          body: '老師幫你補發了寵物「' + _pn + '」(Lv.' + _finalLv + ')!到「🐾 寵物圖鑑」看看牠吧!',
          type: 'compensation'
        });
      }
    }catch(_eN){ console.warn('[寵物補發] 通知寄送失敗(補發本體已完成)', _eN); }
    const _msg = (_existedBefore
        ? ('原已馴養 Lv.' + _prevLv + ((_lv > _prevLv) ? (' → 提升至 Lv.' + _lv) : '(原等級較高或相同,維持不變)'))
        : ('新收錄 Lv.' + _lv))
      + '。寫入:' + _wrote.join('/') + (_skipped.length ? ('(略過不存在槽:' + _skipped.join('/') + ')') : '')
      + '。已寄登入通知。';
    console.log('[_fbAdminGrantPetToPlayer] ✅', uid, _pn, _msg);
    return { ok: true, pet: _pn, lv: _finalLv, existedBefore: _existedBefore, msg: _msg };
  };

  // ════════════════════════════════════════════════════════════════════════
  // ★★ v5.254.0 命座突破系統 — GM 發放命星(設計書 裁定4甲「UR 命星由 GM 發放」＋風險 A9 補償)★★
  //   寫法:在玩家三槽(主檔＋saves/live＋saves/safe)的 `cstGmGrants_s` 追加一張「發放單」{k,n,at,by,why}。
  //   ★ 為什麼不直接改 constellationData_s:學生若正在線上,他下一次存檔會用記憶體裡的命星資料整包蓋掉 GM 剛寫的數字。
  //     發放單欄位**學生端永遠不寫**(不在 _buildSafeData 裡),學生登入時才把沒套用過的單號折進自己的命星資料(ga 記單號 ⇒ 冪等)。
  //   k:英雄名(指定角色命星) 或 '#pick_SR' / '#pick_SSR' / '#pick_UR'(自選命星)。n:1~6。
  window._fbAdminGetPlayerConstellation = async function(uid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const refs = [doc(_fbDb, 'players', uid), doc(_fbDb, 'players', uid, 'saves', 'live'), doc(_fbDb, 'players', uid, 'saves', 'safe')];
    const cs = [], gs = [];
    let unlocked = [];
    for(let i = 0; i < refs.length; i++){
      let snap = null;
      try{ snap = await _gds(refs[i]); }catch(_e1){ try{ snap = await getDoc(refs[i]); }catch(_e2){ snap = null; } }
      const ex = snap && ((typeof snap.exists === 'function') ? snap.exists() : !!snap.exists);
      if(!ex) continue;
      const d = snap.data() || {};
      if(typeof d.constellationData_s === 'string' && d.constellationData_s) cs.push(d.constellationData_s);
      if(typeof d.cstGmGrants_s === 'string' && d.cstGmGrants_s) gs.push(d.cstGmGrants_s);
      if(Array.isArray(d.unlockedHeroes)) d.unlockedHeroes.forEach(function(n){ if(unlocked.indexOf(n) < 0) unlocked.push(n); });
    }
    return { data: window._lxpsCstMerge(cs), gm: window._lxpsCstMergeGm(gs), unlocked: unlocked };
  };
  window._fbAdminGrantConstellation = async function(uid, key, n, why){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _k = String(key || '');
    const _n = Math.max(1, Math.min(6, parseInt(n, 10) || 1));
    const _isPick = /^#pick_(SR|SSR|UR)$/.test(_k);
    if(!_isPick){
      const _db = window.CONSTELLATION_DB || {};
      if(!_db[_k]) throw new Error('沒有這位角色的命座:' + _k);
      if(_k === (window._PROTAG_SSR_NAME || '主角‧覺醒')) throw new Error('主角命星只能由主線劇情取得,不能 GM 發放');
    }
    const _by = (_fbAuth && _fbAuth.currentUser && _fbAuth.currentUser.email) || 'admin';
    const _now = Date.now();
    const _id = 'g' + _now.toString(36) + Math.random().toString(36).slice(2, 6);
    const _grant = { k: _k, n: _n, at: _now, by: _by, why: String(why || '').slice(0, 80) };
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    const _wrote = [], _skipped = [];
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無玩家主檔:' + uid); _skipped.push(_t.label); continue; }
      const _d = _snap.data() || {};
      const _g = window._lxpsCstMergeGm([_d.cstGmGrants_s]);
      _g[_id] = _grant;
      await setDoc(_t.ref, { cstGmGrants_s: JSON.stringify(_g) }, { merge: true });
      _wrote.push(_t.label);
    }
    try{
      if(typeof window._fbAdminSendNotificationToPlayer === 'function'){
        const _label = _isPick ? ({ '#pick_SR':'SR 自選命星', '#pick_SSR':'SSR 自選命星', '#pick_UR':'UR 自選命星' })[_k] : ('「' + _k + '」的命星');
        await window._fbAdminSendNotificationToPlayer(uid, {
          title: '✨ 老師發給你命星',
          body: '老師發給你 ' + _label + ' ×' + _n + '!' + (_grant.why ? ('(' + _grant.why + ')') : '') + '下次登入後到英雄圖鑑的「✨ 命座」就能點亮。',
          type: 'compensation'
        });
      }
    }catch(_eN){ console.warn('[命星發放] 通知寄送失敗(發放本體已完成)', _eN); }
    console.log('[_fbAdminGrantConstellation] ✅', uid, _grant, _wrote);
    return { ok: true, id: _id, grant: _grant, msg: '寫入:' + _wrote.join('/') + (_skipped.length ? ('(略過不存在槽:' + _skipped.join('/') + ')') : '') + '。已寄登入通知。' };
  };

  // ★ v5.278.0(老師 2026-10-18「GM獎勵和補償等功能新增各英雄命座」)——一次寫多筆命星發放單
  //   給 _fbCompensatePlayer 用(補償工具、課堂獎勵領取、全體獎勵領取、虛寶序號兌換都走它)。
  //   list = [{ k:'孫悟空' | '#pick_SR' | '#pick_SSR' | '#pick_UR', n:1~6 }];不合格的項目略過(回傳 skipped)。
  //   opt.idBase:有值 ⇒ 單號固定為 idBase + '_' + 序號(同一筆領獎重跑也不會重複發,例如課堂獎勵失敗回滾後重領);
  //               沒值 ⇒ 隨機單號(GM 手動補償,同樣內容發兩次就是兩次)。
  //   寫法與 _fbAdminGrantConstellation 相同(三槽 cstGmGrants_s 追加,已存在的單號不覆寫);
  //   寫的是自己的帳號(學生端領獎)且命星資料已載入 ⇒ 立刻折進記憶體(_cstFoldGmGrants),不必等下次登入。
  window._fbCstGrantMany = async function(uid, list, opt){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    opt = opt || {};
    const _db = window.CONSTELLATION_DB || {};
    const _protag = window._PROTAG_SSR_NAME || '主角‧覺醒';
    const _now = Date.now();
    const _rand = 'g' + _now.toString(36) + Math.random().toString(36).slice(2, 6);
    const _base = opt.idBase ? String(opt.idBase).slice(0, 80) : _rand;
    const _grants = {}, _skipped = [];
    (Array.isArray(list) ? list : []).slice(0, 60).forEach(function(it, i){
      const _k = String((it && it.k) || '');
      const _n = Math.max(1, Math.min(6, parseInt(it && it.n, 10) || 1));
      const _isPick = /^#pick_(SR|SSR|UR)$/.test(_k);
      const _dbReady = Object.keys(_db).length > 0;   // 命座表沒載入(學生平板偶發)⇒ 先照寫,登入折入時 _cstGrantStar 會再檢查,不在這裡丟掉已領的獎勵
      if(!_k || _k === _protag || (!_isPick && _dbReady && (!_db[_k] || _db[_k].r === 'R'))){ _skipped.push(_k); return; }
      _grants[_base + '_' + i] = { k: _k, n: _n, at: _now, by: String(opt.by || 'admin').slice(0, 80), why: String(opt.why || '').slice(0, 80) };
    });
    const _ids = Object.keys(_grants);
    if(!_ids.length) return { ok: false, written: 0, skipped: _skipped, msg: '沒有可發放的命星' };
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    const _wrote = [];
    let _merged = {};
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無玩家主檔:' + uid); continue; }
      const _g = window._lxpsCstMergeGm([(_snap.data() || {}).cstGmGrants_s]);
      _ids.forEach(function(id){ if(!_g[id]) _g[id] = _grants[id]; });   // 已存在的單號不覆寫(冪等)
      await setDoc(_t.ref, { cstGmGrants_s: JSON.stringify(_g) }, { merge: true });
      _wrote.push(_t.label);
      _merged = _g;
    }
    // 自己的帳號 ⇒ 立刻折進記憶體(命星資料還沒載入就留給登入時的 _cstHydrate,不會漏)
    try{
      const _me = (window._fbUser && window._fbUser.uid) || window._gUserId || '';
      if(_me && _me === uid && typeof window._cstFoldGmGrants === 'function'){
        const _sub = {}; _ids.forEach(function(id){ if(_merged[id]) _sub[id] = _merged[id]; });
        window._cstFoldGmGrants(_sub, { quiet: !!opt.quiet });
      }
    }catch(_eF){ console.warn('[命星批次發放] 記憶體折入失敗(雲端已寫,下次登入會補上)', _eF); }
    console.log('[_fbCstGrantMany] ✅', uid, _ids.length + ' 筆', _wrote, _skipped.length ? ('略過 ' + _skipped.join('、')) : '');
    return { ok: true, written: _ids.length, ids: _ids, slots: _wrote, skipped: _skipped };
  };

  // ★ v4.14.0 — GM 寵物重置補償(老師裁決:兩模式皆可)
  //   mode 'reroll' = 重擲隨機素質(換新 seed + retrainVer++;等級/經驗/好感/跟隨全保留)
  //   mode 'full'   = 完全重置(等級→1、經驗→0、換新 seed + retrainVer++;好感/跟隨保留)
  //   ── 三槽同寫(主檔+live+safe),因 'full' 降等必須壓過所有槽的舊高等紀錄(見 S5 合併驗證);
  //      retrainVer 統一設為「所有槽現有最大值 +1」→ 新 seed 在合併時必勝。只動已馴養寵物,不新建。
  window._fbAdminResetPetForPlayer = async function(uid, petName, mode){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _pn = String(petName || '');
    const _R = window.PET_RARITY || {};
    if(!_R[_pn]) throw new Error('無效的寵物名稱:' + _pn);
    const _mode = (mode === 'full') ? 'full' : 'reroll';
    const _by = (_fbAuth && _fbAuth.currentUser && _fbAuth.currentUser.email) || 'admin';
    const _now = Date.now();
    const _uid12 = String(uid).slice(0, 12);
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _newSeed = (typeof window._petNewSeed === 'function') ? window._petNewSeed() : (Math.floor(Math.random()*0xffffffff) >>> 0);
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    // ── 第 1 趟:讀全部槽,擷取每槽的 pet 紀錄 + 計算最大 retrainVer(供統一 +1) ──
    const _slotData = [];
    let _maxRV = 0, _foundAny = false, _prevLv = 0;
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無玩家主檔:' + uid); _slotData.push(null); continue; }
      const _d = _snap.data() || {};
      let _pets = null;
      if(typeof _d.tamedPets_s === 'string'){ try{ const _p = JSON.parse(_d.tamedPets_s); if(_p && typeof _p === 'object') _pets = _p; }catch(_){} }
      if(!_pets && _d.tamedPets && typeof _d.tamedPets === 'object'){ try{ _pets = JSON.parse(JSON.stringify(_d.tamedPets)); }catch(_){ _pets = null; } }
      _pets = _pets || {};
      _slotData.push({ t: _t, pets: _pets });
      const _cur = _pets[_pn];
      if(_cur){ _foundAny = true; _prevLv = Math.max(_prevLv, (_cur.lv|0) || 1); _maxRV = Math.max(_maxRV, (_cur.retrainVer|0) || 0); }
    }
    if(!_foundAny) throw new Error('該玩家尚未馴養寵物「' + _pn + '」,無法重置(可先用「🎁 指定補發寵物」發給玩家)');
    const _newRV = _maxRV + 1;
    // ── 第 2 趟:對「有該寵物」的槽套用重置並寫回 ──
    const _wrote = [];
    for(let i = 0; i < _slotData.length; i++){
      const _sd = _slotData[i];
      if(!_sd) continue;
      const _cur = _sd.pets[_pn];
      if(!_cur) continue;   // 該槽沒有此寵物 → 不建、不動(無高等紀錄可衝突)
      _cur.seed = _newSeed;
      _cur.retrainVer = _newRV;
      if(_mode === 'full'){ _cur.lv = 1; _cur.exp = 0; }   // 完全重置:退 Lv1、經驗歸零;好感/跟隨保留
      // reroll 模式:lv/exp/aff/followTo 全不動
      await setDoc(_sd.t.ref, {
        tamedPets: _sd.pets,
        tamedPets_s: JSON.stringify(_sd.pets)
      }, { merge: true });
      _wrote.push(_sd.t.label);
    }
    // 通知玩家(登入彈窗)
    try{
      if(typeof window._fbAdminSendNotificationToPlayer === 'function'){
        await window._fbAdminSendNotificationToPlayer(uid, {
          title: '🐾 老師調整了你的寵物',
          body: (_mode === 'full')
            ? ('老師幫寵物「' + _pn + '」完全重置了(等級回到 Lv.1、隨機素質重擲;好感度保留)!快去「🐾 寵物圖鑑」看看,並重新培養牠吧!')
            : ('老師幫寵物「' + _pn + '」重新洗牌了隨機素質(等級、經驗、好感度都不變)!到「🐾 寵物圖鑑」看看牠的新素質吧!'),
          type: 'compensation'
        });
      }
    }catch(_eN){ console.warn('[寵物重置] 通知寄送失敗(重置本體已完成)', _eN); }
    const _msg = (_mode === 'full'
        ? ('完全重置:等級 Lv.' + _prevLv + ' → Lv.1、隨機素質重擲(好感/跟隨保留)')
        : ('重擲隨機素質(等級 Lv.' + _prevLv + '、經驗、好感全保留)'))
      + '。寫入:' + (_wrote.join('/') || '(無)') + '。retrainVer→' + _newRV + '。已寄登入通知。';
    console.log('[_fbAdminResetPetForPlayer] ✅', uid, _pn, _mode, _msg);
    return { ok: true, pet: _pn, mode: _mode, msg: _msg };
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v5.32.0 — GM 後台「🛡️ 裝備管理」後端三函式(裝備 Phase 4 後半·admin_delete 稽核前例)
  //   UI 在 admin_panel.js v5.32.0「🛡️ 裝備管理」卡(三點同步);本區只做資料層。
  //   ・查詢 _fbAdminReadPlayerGear:email/lsps學號/uid → 主檔最新(getDocFromServer)→
  //     實例清單(_s 字串優先·附 GEAR_DB 顯示資料+詞條文字)+ 裝備帳本近 300 筆。
  //   ・發放 _fbAdminGearGrantForUid:GM 端 roll 詞條一次(規則同玩家取得·永久固定)→
  //     三槽同寫(主檔 mustExist + saves/live + saves/safe·寵物重置 v4.14.0 前例)同一顆實例
  //     src='admin_grant' + 帳本 admin_grant 紀錄(uid12=目標玩家·grantedBy=GM)→
  //     主檔蓋 _authoritativeRestoreAt(在線玩家 piece3 乾淨重載不互蓋)→ 寄登入通知。
  //     GM 發放豁免 100 件上限(Phase 1 ignoreCap 前例);回傳 count 供 UI 警示。
  //   ・刪除 _fbAdminGearDeleteForUid:三槽同寫刪實例 + 每槽帳本 push source:'admin_delete'
  //     (_lxpsLatestDeletedMap 稽核感知既有支援 → 殘槽合併不復活·同 sold/gift_sent 機制)→
  //     主檔蓋 _authoritativeRestoreAt → 寄登入通知。裝備中自動視同卸下(實例整顆刪除)。
  // ════════════════════════════════════════════════════════════════════
  window._fbAdminReadPlayerGear = async function(emailOrUid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    const _raw = String(emailOrUid || '').trim();
    if(!_raw) throw new Error('請提供 email、學號或 uid');
    let _uid = '', _email = '', _byEmail = '';
    if(_raw.indexOf('@') >= 0){ _byEmail = _raw.toLowerCase(); }
    else if(/^lsps\d+$/i.test(_raw)){ _byEmail = _raw.toLowerCase() + '@stu.lsps.tp.edu.tw'; }
    if(_byEmail){
      _email = _byEmail;
      const _q = query(collection(_fbDb, 'players'), where('email', '==', _email));
      const _snap = await getDocs(_q);
      if(_snap.empty) throw new Error('查無此玩家:' + _email);
      _snap.forEach(function(d){ if(!_uid) _uid = d.id; });
    } else {
      _uid = _raw;
    }
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _mainSnap = await _gds(doc(_fbDb, 'players', _uid));
    const _mainEx = (typeof _mainSnap.exists === 'function') ? _mainSnap.exists() : !!_mainSnap.exists;
    if(!_mainEx) throw new Error('查無此玩家 doc:' + _uid);
    const _d = _mainSnap.data() || {};
    if(!_email) _email = _d.email || '';
    const _fromS = function(sKey, mKey, isArr){
      let v = null;
      if(typeof _d[sKey] === 'string'){ try{ const p = JSON.parse(_d[sKey]); if(p && (isArr ? Array.isArray(p) : (typeof p === 'object'))) v = p; }catch(_){} }
      if(!v && _d[mKey] && (isArr ? Array.isArray(_d[mKey]) : (typeof _d[mKey] === 'object'))) v = _d[mKey];
      return v || (isArr ? [] : {});
    };
    const _gd = _fromS('equipmentData_s', 'equipmentData', false);
    const _inst = (_gd && _gd.instances && typeof _gd.instances === 'object') ? _gd.instances : {};
    const _hist = _fromS('_equipUnlockHistory_s', '_equipUnlockHistory', true);
    // 附顯示資料(GEAR_DB const 由全域詞法環境讀取·typeof 守門)
    const _hasDb = (typeof GEAR_DB !== 'undefined') && (typeof GEAR_RARITY !== 'undefined');
    const _items = [];
    Object.keys(_inst).forEach(function(eqUid){
      const rec = _inst[eqUid];
      if(!rec || !rec.itemId) return;
      const def = _hasDb ? GEAR_DB[rec.itemId] : null;
      const rr = (def && GEAR_RARITY[def.r]) || {};
      const si = (def && typeof GEAR_SLOT_INFO !== 'undefined' && GEAR_SLOT_INFO[def.slot]) || {};
      _items.push({
        eqUid: eqUid, itemId: rec.itemId,
        n: (def ? def.n : rec.itemId), icon: ((def && def.icon) || '🛡️'),
        slot: (def ? def.slot : '?'), slotName: (si.n || '?'),
        r: (def ? def.r : '?'), rn: (rr.name || '?'), rc: (rr.color || '#cfcfe6'),
        equippedTo: (rec.equippedTo || null), src: (rec.src || '?'),
        at: (rec.at || 0), gifted: !!rec.gifted, rr2: (rec.rr | 0) || 0,
        baseTxt: (def && typeof window._gearEffText === 'function')
          ? (def.eff || []).map(function(e){ return window._gearEffText(e, null); }).join('、') : '',
        affixLines: (typeof window._gearAffixText === 'function')
          ? (rec.affixes || []).map(function(af){ return window._gearAffixText(af); }) : []
      });
    });
    return { uid: _uid, email: _email, nickname: (_d.nickname || _d.displayName || ''),
             count: _items.length, items: _items, ledger: _hist };
  };

  // ════════════════════════════════════════════════════════════════
  // ★★ v5.135.0 — 召喚卷「逐張查證」稽核後端（老師裁定②甲）★★
  // ────────────────────────────────────────────────────────────────
  //   舊稽核靠減法推算（應有 = 發出 − 未用），券沒有身分就只能猜；
  //   券編號制上線後改成**逐張查證**：每一張券的編號、券種、來源、取得時間
  //   全部攤開，已用掉的有 used 清單為證，數字對不對一眼就看得出來。
  //   ★ 純讀取零寫入（同 v5.33.0 圖鑑頁鐵則⑧）。
  //   ★ 三槽都讀並套用與玩家端**完全同一套**合併規則
  //     （inst union → used union → un 取 max → inst \ used），
  //     否則 GM 看到的數字會和學生實際登入後看到的不一樣，比沒有工具更糟。
  //   ★ 對帳結論直接沿用玩家端公式：需補 = 背包 −(實例 + un)
  //     ＝ 老師看到的「幽靈券」數，同一條算式不會出現兩套口徑。
  window._fbAdminReadPlayerTickets = async function(emailOrUid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    const _raw = String(emailOrUid || '').trim();
    if(!_raw) throw new Error('請提供 email、學號或 uid');
    let _uid = '', _email = '';
    let _byEmail = '';
    if(_raw.indexOf('@') >= 0){ _byEmail = _raw.toLowerCase(); }
    else if(/^lsps\d+$/i.test(_raw)){ _byEmail = _raw.toLowerCase() + '@stu.lsps.tp.edu.tw'; }
    if(_byEmail){
      _email = _byEmail;
      const _q = query(collection(_fbDb, 'players'), where('email', '==', _email));
      const _snap = await getDocs(_q);
      if(_snap.empty) throw new Error('查無此玩家:' + _email);
      _snap.forEach(function(d){ if(!_uid) _uid = d.id; });
    } else { _uid = _raw; }

    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _targets = [
      { ref: doc(_fbDb, 'players', _uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', _uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', _uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    const _slots = [];
    let _mainD = null;
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無此玩家 doc:' + _uid); continue; }
      const _d = _snap.data() || {};
      if(_t.label === '主檔') _mainD = _d;
      _slots.push({ label: _t.label, d: _d });
    }
    if(!_mainD) throw new Error('查無此玩家 doc:' + _uid);
    if(!_email) _email = _mainD.email || '';

    // ── 券實例三槽合併（與 _lxpsMergeSlots 5c 完全同一套規則）──
    const _inst = {}, _usedSet = {}, _un = {};
    let _bf = false, _slotsWithData = [];
    _slots.forEach(function(sl){
      let td = null;
      try{ if(typeof sl.d.ticketData_s === 'string' && sl.d.ticketData_s){ const p = JSON.parse(sl.d.ticketData_s); if(p && typeof p === 'object' && !Array.isArray(p)) td = p; } }catch(_){}
      if(!td && sl.d.ticketData && typeof sl.d.ticketData === 'object' && !Array.isArray(sl.d.ticketData)){
        try{ td = JSON.parse(JSON.stringify(sl.d.ticketData)); }catch(_){ td = null; }
      }
      if(!td) return;
      _slotsWithData.push(sl.label);
      Object.keys(td.inst || {}).forEach(function(tid){
        const r = td.inst[tid];
        if(!r || typeof r !== 'object' || !r.it) return;
        if(!_inst[tid]){ try{ _inst[tid] = JSON.parse(JSON.stringify(r)); }catch(_){ _inst[tid] = r; } }
      });
      (Array.isArray(td.used) ? td.used : []).forEach(function(tid){ if(tid) _usedSet[tid] = 1; });
      Object.keys(td.un || {}).forEach(function(k){
        const v = parseInt(td.un[k], 10) || 0;
        if(!(k in _un) || v > _un[k]) _un[k] = v;
      });
      if(td.bf) _bf = true;
    });
    Object.keys(_usedSet).forEach(function(tid){ if(_inst[tid]) delete _inst[tid]; });   // ★ 已用券不列為持有

    // ── 主檔背包（_s 字串優先·v3.15.57 洗錢口徑）──
    let _bag = {};
    try{
      if(typeof _mainD.playerBackpack_s === 'string'){ _bag = JSON.parse(_mainD.playerBackpack_s) || {}; }
      else if(_mainD.playerBackpack && typeof _mainD.playerBackpack === 'object'){ _bag = Object.assign({}, _mainD.playerBackpack); }
    }catch(_){ _bag = {}; }
    if(!_bag || typeof _bag !== 'object' || Array.isArray(_bag)) _bag = {};

    // ── 逐張明細 ──
    const _defOf = function(id){ try{ return (typeof BACKPACK_ITEM_DEF !== 'undefined') ? BACKPACK_ITEM_DEF[id] : null; }catch(_){ return null; } };
    const _items = [];
    Object.keys(_inst).forEach(function(tid){
      const r = _inst[tid];
      const def = _defOf(r.it);
      _items.push({
        tid: tid, itemId: r.it,
        name: (def && def.name) || r.it,
        icon: (def && def.icon) || '\u{1F3AB}',
        src: r.src || '?', at: r.at || 0,
        legacy: !!r.lg,
        isGm: !!(window._isGmTicketId && window._isGmTicketId(r.it))
      });
    });
    _items.sort(function(a, b){ return (a.itemId < b.itemId ? -1 : a.itemId > b.itemId ? 1 : (a.at - b.at)); });

    // ── 逐券種對帳（口徑與玩家端 _ticketReconcile 完全一致）──
    const _rows = [];
    const _ids = (window._TICKET_INST_IDS && Object.keys(window._TICKET_INST_IDS)) || [];
    _ids.forEach(function(id){
      const _bagN  = parseInt(_bag[id], 10) || 0;
      const _haveN = _items.filter(function(o){ return o.itemId === id; }).length;
      const _unN   = parseInt(_un[id], 10) || 0;
      if(!_bagN && !_haveN && !_unN) return;
      const def = _defOf(id);
      _rows.push({
        itemId: id, name: (def && def.name) || id, icon: (def && def.icon) || '\u{1F3AB}',
        bag: _bagN, held: _haveN, used: _unN,
        // 需補 > 0 ＝ 背包數字比帳目多出來的部分（未納管的新券；正常應為 0）
        pending: Math.max(0, _bagN - (_haveN + _unN)),
        // 背包比實例少 ＝ 上次登入投影尚未寫回，屬正常（學生下次登入自動收斂）
        projectDiff: _bagN - _haveN,
        legacy: _items.filter(function(o){ return o.itemId === id && o.legacy; }).length
      });
    });

    return {
      uid: _uid, email: _email,
      nickname: (_mainD.nickname || _mainD.displayName || ''),
      migrated: _bf,                       // 是否已完成首次券編號 backfill
      slots: _slotsWithData,
      heldCount: _items.length,
      usedCount: Object.keys(_usedSet).length,
      items: _items, rows: _rows,
      legacyCount: _items.filter(function(o){ return o.legacy; }).length
    };
  };

  window._fbAdminGearGrantForUid = async function(uid, itemId){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _iid = String(itemId || '');
    if(typeof GEAR_DB === 'undefined' || !GEAR_DB[_iid]) throw new Error('無效的裝備 itemId:' + _iid);
    const _def = GEAR_DB[_iid];
    const _by = (_fbAuth && _fbAuth.currentUser && _fbAuth.currentUser.email) || 'admin';
    const _now = Date.now();
    const _uid12 = String(uid).slice(0, 12);
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    // roll 一次·三槽共用同一顆實例(規則同玩家取得·取得當下永久固定)
    const _afs = (typeof window._gearRollAffixes === 'function') ? window._gearRollAffixes(_iid) : [];
    const _eqUid = (typeof window._gearGenUid === 'function') ? window._gearGenUid()
                 : ('eq_' + _now.toString(36) + '_' + Math.random().toString(36).slice(2, 8));
    const _newInst = { itemId: _iid, affixes: _afs, gifted: false, equippedTo: null,
                       src: 'admin_grant', at: _now, at2: _now, rr: 0 };
    const _ledgerRec = { eqUid: _eqUid, itemId: _iid, src: 'admin_grant', uid12: _uid12, at: _now, grantedBy: _by };
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    const _wrote = [];
    let _mainCount = 0;
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無玩家主檔:' + uid); continue; }
      const _d = _snap.data() || {};
      let _gd = null;
      if(typeof _d.equipmentData_s === 'string'){ try{ const p = JSON.parse(_d.equipmentData_s); if(p && typeof p === 'object') _gd = p; }catch(_){} }
      if(!_gd && _d.equipmentData && typeof _d.equipmentData === 'object'){ try{ _gd = JSON.parse(JSON.stringify(_d.equipmentData)); }catch(_){ _gd = null; } }
      if(!_gd || typeof _gd !== 'object') _gd = { instances:{} };
      if(!_gd.instances || typeof _gd.instances !== 'object') _gd.instances = {};
      _gd.instances[_eqUid] = _newInst;
      let _hist = null;
      if(typeof _d._equipUnlockHistory_s === 'string'){ try{ const p = JSON.parse(_d._equipUnlockHistory_s); if(Array.isArray(p)) _hist = p; }catch(_){} }
      if(!_hist && Array.isArray(_d._equipUnlockHistory)) _hist = _d._equipUnlockHistory.slice();
      _hist = _hist || [];
      _hist.push(_ledgerRec);
      if(_hist.length > 300) _hist = _hist.slice(-300);
      const _patch = {
        equipmentData: _gd, equipmentData_s: JSON.stringify(_gd),
        _equipUnlockHistory: _hist, _equipUnlockHistory_s: JSON.stringify(_hist)
      };
      if(_t.label === '主檔'){ _patch._authoritativeRestoreAt = _now; _mainCount = Object.keys(_gd.instances).length; }
      await setDoc(_t.ref, _patch, { merge: true });
      _wrote.push(_t.label);
    }
    // 通知玩家(登入彈窗)
    try{
      if(typeof window._fbAdminSendNotificationToPlayer === 'function'){
        const _rn = (typeof GEAR_RARITY !== 'undefined' && GEAR_RARITY[_def.r] && GEAR_RARITY[_def.r].name) || '稀有';
        await window._fbAdminSendNotificationToPlayer(uid, {
          title: '🛡️ 老師送你一件裝備!',
          body: '老師發給你 ' + (_def.icon || '🛡️') + ' ' + _rn + '裝備「' + _def.n + '」×1(詞條 ' + _afs.length + ' 條·當場隨機決定永久固定)!到英雄圖鑑的「🛡️ 裝備欄位」幫夥伴穿上吧!',
          type: 'compensation'
        });
      }
    }catch(_eN){ console.warn('[GM裝備發放] 通知寄送失敗(發放本體已完成)', _eN); }
    console.log('[_fbAdminGearGrantForUid] ✅', uid, _iid, _eqUid, '寫入:' + _wrote.join('/'));
    return { ok: true, eqUid: _eqUid, itemId: _iid, name: _def.n, affixN: _afs.length,
             count: _mainCount, wrote: _wrote };
  };

  window._fbAdminGearDeleteForUid = async function(uid, eqUid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    if(!uid) throw new Error('缺少 uid');
    const _eq = String(eqUid || '');
    if(!_eq) throw new Error('缺少 eqUid');
    const _by = (_fbAuth && _fbAuth.currentUser && _fbAuth.currentUser.email) || 'admin';
    const _now = Date.now();
    const _uid12 = String(uid).slice(0, 12);
    const _gds = (typeof getDocFromServer === 'function') ? getDocFromServer : getDoc;
    const _targets = [
      { ref: doc(_fbDb, 'players', uid), label: '主檔', mustExist: true },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'live'), label: 'live', mustExist: false },
      { ref: doc(_fbDb, 'players', uid, 'saves', 'safe'), label: 'safe', mustExist: false }
    ];
    let _itemId = '', _foundAny = false;
    const _wrote = [];
    for(let i = 0; i < _targets.length; i++){
      const _t = _targets[i];
      let _snap = null;
      try{ _snap = await _gds(_t.ref); }catch(_e1){ try{ _snap = await getDoc(_t.ref); }catch(_e2){ _snap = null; } }
      const _ex = _snap && ((typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists);
      if(!_ex){ if(_t.mustExist) throw new Error('查無玩家主檔:' + uid); continue; }
      const _d = _snap.data() || {};
      let _gd = null;
      if(typeof _d.equipmentData_s === 'string'){ try{ const p = JSON.parse(_d.equipmentData_s); if(p && typeof p === 'object') _gd = p; }catch(_){} }
      if(!_gd && _d.equipmentData && typeof _d.equipmentData === 'object'){ try{ _gd = JSON.parse(JSON.stringify(_d.equipmentData)); }catch(_){ _gd = null; } }
      if(!_gd || typeof _gd !== 'object') _gd = { instances:{} };
      if(!_gd.instances || typeof _gd.instances !== 'object') _gd.instances = {};
      const _has = !!_gd.instances[_eq];
      if(_has){
        _foundAny = true;
        if(!_itemId) _itemId = (_gd.instances[_eq].itemId || '');
        delete _gd.instances[_eq];
      }
      // ★ 帳本 admin_delete「三槽都寫」:任一殘槽 union 到本筆即排除該 eqUid(稽核感知既有機制),
      //   玩家在線覆寫主檔/live 時 safe 槽仍留鐵證 → 永不復活(admin_delete 英雄前例同款保險)。
      let _hist = null;
      if(typeof _d._equipUnlockHistory_s === 'string'){ try{ const p = JSON.parse(_d._equipUnlockHistory_s); if(Array.isArray(p)) _hist = p; }catch(_){} }
      if(!_hist && Array.isArray(_d._equipUnlockHistory)) _hist = _d._equipUnlockHistory.slice();
      _hist = _hist || [];
      _hist.push({ eqUid: _eq, itemId: (_itemId || ''), src: 'admin', source: 'admin_delete',
                   uid12: _uid12, at: _now, removedBy: _by });
      if(_hist.length > 300) _hist = _hist.slice(-300);
      const _patch = {
        equipmentData: _gd, equipmentData_s: JSON.stringify(_gd),
        _equipUnlockHistory: _hist, _equipUnlockHistory_s: JSON.stringify(_hist)
      };
      if(_t.label === '主檔') _patch._authoritativeRestoreAt = _now;
      await setDoc(_t.ref, _patch, { merge: true });
      _wrote.push(_t.label);
    }
    if(!_foundAny) return { ok: false, reason: 'not_found', msg: '三槽皆查無此裝備實例(可能已被賣出/送出/刪除)' };
    const _def = (typeof GEAR_DB !== 'undefined') ? GEAR_DB[_itemId] : null;
    // 通知玩家(登入彈窗)
    try{
      if(typeof window._fbAdminSendNotificationToPlayer === 'function'){
        await window._fbAdminSendNotificationToPlayer(uid, {
          title: '🛡️ 老師調整了你的裝備',
          body: '老師從你的裝備背包移除了 ' + ((_def && _def.icon) || '🛡️') + '「' + ((_def && _def.n) || _itemId) + '」×1(若正裝備在夥伴身上會自動卸下)。有疑問可以用「🙋 求救與回報」告訴老師。',
          type: 'warning'
        });
      }
    }catch(_eN){ console.warn('[GM裝備刪除] 通知寄送失敗(刪除本體已完成)', _eN); }
    console.log('[_fbAdminGearDeleteForUid] ✅', uid, _eq, _itemId, '寫入:' + _wrote.join('/'));
    return { ok: true, eqUid: _eq, itemId: _itemId, name: ((_def && _def.n) || _itemId), wrote: _wrote };
  };

  // 彈窗「♻️ 重置」點擊入口(讀 select/mode → confirm → 執行 → 重整彈窗)
  window._gmPetResetClick = async function(uid){
    try{
      const _sel = document.getElementById('_gm-pet-reset-sel');
      const _pn = _sel ? String(_sel.value || '') : '';
      const _modeEl = document.querySelector('input[name="_gm-pet-reset-mode"]:checked');
      const _mode = _modeEl ? String(_modeEl.value) : 'reroll';
      if(!_pn){ alert('請先選擇要重置的寵物(需為該玩家已馴養者)'); return; }
      const _modeTxt = (_mode === 'full') ? '完全重置(退 Lv.1、重擲隨機素質;好感保留)' : '重擲隨機素質(等級/經驗/好感全保留)';
      if(!confirm('確定要對玩家的寵物「' + _pn + '」執行:\n' + _modeTxt + ' 嗎?')) return;
      const _res = await window._fbAdminResetPetForPlayer(uid, _pn, _mode);
      alert('✅ 重置完成:' + _pn + '\n' + ((_res && _res.msg) ? _res.msg : ''));
      try{ window._fbShowPlayerPetRecords(uid); }catch(_){}
    }catch(e){
      alert('重置失敗:' + (e && e.message ? e.message : e));
    }
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v3.15.26(2026-06-17)新增 — 虛寶序號(課堂獎勵兌換券)系統
  //   GM 後台勾獎勵+數量 → 批量產生「一次性序號」寫 redeemCodes/{CODE};
  //   學生主選單「🎟️ 序號兌換」輸入序號 → 兌換到自己帳號(複用 _fbCompensatePlayer)。
  //   ── 單次使用:每個序號只能被兌換一次,兌過再輸入顯示「此序號已被使用」。
  //   ⚠ 需在 Firestore Console 部署 redeemCodes 規則後才生效(見 MEMORY_HANDOFF / firestore.rules)。
  //   資料結構 redeemCodes/{CODE} = {
  //     code, reward(_fbCompensatePlayer payload), itemsLabel[],
  //     redeemed:bool, redeemedBy, redeemedByLabel, redeemedAt,
  //     expiresAt(0=永久), batchId, note, createdAt, createdBy, enabled
  //   }
  //   安全:玩家本來就能寫自己 doc(反作弊靠 GM 異常掃描),序號系統只多防「同序號重複兌換」。
  //         rule 限玩家僅能把 redeemed:false→true(且 redeemedBy==自己),動不了 reward/有效期。
  // ════════════════════════════════════════════════════════════════════
  // 序號產生器:12 碼大寫英數,排除易混淆字元 0/O/1/I/L(比照邀請碼)。
  window._lxpsGenRedeemCode = function(){
    const _chars = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';   // 排除 0 O 1 I L
    let _s = '';
    for(let i = 0; i < 12; i++){ _s += _chars.charAt(Math.floor(Math.random() * _chars.length)); }
    return _s;   // 例:XK3PQ9MNW2HT
  };

  // GM:批量產生序號。spec = { reward, itemsLabel, count, expiresAt, note }
  //   回傳 { ok, codes:[...], fail:[...], batchId, expiresAt, itemsLabel }
  window._fbGenerateRedeemCodes = async function(spec){
    if(!spec || typeof spec !== 'object') throw new Error('spec 為必要');
    const _reward = (spec.reward && typeof spec.reward === 'object') ? spec.reward : null;
    const _labels = Array.isArray(spec.itemsLabel) ? spec.itemsLabel.map(s => String(s)).slice(0, 30) : [];
    const _count  = Math.max(1, Math.min(200, parseInt(spec.count, 10) || 1));   // 一批最多 200
    const _expiresAt = (typeof spec.expiresAt === 'number' && spec.expiresAt > 0) ? spec.expiresAt : 0;
    const _note = String(spec.note || '').slice(0, 120);
    if(!_reward || !_labels.length) throw new Error('獎勵內容不可為空');
    const _by = (window._fbUser && window._fbUser.email) || 'admin';
    const _batchId = 'B' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const _codes = [], _fail = [];
    for(let i = 0; i < _count; i++){
      const _code = window._lxpsGenRedeemCode();
      try{
        // runTransaction 確保「不存在才寫」,避免極低機率撞號覆蓋既有序號
        const _written = await runTransaction(_fbDb, async (tx) => {
          const _ref = doc(_fbDb, 'redeemCodes', _code);
          const _snap = await tx.get(_ref);
          if(_snap.exists()) return false;   // 撞號 → 跳過(不重試,避免迴圈)
          tx.set(_ref, {
            code: _code,
            reward: _reward,
            itemsLabel: _labels,
            redeemed: false,
            redeemedBy: '',
            redeemedByLabel: '',
            redeemedAt: 0,
            expiresAt: _expiresAt,
            batchId: _batchId,
            note: _note,
            createdAt: Date.now(),
            createdBy: _by,
            enabled: true,
          });
          return true;
        });
        if(_written){ _codes.push(_code); } else { _fail.push(_code + '(撞號跳過)'); }
      }catch(e){
        _fail.push(_code + ':' + (e && e.message || e));
      }
    }
    return { ok: _codes.length > 0, codes: _codes, fail: _fail, batchId: _batchId, expiresAt: _expiresAt, itemsLabel: _labels };
  };

  // GM:列出序號清單(新→舊;預設 200 筆)。回傳陣列。
  window._fbListRedeemCodes = async function(maxN){
    const _n = Math.max(1, Math.min(500, parseInt(maxN, 10) || 200));
    let _snap;
    try{
      const _q = query(collection(_fbDb, 'redeemCodes'), orderBy('createdAt', 'desc'), limit(_n));
      _snap = await getDocs(_q);
    }catch(_eOrder){
      console.warn('[_fbListRedeemCodes] orderBy fallback', _eOrder);
      const _q2 = query(collection(_fbDb, 'redeemCodes'), limit(_n));
      _snap = await getDocs(_q2);
    }
    const _list = [];
    _snap.forEach(d => {
      const _x = d.data() || {};
      _list.push({
        code: _x.code || d.id,
        itemsLabel: Array.isArray(_x.itemsLabel) ? _x.itemsLabel : [],
        redeemed: !!_x.redeemed,
        redeemedByLabel: _x.redeemedByLabel || '',
        redeemedAt: _x.redeemedAt || 0,
        expiresAt: _x.expiresAt || 0,
        enabled: _x.enabled !== false,
        note: _x.note || '',
        batchId: _x.batchId || '',
        createdAt: _x.createdAt || 0,
        createdBy: _x.createdBy || '',
      });
    });
    _list.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    return _list;
  };

  // GM:刪除序號(已兌換者的玩家獎勵不受影響,只是讓此序號無法再被兌換/查到)
  window._fbAdminDeleteRedeemCode = async function(code){
    const _c = String(code || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    if(!_c) throw new Error('序號不可為空');
    await deleteDoc(doc(_fbDb, 'redeemCodes', _c));
    return true;
  };

  // 玩家:兌換序號(單次使用)。回傳 { ok, itemsLabel, reason, _critical }
  window._fbRedeemCode = async function(code){
    const _uid = (window._fbUser && window._fbUser.uid) || null;
    if(!_uid) return { ok: false, reason: '尚未登入,請重新整理後再試' };
    // normalize:去掉非英數、轉大寫(學生可能打成小寫或加 - 空格)
    const _c = String(code || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    if(!_c || _c.length < 6) return { ok: false, reason: '請輸入正確的序號' };
    const _ref = doc(_fbDb, 'redeemCodes', _c);
    // 先讀一次給友善訊息(rule + transaction 是最後防線)
    let _data = null;
    try{
      const _snap = await getDocFromServer(_ref);
      // ★ v3.15.75 — 相容 .exists 為方法(v9 modular)或布林屬性,確保「查無此序號」一定判得出來,絕不 fall-through 成功
      const _exists = (typeof _snap.exists === 'function') ? _snap.exists() : !!_snap.exists;
      if(!_exists) return { ok: false, reason: '查無此序號,請確認有沒有打錯' };
      _data = _snap.data() || {};
    }catch(e){
      console.warn('[_fbRedeemCode] 讀取失敗', e);
      // ★ v3.15.75 — 權限被拒(redeemCodes 規則未部署)與一般網路問題分開提示;兩者一律「不發獎」
      const _pd = !!(e && (e.code === 'permission-denied' || /permission|insufficient/i.test(String((e && e.message) || ''))));
      return { ok: false, reason: _pd ? '序號系統尚未啟用,請聯絡老師' : '讀取序號失敗,請檢查網路後再試' };
    }
    // ★ v3.15.75 — 結構驗證:真正的序號一定帶 reward / itemsLabel / createdBy / batchId 其中之一,
    //   防「剛好存在但不是序號」的文件被當成功兌換(亂打序號 → 查無此序號,絕不發獎)。
    const _looksLikeCode = !!(_data && ((_data.reward && typeof _data.reward === 'object')
      || (Array.isArray(_data.itemsLabel) && _data.itemsLabel.length > 0)
      || _data.createdBy || _data.batchId));
    if(!_looksLikeCode) return { ok: false, reason: '查無此序號,請確認有沒有打錯' };
    if(_data.enabled === false) return { ok: false, reason: '此序號已停用' };
    if(_data.expiresAt && Date.now() > _data.expiresAt) return { ok: false, reason: '此序號已過期' };
    if(_data.redeemed) return { ok: false, reason: '此序號已被使用' };
    // transaction 原子標記:防同時兩人兌同一序號(誰先標記成功誰得)
    const _label = ((window._fbUser && window._fbUser.email) || '') || _uid;
    let _txResult;
    try{
      _txResult = await runTransaction(_fbDb, async (tx) => {
        const _s = await tx.get(_ref);
        // ★ v3.15.75 — 同上 .exists 相容,交易內存在性檢查也絕不誤判(最後防線)
        const _sExists = (typeof _s.exists === 'function') ? _s.exists() : !!_s.exists;
        if(!_sExists) return { ok: false, reason: '查無此序號' };
        const _d = _s.data() || {};
        if(_d.enabled === false) return { ok: false, reason: '此序號已停用' };
        if(_d.expiresAt && Date.now() > _d.expiresAt) return { ok: false, reason: '此序號已過期' };
        if(_d.redeemed) return { ok: false, reason: '此序號已被使用' };
        tx.update(_ref, {
          redeemed: true,
          redeemedBy: _uid,
          redeemedByLabel: String(_label || '').slice(0, 60),
          redeemedAt: Date.now(),
        });
        return { ok: true, reward: _d.reward || {}, itemsLabel: Array.isArray(_d.itemsLabel) ? _d.itemsLabel : [] };
      });
    }catch(e){
      // permission denied(rule resource.redeemed==false 不成立=剛被搶兌)或其他
      console.warn('[_fbRedeemCode] transaction 失敗', e);
      return { ok: false, reason: '兌換失敗,可能此序號剛被別人使用,請再確認' };
    }
    if(!_txResult || !_txResult.ok) return { ok: false, reason: (_txResult && _txResult.reason) || '兌換失敗' };
    // 標記成功 → 發獎到自己(複用 _fbCompensatePlayer,union 合併不降級)
    //   ★ 先標記再發獎:寧可偶爾(發獎異常時)漏發、由老師補,也不可「先發獎後標記失敗」造成重複刷
    try{
      if(typeof window._fbCompensatePlayer !== 'function') throw new Error('_fbCompensatePlayer 未載入');
      await window._fbCompensatePlayer(_uid, Object.assign({}, _txResult.reward, {
        reason: '虛寶序號兌換',
        summary: '虛寶序號:' + ((_txResult.itemsLabel || []).join(' + ') || _c),
        by: 'redeem:' + _c,
      }));
    }catch(e){
      console.error('[_fbRedeemCode] 已標記但發獎失敗(序號已消耗)', e);
      return { ok: false, reason: '兌換異常,請截圖這個序號找老師補發', _critical: true, itemsLabel: _txResult.itemsLabel };
    }
    // ★ v3.17.8 — 發獎成功 → 自寫一筆 _redeemClaimLog(self-write·不需改 rule),
    //   供 _fbReconcileRedeemCodeTickets 登入回溯對帳讀取(避免對 redeemCodes 集合做 list 查詢——
    //   該集合 list 權限僅限管理員,玩家用 query+getDocs 會被規則擋下,故改讀自己主檔的紀錄)。
    try{
      const _rps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      let _rlog = [];
      if(_rps.exists()){ const _rpd = _rps.data() || {}; if(Array.isArray(_rpd._redeemClaimLog)) _rlog = _rpd._redeemClaimLog.slice(); }
      if(!_rlog.some(function(e){ return e && e.code === _c; })){
        _rlog.push({ code: _c, reward: _txResult.reward || {}, itemsLabel: (_txResult.itemsLabel || []).slice(0, 40), at: Date.now() });
        if(_rlog.length > 200) _rlog = _rlog.slice(-200);
        await setDoc(doc(_fbDb, 'players', _uid), { _redeemClaimLog: _rlog }, { merge: true });
      }
    }catch(_eLog){ console.warn('[_fbRedeemCode] 寫入 _redeemClaimLog 失敗(不影響已發獎·僅影響回溯對帳)', _eLog); }
    // ★ v3.17.8 — 回傳結構化 reward,讓 client 領取後「即時把獎勵套進記憶體」(比照 v3.16.97 GM課堂獎勵修法,
    //   免疫 _lxpsMergeSlots 消耗型欄位「只取最新槽」— 若玩家兌換後沒有立刻重整就繼續遊戲,
    //   後續 autosave 帶著舊記憶體背包寫槽會把剛兌換的券沖掉,套進記憶體後就不會了)
    return { ok: true, itemsLabel: _txResult.itemsLabel || [], reward: (_txResult.reward && typeof _txResult.reward === 'object') ? _txResult.reward : {} };
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v3.17.8 — 回溯救援:登入對帳「已兌換序號自選卷·實際沒拿到的補上」
  //   鏡像 v3.16.97 的 _fbReconcileGmClassRewardTickets;來源改讀玩家自己主檔的 _redeemClaimLog
  //   (self-write·由 _fbRedeemCode 兌換成功時寫入,不對 redeemCodes 集合做 list 查詢——
  //   該集合 list 權限僅限管理員,一般玩家 query+getDocs 會被 rules 擋下)。
  //   同一份 _GMCR_PICK_TICKET_SRC 定義(4 種自選卷)。
  //   安全不等式同款:已發(兌換序號 reward.backpack)− 已用(durable 帳本)− 現有(背包)− 已補(冪等記) > 0 才補。
  //   ⚠ 邊界:v3.17.8 之前兌換的序號沒有 _redeemClaimLog 紀錄,無法回溯對帳(僅涵蓋本次修復後的兌換)。
  // ════════════════════════════════════════════════════════════════════
  window._fbReconcileRedeemCodeTickets = async function(){
    try{
      var _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb || !window._GMCR_PICK_TICKET_SRC) return;
      var _pd = {};
      try{ var _ps = await getDocFromServer(doc(_fbDb, 'players', _uid)); if(_ps.exists()) _pd = _ps.data() || {}; }
      catch(_ePd){ return; }
      var _mine = Array.isArray(_pd._redeemClaimLog) ? _pd._redeemClaimLog : [];
      if(!_mine.length) return;
      var _recovered = (_pd._redeemRecoveredTickets && typeof _pd._redeemRecoveredTickets === 'object') ? Object.assign({}, _pd._redeemRecoveredTickets) : {};
      var _RECONCILE_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;
      var _nowR = Date.now();
      var _granted = {};
      _mine.forEach(function(rw){
        if(!rw || !rw.at) return;
        var _bp = (rw.reward && typeof rw.reward === 'object') ? rw.reward.backpack : null;
        if(!_bp || typeof _bp !== 'object') return;
        var _isOld = !!((_nowR - rw.at) > _RECONCILE_WINDOW_MS);
        Object.keys(window._GMCR_PICK_TICKET_SRC).forEach(function(_k){
          if(_isOld && window._GMCR_PICK_TICKET_SRC[_k].ledger === '_heroUnlockHistory') return;
          var _n = Math.max(0, parseInt(_bp[_k], 10) || 0);
          if(_n > 0) _granted[_k] = (_granted[_k] || 0) + _n;
        });
      });
      if(!Object.keys(_granted).length) return;
      var _countSrc = function(ledgerKey, src){
        var _arr = Array.isArray(_pd[ledgerKey]) ? _pd[ledgerKey] : [];
        var _c = 0;
        _arr.forEach(function(e){ if(e && e.source === src) _c++; });
        return _c;
      };
      var _toGrant = {};
      Object.keys(_granted).forEach(function(_k){
        var _def = window._GMCR_PICK_TICKET_SRC[_k];
        var _used = _countSrc(_def.ledger, _def.source);
        var _held = (typeof backpackGet === 'function') ? (backpackGet(_k) || 0) : 0;
        var _rec  = Math.max(0, parseInt(_recovered[_k], 10) || 0);
        var _short = (_granted[_k] || 0) - _used - _held - _rec;
        if(_short > 0) _toGrant[_k] = _short;
      });
      if(!Object.keys(_toGrant).length) return;
      var _labels = [];
      Object.keys(_toGrant).forEach(function(_k){
        var _n = _toGrant[_k];
        try{ if(typeof backpackAdd === 'function') backpackAdd(_k, _n); }catch(_eAdd){}
        _recovered[_k] = (Math.max(0, parseInt(_recovered[_k], 10) || 0)) + _n;
        _labels.push(window._GMCR_PICK_TICKET_SRC[_k].label + '×' + _n);
      });
      try{ await setDoc(doc(_fbDb, 'players', _uid), { _redeemRecoveredTickets: _recovered }, { merge: true }); }
      catch(_eMark){ console.warn('[序號兌換對帳] 寫冪等標記失敗(背包已補·下次因 held 已有不會重補)', _eMark); }
      try{ if(typeof _showInGameToast === 'function') _showInGameToast('🎁 補發了你序號兌換漏拿到的：' + _labels.join('、'), '#66dd88', 4500); }catch(_eToast){}
      try{ console.log('[序號兌換對帳 v3.17.8] 補發漏領自選卷', _toGrant); }catch(_){}
    }catch(_eAll){ try{ console.warn('[序號兌換對帳] 例外(略過·不影響登入)', _eAll); }catch(_){} }
  };

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v3.15.49 — 全體玩家獎勵(GM 一鍵發送給所有人,每人「保證只領一次」)
  // ────────────────────────────────────────────────────────────────────────────
  //   防重複設計(免疫存檔 richest-merge 復活):
  //     ① GM 建立 → 寫獨立 collection globalRewards/{autoId}
  //          = { reward(_fbCompensatePlayer payload), items[](顯示用), title, note,
  //              createdAt, createdBy, expiresAt(0=永久), enabled:true }
  //     ② 玩家領取 = 對「獨立認領文件」globalRewardClaims/{uid}_{rewardId} 做 transaction:
  //          tx.get 已存在 → 視為已領、略過;不存在 → tx.set 認領(原子標記)。
  //        認領文件與玩家存檔(players/{uid} 及 saves/*)完全分離 → 永不會被三槽 richest-merge
  //        「復活」成未領狀態 → 即使共用 iPad 清快取 / 雲端資料誤差,也絕不可能重複領取。
  //     ③ 標記成功後才 _fbCompensatePlayer 發獎(沿用序號兌換「先標記再發獎,寧漏不重複」原則)。
  //   效能:玩家主檔存 _grClaimed(陣列)做「跳過已領」快取,避免每次登入都對每個獎勵跑 transaction;
  //         但「權威防重複」永遠是 globalRewardClaims 認領文件,快取只是省讀取,壞了也擋得住雙領。
  // ════════════════════════════════════════════════════════════════════════════

  // GM:建立一筆全體獎勵。reward = _buildReward 產生的 payload;meta = { items, title, note, expiresDays }
  window._fbCreateGlobalReward = async function(reward, meta){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    meta = meta || {};
    const _by = (window._fbUser && window._fbUser.email) || 'admin';
    const _days = Math.max(0, Math.floor(Number(meta.expiresDays) || 0));   // 0 = 永久
    const _now = Date.now();
    const _doc = {
      reward: reward || {},
      items: Array.isArray(meta.items) ? meta.items.slice(0, 40) : [],
      title: String(meta.title || '全體獎勵').slice(0, 60),
      note: String(meta.note || '').slice(0, 300),
      createdAt: _now,
      createdBy: String(_by).slice(0, 60),
      expiresAt: _days > 0 ? (_now + _days * 86400 * 1000) : 0,
      enabled: true,
    };
    // 無 addDoc 匯入 → 用 doc(collection(...)) 產生 auto-id ref 再 setDoc
    const _ref = doc(collection(_fbDb, 'globalRewards'));
    await setDoc(_ref, _doc);
    console.info('✅ [全體獎勵] 已建立 ' + _ref.id + '（' + _doc.title + '）');
    return { ok: true, id: _ref.id };
  };

  // GM:列出所有全體獎勵(新→舊)
  window._fbListGlobalRewards = async function(){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    const _snap = await getDocs(collection(_fbDb, 'globalRewards'));
    const _list = [];
    _snap.forEach(function(d){ _list.push(Object.assign({ id: d.id }, d.data() || {})); });
    _list.sort(function(a, b){ return (b.createdAt || 0) - (a.createdAt || 0); });
    return _list;
  };

  // GM:啟用 / 停用一筆全體獎勵(停用後新登入的玩家不再領;已領者不受影響)
  window._fbSetGlobalRewardEnabled = async function(id, enabled){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    if(!id) throw new Error('id 不可為空');
    await updateDoc(doc(_fbDb, 'globalRewards', id), { enabled: !!enabled });
    return { ok: true };
  };

  // GM:刪除一筆全體獎勵(認領文件 globalRewardClaims 保留即可,無害)
  window._fbDeleteGlobalReward = async function(id){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    if(!id) throw new Error('id 不可為空');
    await deleteDoc(doc(_fbDb, 'globalRewards', id));
    return { ok: true };
  };

  // 玩家:登入時自動領取所有「尚未領過」的有效全體獎勵。回傳已領清單供通知。
  window._fbClaimGlobalRewards = async function(){
    const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
    if(!_uid || !_fbDb) return { claimed: [] };
    let _activeList = [];
    try{
      // 只讀 enabled==true(需 globalRewards 規則允許登入者 list;見部署說明)
      const _q = query(collection(_fbDb, 'globalRewards'), where('enabled', '==', true));
      const _snap = await getDocs(_q);
      _snap.forEach(function(d){ _activeList.push(Object.assign({ id: d.id }, d.data() || {})); });
    }catch(e){
      // ★ v4.10.0 — 改為不早退:即使 globalRewards 查詢失敗(規則未部署/網路),
      //   仍要處理下方「寵物同萌上線禮」(硬編碼·不依賴 globalRewards 集合)。
      console.warn('[全體獎勵] 讀取有效獎勵失敗(可能規則未部署)·仍處理上線禮', e);
    }
    // ★ v4.10.0 需求1 — 「寵物同萌」全服上線禮(硬編碼注入·不需 GM 在後台建立):
    //   隨機寵物召喚卷×1 + 高級寵物飼料×10。防重複:走既有 globalRewardClaims/{uid}_{rid}
    //   transaction create-only 認領文件(UID 雲端權威·免疫三槽合併復活/跨裝置重複)。
    try{
      if(window._petSysOpenForMe && window._petSysOpenForMe()){
        _activeList.unshift({
          id: 'pet40_launch_v4100',
          title: '🐾 寵物同萌 正式上線禮',
          items: ['🎟️ 隨機寵物召喚卷 ×1', '🍖 高級寵物飼料 ×10'],
          note: '「寵物同萌」全面開放!快用召喚卷召喚你的第一隻寵物,再到寵物小屋跟牠互動吧!',
          reward: { backpack: { pet_summon_ticket: 1, pet_food_adv: 10 } },
          enabled: true
        });
      }
    }catch(_eGift){ console.warn('[寵物上線禮] 注入失敗', _eGift); }
    if(!_activeList.length) return { claimed: [] };

    // 讀玩家主檔的「已領快取」_grClaimed,先跳過已領,省去 transaction
    let _claimedCache = [];
    try{
      const _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(_ps.exists()){
        const _pd = _ps.data() || {};
        if(Array.isArray(_pd._grClaimed)) _claimedCache = _pd._grClaimed.slice();
        // ★ v4.10.0 — 順讀寵物教學雲端旗標(同一次讀取·零額外成本):
        //   petTut1Done=第一階段聚光引導已完成 / petTut2Seen=馴養教學看過一次 / petTut2Off=永久關閉
        try{
          window._petTutCloudFlags = {
            t1Done: !!_pd.petTut1Done,
            t2Seen: !!_pd.petTut2Seen,
            t2Off:  !!_pd.petTut2Off,
            houseDone: !!_pd.petHouseTutDone   // ★ v5.125.0 小屋首入教學
          };
          try{ window._petTutCloudFlagsReady = true; }catch(_){}
        }catch(_eTf){}
      }
    }catch(_eRdCache){ /* 讀不到快取就一律走 transaction,仍安全 */ }
    const _claimedSet = new Set(_claimedCache);

    const _now = Date.now();
    const _newlyClaimed = [];   // 本次真的領到的(供通知)
    const _toCacheAppend = [];  // 要補進 _grClaimed 快取的 id(含「已被認領」者,下次省 transaction)

    for(const _rw of _activeList){
      const _rid = _rw.id;
      if(!_rid) continue;
      if(_claimedSet.has(_rid)) continue;                       // 快取已標記 → 跳過
      if(_rw.expiresAt && _now > _rw.expiresAt) continue;        // 已過期 → 不領
      const _claimRef = doc(_fbDb, 'globalRewardClaims', _uid + '_' + _rid);
      // ① transaction 原子認領(權威防重複,免疫存檔合併復活)
      let _tx;
      try{
        _tx = await runTransaction(_fbDb, async (tx) => {
          const _cs = await tx.get(_claimRef);
          if(_cs.exists()) return { already: true };
          tx.set(_claimRef, {
            uid: _uid,
            rewardId: _rid,
            at: _now,
            items: Array.isArray(_rw.items) ? _rw.items.slice(0, 40) : [],
          });
          return { claimed: true };
        });
      }catch(e){
        // permission/network → 本次略過,下次登入再試(未標記、未發獎,不會重複)
        console.warn('[全體獎勵] 認領 transaction 失敗 rid=' + _rid, e);
        continue;
      }
      if(_tx && _tx.already){
        _toCacheAppend.push(_rid);   // 別的裝置/分頁已領 → 補快取,下次省 transaction
        continue;
      }
      if(!_tx || !_tx.claimed) continue;
      // ② 標記成功 → 發獎到自己(沿用 _fbCompensatePlayer 三槽寫入,union/max 合併不降級)
      try{
        if(typeof window._fbCompensatePlayer !== 'function') throw new Error('_fbCompensatePlayer 未載入');
        const _items = Array.isArray(_rw.items) ? _rw.items : [];
        await window._fbCompensatePlayer(_uid, Object.assign({}, _rw.reward || {}, {
          reason: '全體獎勵發放',
          summary: '全體獎勵：' + (_rw.title || '') + (_items.length ? ('（' + _items.join('、') + '）') : ''),
          by: 'globalReward:' + _rid,
        }));
        // ★ v3.17.8 — 一併帶 reward 原始 payload,讓登入端呼叫者能即時把 backpack 部分套進記憶體
        //   (比照 v3.16.97 GM課堂獎勵修法),免疫「沒重整就繼續遊戲→autosave 用舊背包沖掉剛領的獎勵」。
        _newlyClaimed.push({ id: _rid, title: _rw.title || '全體獎勵', items: _items, note: _rw.note || '', reward: _rw.reward || {} });
        _toCacheAppend.push(_rid);
        // ★ v3.17.8 — 自寫一筆 _grClaimLog(self-write),供 _fbReconcileGlobalRewardTickets 登入回溯對帳
        try{
          const _lps = await getDocFromServer(doc(_fbDb, 'players', _uid));
          let _glog = [];
          if(_lps.exists()){ const _lpd = _lps.data() || {}; if(Array.isArray(_lpd._grClaimLog)) _glog = _lpd._grClaimLog.slice(); }
          if(!_glog.some(function(e){ return e && e.rewardId === _rid; })){
            _glog.push({ rewardId: _rid, reward: _rw.reward || {}, items: _items.slice(0, 40), at: _now });
            if(_glog.length > 200) _glog = _glog.slice(-200);
            await setDoc(doc(_fbDb, 'players', _uid), { _grClaimLog: _glog }, { merge: true });
          }
        }catch(_eGLog){ console.warn('[全體獎勵] 寫入 _grClaimLog 失敗(不影響已發獎·僅影響回溯對帳)', _eGLog); }
      }catch(e){
        // 已標記但發獎異常 → 該獎勵這次漏發(認領文件已佔位,不會重複);記錄供老師補發
        console.error('[全體獎勵] 已認領但發獎失敗 rid=' + _rid + '（已佔位,不會重複領）', e);
      }
    }

    // ③ 更新玩家主檔 _grClaimed 快取(本次新領 + 已被認領者),下次登入直接跳過
    if(_toCacheAppend.length){
      try{
        const _merged = Array.from(new Set(_claimedCache.concat(_toCacheAppend))).slice(-200);
        await setDoc(doc(_fbDb, 'players', _uid), { _grClaimed: _merged }, { merge: true });
      }catch(_eWrCache){ console.warn('[全體獎勵] 寫入已領快取失敗(不影響防重複)', _eWrCache); }
    }
    return { claimed: _newlyClaimed };
  };

  // ★ v4.10.0 — 寵物教學旗標雲端寫入 helper(self-write players/{uid} 單欄·merge:true·免改規則):
  //   petTut1Done(第一階段聚光引導完成)/ petTut2Seen(馴養教學看過一次)/ petTut2Off(永久關閉)。
  //   非存檔白名單欄位 → gameCloudSave merge:true 不會清掉;跨裝置由 _fbClaimGlobalRewards 順讀。
  window._fbSetPetTutFlag = async function(field){
    try{
      const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb) return false;
      // ★ v5.125.0 — 新增 petHouseTutDone(小屋首入教學);原本純 localStorage ⇒ 換裝置必重跑
      if(['petTut1Done','petTut2Seen','petTut2Off','petHouseTutDone'].indexOf(field) < 0) return false;
      const _p = {}; _p[field] = Date.now();
      await setDoc(doc(_fbDb, 'players', _uid), _p, { merge: true });
      try{ window._petTutCloudFlags = window._petTutCloudFlags || {}; 
           if(field==='petTut1Done') window._petTutCloudFlags.t1Done = true;
           if(field==='petTut2Seen') window._petTutCloudFlags.t2Seen = true;
           if(field==='petTut2Off')  window._petTutCloudFlags.t2Off  = true;
           if(field==='petHouseTutDone') window._petTutCloudFlags.houseDone = true; }catch(_){}
      return true;
    }catch(_e){ console.warn('[寵物教學旗標寫入]', _e); return false; }
  };

  // ★ v5.141.0 — 教學旗標「主檔權威再確認」：啟動任何一次性教學前直接讀主檔（getDocFromServer 一次·零寫入），
  //   把四個旗標 OR 進 window._petTutCloudFlags。三槽合併與 _applySafeData 只是快取，主檔才是 _fbSetPetTutFlag 的落地點。
  window._fbRefreshPetTutFlags = async function(){
    try{
      const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb) return null;
      const _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(!_ps.exists()) return null;
      const _pd = _ps.data() || {};
      const _pf = window._petTutCloudFlags || {};
      window._petTutCloudFlags = {
        t1Done:    !!(_pf.t1Done    || _pd.petTut1Done),
        t2Seen:    !!(_pf.t2Seen    || _pd.petTut2Seen),
        t2Off:     !!(_pf.t2Off     || _pd.petTut2Off),
        houseDone: !!(_pf.houseDone || _pd.petHouseTutDone)
      };
      window._petTutCloudFlagsReady = true;
      return window._petTutCloudFlags;
    }catch(_e){ console.warn('[寵物教學旗標·主檔再確認] 讀取失敗，維持既有旗標', _e); return null; }
  };

  // ★ v4.65.0 — 主線劇情進度 self-write(players/{uid} merge·免改 rules·比照 _fbSetPetTutFlag)
  window._fbSaveMainStoryProgress = async function(progObj){
    try{
      const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb) return false;
      if(!progObj || typeof progObj !== 'object') return false;
      await setDoc(doc(_fbDb, 'players', _uid), { mainStoryProgress: progObj }, { merge: true });
      return true;
    }catch(_e){ console.warn('[主線進度寫入]', _e); return false; }
  };
  // ★ v4.65.0 — 登入後讀一次主檔 mainStoryProgress → hydrate(getDocFromServer 一次·比照 _fbReconcile*)
  window._msHydrateFromCloud = async function(){
    try{
      const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb){ if(typeof window._msHydrateProgress === 'function') window._msHydrateProgress(null); return; }
      let _pd = {};
      let _pdOk = false;   /* ★ v5.131.0 — 雲端主檔是否真的讀到(含「文件不存在」=合法的全新玩家);讀取失敗絕不解除造型上雲守門 */
      try{ const _ps = await getDocFromServer(doc(_fbDb, 'players', _uid)); _pdOk = true; if(_ps.exists()) _pd = _ps.data() || {}; }catch(_ep){}
      if(typeof window._msHydrateProgress === 'function') window._msHydrateProgress(_pd.mainStoryProgress || null);
      // ★ v5.7.0 — GM 回溯:avatarCard 帶 rst(後台重置寫入)且比本機 card 記錄的新 → 整份採用雲端重置版
      //   (cfg=預設・未覺醒・主線部件已剔),覆寫本機鏡像;同步覺醒旗標、清暱稱本機鍵、立繪簽章歸零重畫。
      //   只有被 GM 重置過的帳號才會有 rst 欄位,其他玩家此段零影響。
      //   (若不在登入時採用:avatar_db 的 _avatarPullFromCloud 只在造型工房開啟時跑,且要求 cloud.cfg 存在
      //    才採用;學生若不開工房,舊裝置的本機 card[舊臉/已覺醒]會一直生效,回溯等於沒發生。)
      try{
        const _avC = _pd.avatarCard;
        /* ★ v5.8.0 老師需求4 — 先做「卡片歸屬校正」:avatar_db 啟動時讀的是 guest 卡,
         *   這裡依當前 uid 重讀本機,下面的 rst/up 對時才是拿真的本機卡在比
         *   (v5.7.0 原邏輯若拿 guest 卡比 rst=0,雖冪等但不精確)。 */
        try{
          const _nowUH = _uid || 'guest';
          if(typeof window._avatarLoadLocal === 'function'
             && (!window._avatarLocalCard || window._avatarLocalCardUid !== _nowUH)){
            window._avatarLoadLocal();
          }
        }catch(_eLd){}
        /* ★ v5.131.0 — 採用雲端卡之前先快照「舊本機卡」的解鎖帳本與覺醒旗標:
         *   對帳前在本機入帳的部件解鎖(打BOSS/召喚/主線)只存在本機卡上,整份採用雲端會把它們蓋掉。
         *   unlock 是只增不減的帳本 → 採用後 union 回卡最安全;覺醒旗標取 OR。
         *   ★ GM 回溯(rst)分支刻意不 union —— 回溯的本意就是剝除,union 會讓回溯失效。 */
        let _avPrevUnlock = null, _avPrevAwk = false;
        try{
          const _pvC = window._avatarLocalCard;
          if(_pvC){ _avPrevUnlock = Array.isArray(_pvC.unlock) ? _pvC.unlock.slice() : null; _avPrevAwk = !!_pvC.protagAwakened; }
        }catch(_ePv){}
        const _avUnionPrev = function(){
          try{
            const _cd = window._avatarLocalCard; let _chg = false;
            if(_cd && _avPrevUnlock && _avPrevUnlock.length){
              if(!Array.isArray(_cd.unlock)) _cd.unlock = [];
              for(let _ui = 0; _ui < _avPrevUnlock.length; _ui++){
                if(_cd.unlock.indexOf(_avPrevUnlock[_ui]) === -1){ _cd.unlock.push(_avPrevUnlock[_ui]); _chg = true; }
              }
            }
            if(_cd && _avPrevAwk && !_cd.protagAwakened){
              _cd.protagAwakened = true;
              try{ window._protagAwakened = true; }catch(_eA){}
              _chg = true;
            }
            if(_chg){
              try{ if(typeof window._avatarSaveLocal === 'function') window._avatarSaveLocal(); }catch(_eS){}
              window._avatarCloudPushPending = true;   /* 對帳完成後補推,雲端帳本一併補齊 */
            }
          }catch(_eUn){}
        };
        /* ★ v5.131.0 — 「從未在工房儲存過的預設卡」判定(救回/補強分支共用):
         *   _avatarDefaultCfg 為純靜態物件 → JSON 比對可靠;工房的「全部重置/隨機」必經工房儲存
         *   ⇒ saveN≥1,而污染鏈產物來自 grant 路徑(工房關)⇒ saveN 不增,兩者可嚴格區分。 */
        const _avCfgIsDefault = function(c){
          try{ return !!c && typeof window._avatarDefaultCfg === 'function' && JSON.stringify(c) === JSON.stringify(window._avatarDefaultCfg()); }catch(_eD){ return false; }
        };
        /* 共用採用流程:整份採用雲端卡 + 覆寫本機鏡像 + 覺醒旗標 + 立繪簽章歸零重畫 */
        const _avAdopt = function(card, why){
          try{
            window._avatarLocalCard = card;
            try{ if(typeof window._avatarSaveLocal === 'function') window._avatarSaveLocal(); }catch(_eSv){}
            try{ window._protagAwakened = !!card.protagAwakened; }catch(_ePa){}
            try{
              window._lxpsProtagPortraitDone = false;
              window._lxpsProtagPortraitSig = '';
              window._lxpsProtagPortraitBusy = false;
              if(typeof window._lxpsProtagPortraitRefresh === 'function') window._lxpsProtagPortraitRefresh();
            }catch(_ePr){}
            console.warn('[主角造型] 已採用雲端卡(' + why + ')');
          }catch(_eAd){}
        };
        let _avAdopted = false;
        if(_avC && typeof _avC.rst === 'number'){
          const _avL = window._avatarLocalCard;
          const _avLr = (_avL && typeof _avL.rst === 'number') ? _avL.rst : 0;
          if(_avLr < _avC.rst){
            _avAdopt(_avC, 'GM 回溯 rst=' + _avC.rst);
            _avAdopted = true;
            try{ if(!_avC.nick && _uid) localStorage.removeItem('lxps_nickname_' + _uid); }catch(_eNk){}
            try{ window._avatarNickname = (_avC.nick || ''); }catch(_eNm){}
          }
        }
        /* ★ v5.8.0 老師需求4 — up 對時(跨裝置同步 + 雲端寫入失敗自癒):
         *   ①換新平板(本機 localStorage 根本沒這位學生的卡)且雲端有 cfg → 直接採用雲端
         *     (學生不必開造型工房,圖鑑/戰鬥卡登入即正確);
         *   ②雲端 up 較新(別台裝置存過)→ 採用雲端;
         *   ③本機 up 較新(上次雲端儲存失敗)→ 補推上雲自癒。
         *   舊卡沒有 up 欄位視為 0(0=0 → 維持本機,行為與 v5.7.0 相同);GM 回溯已在上方處理。 */
        if(!_avAdopted && _avC && _avC.cfg){
          try{
            const _lsRaw = _uid ? localStorage.getItem('lxps_avatarCard_' + _uid) : null;
            const _avL2 = window._avatarLocalCard;
            const _cUp = (typeof _avC.up === 'number') ? _avC.up : 0;
            const _lUp = (_avL2 && typeof _avL2.up === 'number') ? _avL2.up : 0;
            if(!_lsRaw || !_avL2 || !_avL2.cfg){
              _avAdopt(_avC, '新裝置還原');
              _avUnionPrev();   /* ★ v5.131.0 — 對帳前本機入帳的解鎖 union 回卡,不遺失 */
              try{ if(typeof _avC.nick === 'string' && _avC.nick) window._avatarNickname = _avC.nick; }catch(_eN2){}
            } else if(_lUp === 0 && !((_avL2.saveN|0)) && _avCfgIsDefault(_avL2.cfg)){
              /* ★ v5.131.0 補強 — 本機有卡但是「從未儲存過的預設卡」(up=0·saveN=0·cfg=預設):
               *   舊守門只認「本機完全沒卡」才還原,這種早期寫入的預設卡會卡在 0=0 分支永不還原。 */
              _avAdopt(_avC, '本機為未儲存預設卡,採用雲端');
              _avUnionPrev();
              try{ if(typeof _avC.nick === 'string' && _avC.nick) window._avatarNickname = _avC.nick; }catch(_eN4){}
            } else if(_cUp > _lUp){
              /* ★ v5.131.0 既損救回 — 雲端 up 雖較新,但雲端卡是「從未在工房儲存過的預設卡」
               *   (=污染鏈產物:別台裝置在對帳前把預設卡整包推上雲)而本機持有真造型
               *   → 不採用雲端,改保留本機並於對帳完成後推回上雲自癒。
               *   ★ 不會誤殺「玩家真的重置成預設」:工房重置必經工房儲存 ⇒ 雲端卡 saveN≥1 不命中本謂詞。 */
              if(!((_avC.saveN|0)) && !(typeof _avC.rst === 'number') && _avCfgIsDefault(_avC.cfg) && !_avCfgIsDefault(_avL2.cfg)){
                window._avatarCloudPushPending = true;
                console.warn('[主角造型] 雲端疑為被污染的預設卡(saveN=0),保留本機真造型並補推自癒');
              } else {
                _avAdopt(_avC, '雲端較新 up=' + _cUp);
                _avUnionPrev();   /* ★ v5.131.0 — 同上,解鎖帳本只增不減 */
                try{ if(typeof _avC.nick === 'string' && _avC.nick) window._avatarNickname = _avC.nick; }catch(_eN3){}
              }
            } else if(_lUp > _cUp){
              /* ★ v5.131.0 — 自癒改走 pending:此刻守門旗標尚未解除,直接呼叫會被自己的守門擋下;
               *   統一由段尾「對帳完成」補推(舊直接呼叫行保留備查)。 */
              window._avatarCloudPushPending = true;
              /* 舊:try{ if(typeof window._avatarSaveToCloud === 'function') Promise.resolve(window._avatarSaveToCloud()).catch(function(){}); }catch(_eHl){} */
              console.warn('[主角造型] 本機較新,對帳後補推上雲自癒(up=' + _lUp + ')');
            }
          }catch(_eUp){}
        }
        /* ★ v5.8.0 老師需求4(重開遊戲臉變預設根治)— 對帳後立繪簽章比對:
         *   啟動 poll 可能已用 guest 預設卡畫過並以預設 cfg 簽章上鎖,這裡拿「正確的卡」
         *   再比一次,簽章不一致 → 歸零重畫。無論上面有沒有採用雲端都要做(採用路徑已自帶重畫,冪等)。 */
        try{
          const _cardF = window._avatarLocalCard;
          if(_cardF && _cardF.cfg){
            let _sigF = ''; try{ _sigF = JSON.stringify(_cardF.cfg); }catch(_eSg){}
            try{ _sigF += '|D' + JSON.stringify(window._avatarPartDefaults || {}); }catch(_eSd){}   /* ★ v5.15.0 與立繪簽章同格式(cfg+管理員部件預設表) */
            if(_sigF && window._lxpsProtagPortraitSig !== _sigF){
              window._lxpsProtagPortraitDone = false;
              window._lxpsProtagPortraitSig = '';
              window._lxpsProtagPortraitBusy = false;
              if(typeof window._lxpsProtagPortraitRefresh === 'function') window._lxpsProtagPortraitRefresh();
            }
          }
        }catch(_eFix){}
        /* ★ v5.9.0 — 登入對帳完成後全面補判主角類獎章(主線進度/avatarCard/BD 都已就緒;
         *   已完成章節或已打扮過的舊玩家,登入即自動回溯發章,冪等零重複發獎)。 */
        try{ if(typeof window._protagMedalSweep === 'function') window._protagMedalSweep(); }catch(_eMdl){}
        try{ if(typeof window._minigameMedalSweep === 'function') window._minigameMedalSweep(); }catch(_eMg){}
        /* ★★ v5.131.0 — 造型對帳完成:解除上雲守門+補推。
         *   只有「雲端主檔真的讀到」(_pdOk·含合法的全新玩家無文件)才解除;讀取失敗維持守門
         *   =該次登入的部件解鎖只落地本機,下次成功對帳時由 union+pending 一併補上雲,零遺失。 */
        try{
          if(_pdOk){
            window._avatarCloudReconciled = true;
            if(window._avatarCloudPushPending){
              window._avatarCloudPushPending = false;
              if(typeof window._avatarSaveToCloud === 'function') Promise.resolve(window._avatarSaveToCloud()).catch(function(){});
            }
          }
        }catch(_eRc){}
      }catch(_eAvR){ console.warn('[主角回溯採用]', _eAvR); }
    }catch(_e){ console.warn('[主線進度讀取]', _e); if(typeof window._msHydrateProgress === 'function') window._msHydrateProgress(null); }
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v3.17.8 — 回溯救援:登入對帳「已領全體獎勵自選卷·實際沒拿到的補上」
  //   鏡像 v3.16.97 / v3.17.8 序號版,讀玩家自己主檔的 _grClaimLog(self-write)。
  //   同一份 _GMCR_PICK_TICKET_SRC 定義(4 種自選卷)。
  //   安全不等式同款:已發(全體獎勵 reward.backpack)− 已用(durable 帳本)− 現有(背包)− 已補(冪等記) > 0 才補。
  // ════════════════════════════════════════════════════════════════════
  window._fbReconcileGlobalRewardTickets = async function(){
    try{
      var _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb || !window._GMCR_PICK_TICKET_SRC) return;
      var _pd = {};
      try{ var _ps = await getDocFromServer(doc(_fbDb, 'players', _uid)); if(_ps.exists()) _pd = _ps.data() || {}; }
      catch(_ePd){ return; }
      var _mine = Array.isArray(_pd._grClaimLog) ? _pd._grClaimLog : [];
      if(!_mine.length) return;
      var _recovered = (_pd._grRecoveredTickets && typeof _pd._grRecoveredTickets === 'object') ? Object.assign({}, _pd._grRecoveredTickets) : {};
      var _RECONCILE_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;
      var _nowR = Date.now();
      var _granted = {};
      _mine.forEach(function(rw){
        if(!rw || !rw.at) return;
        var _bp = (rw.reward && typeof rw.reward === 'object') ? rw.reward.backpack : null;
        if(!_bp || typeof _bp !== 'object') return;
        var _isOld = !!((_nowR - rw.at) > _RECONCILE_WINDOW_MS);
        Object.keys(window._GMCR_PICK_TICKET_SRC).forEach(function(_k){
          if(_isOld && window._GMCR_PICK_TICKET_SRC[_k].ledger === '_heroUnlockHistory') return;
          var _n = Math.max(0, parseInt(_bp[_k], 10) || 0);
          if(_n > 0) _granted[_k] = (_granted[_k] || 0) + _n;
        });
      });
      if(!Object.keys(_granted).length) return;
      var _countSrc = function(ledgerKey, src){
        var _arr = Array.isArray(_pd[ledgerKey]) ? _pd[ledgerKey] : [];
        var _c = 0;
        _arr.forEach(function(e){ if(e && e.source === src) _c++; });
        return _c;
      };
      var _toGrant = {};
      Object.keys(_granted).forEach(function(_k){
        var _def = window._GMCR_PICK_TICKET_SRC[_k];
        var _used = _countSrc(_def.ledger, _def.source);
        var _held = (typeof backpackGet === 'function') ? (backpackGet(_k) || 0) : 0;
        var _rec  = Math.max(0, parseInt(_recovered[_k], 10) || 0);
        var _short = (_granted[_k] || 0) - _used - _held - _rec;
        if(_short > 0) _toGrant[_k] = _short;
      });
      if(!Object.keys(_toGrant).length) return;
      var _labels = [];
      Object.keys(_toGrant).forEach(function(_k){
        var _n = _toGrant[_k];
        try{ if(typeof backpackAdd === 'function') backpackAdd(_k, _n); }catch(_eAdd){}
        _recovered[_k] = (Math.max(0, parseInt(_recovered[_k], 10) || 0)) + _n;
        _labels.push(window._GMCR_PICK_TICKET_SRC[_k].label + '×' + _n);
      });
      try{ await setDoc(doc(_fbDb, 'players', _uid), { _grRecoveredTickets: _recovered }, { merge: true }); }
      catch(_eMark){ console.warn('[全體獎勵對帳] 寫冪等標記失敗(背包已補·下次因 held 已有不會重補)', _eMark); }
      try{ if(typeof _showInGameToast === 'function') _showInGameToast('🎁 補發了你全體獎勵漏拿到的：' + _labels.join('、'), '#66dd88', 4500); }catch(_eToast){}
      try{ console.log('[全體獎勵對帳 v3.17.8] 補發漏領自選卷', _toGrant); }catch(_){}
    }catch(_eAll){ try{ console.warn('[全體獎勵對帳] 例外(略過·不影響登入)', _eAll); }catch(_){} }
  };

  // 玩家:全體獎勵到帳通知彈窗(列出本次領到的獎勵 + 重新整理鈕,沿用序號兌換成功的 UX)
  window._showGlobalRewardNotice = function(list){
    try{
      if(!Array.isArray(list) || !list.length) return;
      const _esc = function(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
      let _blocks = '';
      list.forEach(function(rw){
        const _items = Array.isArray(rw.items) ? rw.items : [];
        _blocks += '<div style="margin:10px 0;padding:10px 12px;background:rgba(255,210,90,0.10);'
          + 'border:1px solid rgba(255,210,90,0.45);border-radius:10px;text-align:left;">'
          + '<div style="color:#ffe066;font-weight:900;font-size:17px;">🎁 ' + _esc(rw.title || '全體獎勵') + '</div>'
          + (rw.note ? ('<div style="color:#cbd6ea;font-size:12px;margin:3px 0 6px;">' + _esc(rw.note) + '</div>') : '')
          + (_items.length ? ('<div style="color:#fff;font-size:15px;font-weight:800;line-height:1.8;">'
              + _items.map(_esc).join('<br>') + '</div>') : '')
          + '</div>';
      });
      // 移除舊的(避免重複)
      try{ const _old = document.getElementById('_global-reward-notice'); if(_old) _old.remove(); }catch(_){}
      const _ov = document.createElement('div');
      _ov.id = '_global-reward-notice';
      _ov.style.cssText = 'position:fixed;inset:0;z-index:99000;display:flex;align-items:center;justify-content:center;'
        + 'background:rgba(0,0,0,0.72);padding:20px;';
      _ov.innerHTML = '<div style="max-width:440px;width:100%;max-height:86vh;overflow-y:auto;'
        + 'background:linear-gradient(160deg,#1a2548,#0e1730);border:2px solid rgba(255,210,90,0.6);'
        + 'border-radius:18px;padding:22px 20px;box-shadow:0 10px 40px rgba(0,0,0,0.6);text-align:center;'
        + 'font-family:inherit;">'
        + '<div style="font-size:26px;font-weight:900;color:#ffd54f;letter-spacing:1px;">🎉 你收到全體獎勵！</div>'
        + '<div style="font-size:13px;color:#bbcce0;margin-top:4px;">老師發送給全班的獎勵已存入你的帳號</div>'
        + _blocks
        + '<div style="font-size:12px;color:#9fb0cc;margin-top:6px;">重新整理後就能看到囉！</div>'
        + '<div style="display:flex;gap:10px;margin-top:14px;justify-content:center;flex-wrap:wrap;">'
        + '<button onclick="_lxpsReloadKeepLoginIfLoggedIn()" style="padding:11px 22px;font-size:15px;font-weight:800;'   /* ★ v5.148.0 舊:onclick=location.reload() 會被攔截器踢出 */
        + 'background:linear-gradient(135deg,#2a8a3a,#1d7a2a);border:2px solid #66dd88;color:#fff;'
        + 'border-radius:10px;cursor:pointer;font-family:inherit;letter-spacing:1px;">🔄 重新整理看獎勵</button>'
        + '<button onclick="(function(){var e=document.getElementById(\'_global-reward-notice\');if(e)e.remove();})()" '
        + 'style="padding:11px 18px;font-size:14px;font-weight:700;background:rgba(120,140,180,0.25);'
        + 'border:1.5px solid rgba(150,170,210,0.5);color:#dfe7f5;border-radius:10px;cursor:pointer;'
        + 'font-family:inherit;">稍後再看</button>'
        + '</div></div>';
      document.body.appendChild(_ov);
      try{ if(typeof playSfx === 'function') playSfx('sfx-coin', 0.85); }catch(_){}
    }catch(e){ console.warn('[全體獎勵通知] 彈窗失敗', e); }
  };

  // ════════════════════════════════════════════════════════════════════════════
  // ★ v3.16.65 — GM 課堂獎勵「拉取制」收件(逐玩家) + 手動「確認領取」
  // ────────────────────────────────────────────────────────────────────────────
  //   把「課堂獎勵發放」由 push(_fbCompensatePlayer 直接寫)改為 pull(玩家領取):
  //     ① GM 指派 → 寫該玩家收件箱 gmClassRewards/{uid}/items/{autoId}
  //          = { uid, label, email, reward(_fbCompensatePlayer payload),
  //              itemsLabel[](顯示用), merit(事蹟·發獎理由), by, at, enabled:true }
  //     ② 玩家在「🎁 GM獎勵」看到「事蹟 + 獎項名稱數量」→ 按「確認領取」:
  //        對「獨立認領文件」gmClassRewardClaims/{uid}_{rewardId} 做 transaction
  //        (tx.get 已存在→視為已領、不重發;不存在→tx.set 認領)。
  //        認領文件 docId 前綴綁 uid + create-only → 永不被三槽 richest-merge 復活、
  //        跨裝置/分頁不重複領、不跨帳號污染(同 globalRewardClaims 模型)。
  //     ③ 認領成功才以「伺服器重讀的權威 reward」_fbCompensatePlayer 入帳(不信任 client 傳入,防竄改 UR/數量)。
  //   ★ 防同裝置帳號污染核心:rule 只讓玩家讀/領自己 uid 的收件箱 → 共用 iPad 上 B 同學
  //     看不到也領不到 A 同學的 UR 獎勵;獎勵只在「正確學生登入且主動領取」時才套用到其存檔。
  //   ⚠ 需部署 firestore.rules:gmClassRewards(GM 寫·玩家讀自己) + gmClassRewardClaims(create-only·docId 前綴=uid)。
  // ════════════════════════════════════════════════════════════════════════════

  // GM:指派一筆課堂獎勵到某玩家收件箱。reward = _buildReward payload;itemsLabel = 顯示用文字陣列;merit = 事蹟
  window._fbWriteGmClassReward = async function(uid, label, email, reward, itemsLabel, merit){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    if(!uid) throw new Error('uid 不可為空');
    const _by = (window._fbUser && window._fbUser.email) || 'admin';
    const _now = Date.now();
    const _doc = {
      uid: String(uid),
      label: String(label || '').slice(0, 80),
      email: String(email || '').slice(0, 80),
      reward: reward || {},
      itemsLabel: Array.isArray(itemsLabel) ? itemsLabel.slice(0, 40) : [],
      merit: String(merit || '').slice(0, 120),
      by: String(_by).slice(0, 60),
      at: _now,
      enabled: true,
    };
    const _ref = doc(collection(_fbDb, 'gmClassRewards', String(uid), 'items'));
    await setDoc(_ref, _doc);
    console.info('✅ [GM課堂獎勵] 已指派給 ' + uid + ' → ' + _ref.id);
    return { ok: true, id: _ref.id };
  };

  // 玩家:讀自己收件箱「尚未領取」的有效獎勵(供「🎁 GM獎勵」收件區 + 鈕上方標籤)。回傳待領陣列(新→舊)。
  window._fbReadMyGmClassRewards = async function(){
    const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
    if(!_uid || !_fbDb) return [];
    let _all = [];
    try{
      const _snap = await getDocs(collection(_fbDb, 'gmClassRewards', _uid, 'items'));
      _snap.forEach(function(d){ _all.push(Object.assign({ id: d.id }, d.data() || {})); });
    }catch(e){
      console.warn('[GM獎勵] 讀取收件箱失敗(可能規則未部署)', e);
      return [];
    }
    if(!_all.length) return [];
    // 讀玩家主檔「已領快取」_gmcrClaimed → 過濾已領(權威仍是認領文件,快取只是省領取重試/避免顯示已領)
    let _claimedCache = [];
    try{
      const _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(_ps.exists()){
        const _pd = _ps.data() || {};
        if(Array.isArray(_pd._gmcrClaimed)) _claimedCache = _pd._gmcrClaimed.slice();
      }
    }catch(_eRd){ /* 讀不到快取就不過濾,領取時 transaction 仍會擋重複 */ }
    const _claimedSet = new Set(_claimedCache);
    const _now = Date.now();
    const _pending = [];
    _all.forEach(function(rw){
      if(!rw.id) return;
      if(rw.enabled === false) return;
      if(rw.expiresAt && _now > rw.expiresAt) return;
      if(_claimedSet.has(rw.id)) return;
      _pending.push(rw);
    });
    _pending.sort(function(a, b){ return (b.at || 0) - (a.at || 0); });
    return _pending;
  };

  // 玩家:領取單筆課堂獎勵。transaction 原子認領(免疫存檔復活/跨裝置重複),認領成功才以「伺服器權威 reward」入帳。
  //   回傳 { ok, already, reason, itemsLabel, merit }
  window._fbClaimGmClassReward = async function(rewardId){
    const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
    if(!_uid || !_fbDb) return { ok: false, reason: '尚未連線,請稍後再試' };
    if(!rewardId) return { ok: false, reason: '獎勵代碼錯誤' };
    // ① 伺服器重讀該獎勵(權威來源,不信任 client 傳入的 reward 內容,防竄改 UR/數量)
    let _rw;
    try{
      const _rs = await getDocFromServer(doc(_fbDb, 'gmClassRewards', _uid, 'items', rewardId));
      if(!_rs.exists()) return { ok: false, reason: '這筆獎勵不存在或已被收回' };
      _rw = Object.assign({ id: _rs.id }, _rs.data() || {});
    }catch(e){
      return { ok: false, reason: '讀取獎勵失敗,請稍後再試' };
    }
    if(_rw.enabled === false) return { ok: false, reason: '這筆獎勵已被老師停用' };
    if(_rw.expiresAt && Date.now() > _rw.expiresAt) return { ok: false, reason: '這筆獎勵已過期' };
    const _itemsLabel = Array.isArray(_rw.itemsLabel) ? _rw.itemsLabel : [];
    const _now = Date.now();
    const _claimRef = doc(_fbDb, 'gmClassRewardClaims', _uid + '_' + rewardId);
    const _playerRef = doc(_fbDb, 'players', _uid);
    // ★ v3.16.94 — 領取防重複「主閘門」改用玩家自己主檔的 _gmcrClaimed 陣列(self-write 永遠可寫,
    //   不依賴 gmClassRewards/gmClassRewardClaims 規則是否部署)。根治「transaction 寫入被規則擋 →
    //   領取失敗 re-enable → 無限空轉、沒入帳」:即使規則未部署,自寫 _gmcrClaimed 仍能標記已領,
    //   收件箱(_fbReadMyGmClassRewards 已用 _gmcrClaimed 過濾)立刻隱藏該筆 → 鈕不再空轉,
    //   發放成功就會出現在召喚頁。gmClassRewardClaims transaction 降為「最佳努力跨裝置去重」
    //   (規則部署時生效;未部署則靜默跳過,改靠 self-write 閘門 + 同頁鈕禁用防重複)。
    // ①.5 先讀自己主檔 _gmcrClaimed:若已含本筆 → 已領過,直接擋(免重複入帳)
    try{
      const _pre = await getDocFromServer(_playerRef);
      if(_pre.exists()){
        const _pd = _pre.data() || {};
        if(Array.isArray(_pd._gmcrClaimed) && _pd._gmcrClaimed.indexOf(rewardId) >= 0){
          return { ok: false, already: true, reason: '這筆獎勵已經領過了' };
        }
      }
    }catch(_ePre){ /* 讀不到快取就往下走,後面 transaction / 標記仍會把關 */ }
    // ② 最佳努力 transaction 跨裝置去重(規則部署時生效;未部署則 catch 後靜默改走 self-write 閘門)
    let _txAlready = false;
    try{
      const _tx = await runTransaction(_fbDb, async (tx) => {
        const _cs = await tx.get(_claimRef);
        if(_cs.exists()) return { already: true };
        tx.set(_claimRef, { uid: _uid, rewardId: rewardId, at: _now, items: _itemsLabel.slice(0, 40) });
        return { claimed: true };
      });
      if(_tx && _tx.already) _txAlready = true;
    }catch(_eTx){
      console.warn('[GM獎勵] 認領 transaction 無法寫入(規則可能未部署),改用主檔 _gmcrClaimed 自寫閘門 rid=' + rewardId, _eTx);
    }
    if(_txAlready) return { ok: false, already: true, reason: '這筆獎勵已經領過了' };
    // ②.5 ★ 主閘門:發獎「之前」先以 self-write 標記 _gmcrClaimed(read-modify-write,等效 arrayUnion)。
    //   self-write 永遠可寫(players/{uid} 規則允許本人寫非停權欄位),標記成功 → 收件箱立即隱藏該筆。
    //   標記失敗才中止(可重試;尚未發獎不會重複扣發)。
    try{
      const _ps = await getDocFromServer(_playerRef);
      let _cacheBefore = [];
      if(_ps.exists()){
        const _pd = _ps.data() || {};
        if(Array.isArray(_pd._gmcrClaimed)) _cacheBefore = _pd._gmcrClaimed.slice();
      }
      // 競態保險:重讀後再確認一次未領(防 ② 與此處之間被別處標記)
      if(_cacheBefore.indexOf(rewardId) >= 0) return { ok: false, already: true, reason: '這筆獎勵已經領過了' };
      const _markedCache = Array.from(new Set(_cacheBefore.concat([rewardId]))).slice(-300);
      await setDoc(_playerRef, { _gmcrClaimed: _markedCache }, { merge: true });
    }catch(_eMark){
      console.warn('[GM獎勵] 標記 _gmcrClaimed 失敗(尚未發獎·可重試)rid=' + rewardId, _eMark);
      return { ok: false, reason: '領取失敗,請稍後再試(未發放,可再試)' };
    }
    // ③ 已標記 → 以伺服器權威 reward 入帳(_fbCompensatePlayer 三槽 union/max,只增不減)
    try{
      if(typeof window._fbCompensatePlayer !== 'function') throw new Error('_fbCompensatePlayer 未載入');
      await window._fbCompensatePlayer(_uid, Object.assign({}, _rw.reward || {}, {
        reason: '課堂獎勵領取',
        summary: '課堂獎勵' + (_rw.merit ? ('（' + _rw.merit + '）') : '') + (_itemsLabel.length ? ('：' + _itemsLabel.join('、')) : ''),
        by: 'gmClassReward:' + rewardId,
      }));
    }catch(e){
      // ★ 發獎失敗 → 回滾標記(把 rewardId 從 _gmcrClaimed 移除),讓學生可重新領取,避免「標記了卻沒入帳」永久卡住
      console.error('[GM獎勵] 入帳失敗·回滾 _gmcrClaimed 標記 rid=' + rewardId, e);
      try{
        const _rb = await getDocFromServer(_playerRef);
        let _rbCache = [];
        if(_rb.exists()){ const _rbd = _rb.data() || {}; if(Array.isArray(_rbd._gmcrClaimed)) _rbCache = _rbd._gmcrClaimed.slice(); }
        const _rolled = _rbCache.filter(function(x){ return x !== rewardId; });
        await setDoc(_playerRef, { _gmcrClaimed: _rolled }, { merge: true });
      }catch(_eRb){ console.error('[GM獎勵] 回滾標記也失敗(請通知老師補發)rid=' + rewardId, _eRb); }
      return { ok: false, reason: '入帳發生異常,請稍後再試(已回復·可再領)' };
    }
    // ★ v3.17.6(老師需求 2)— 入帳成功 → 若本筆獎勵含 GM 召喚卷,記錄「發放理由(事蹟)+時間」到本機中繼資料,
    //   供背包/召喚星空顯示「🎁 老師發放理由…（時間）」。純本機顯示用,不影響入帳/存檔。
    try{
      if(typeof window._recordGmTicketMeta === 'function' && _rw && _rw.reward && _rw.reward.backpack){
        window._recordGmTicketMeta(_uid, _rw.reward.backpack, _rw.merit || '', _now);
      }
    }catch(_eMeta){ try{ console.warn('[GM獎勵] 記錄 GM 卷理由時間失敗(不影響領取)', _eMeta); }catch(_){} }
    // ④ 入帳成功 → 補寫 _gmcrClaimLog 領取紀錄(_gmcrClaimed 已於 ②.5 標記;此處只補紀錄)
    //    ★ v3.16.66 — 領取紀錄(獎項名/事蹟/獎項清單/領取時間)寫主檔(self-write·不需改 rule),
    //      供學生「✅已領取紀錄」顯示 + GM 後台查(根治「學生領完收件區空白→不認帳」)。
    try{
      const _ps2 = await getDocFromServer(_playerRef);
      let _cache2 = [], _log = [];
      if(_ps2.exists()){
        const _pd2 = _ps2.data() || {};
        if(Array.isArray(_pd2._gmcrClaimed)) _cache2 = _pd2._gmcrClaimed.slice();
        if(Array.isArray(_pd2._gmcrClaimLog)) _log = _pd2._gmcrClaimLog.slice();
      }
      const _merged = Array.from(new Set(_cache2.concat([rewardId]))).slice(-300);
      if(!_log.some(function(e){ return e && e.rewardId === rewardId; })){
        _log.push({ rewardId: rewardId, label: String(_rw.label || '').slice(0, 80),
                    merit: String(_rw.merit || '').slice(0, 120),
                    items: _itemsLabel.slice(0, 40), at: _now });
        if(_log.length > 200) _log = _log.slice(-200);
      }
      await setDoc(_playerRef, { _gmcrClaimed: _merged, _gmcrClaimLog: _log }, { merge: true });
    }catch(_eWr){ console.warn('[GM獎勵] 寫入已領紀錄失敗(不影響防重複·已標記)', _eWr); }
    // ★ v3.16.97 — 甲:回傳結構化 reward,讓 client 領取後「即時把獎勵套進記憶體背包」(防 autosave 覆蓋丟券)
    return { ok: true, itemsLabel: _itemsLabel, merit: _rw.merit || '', reward: (_rw.reward && typeof _rw.reward === 'object') ? _rw.reward : {} };
  };

  // ════════════════════════════════════════════════════════════════
  // ★ v3.16.97 — 回溯救援:登入對帳「已領課堂獎勵自選卷·實際沒拿到的補上」
  // ────────────────────────────────────────────────────────────────
  // 背景:v3.16.96 前的領取流程把獎勵寫雲端但「未即時套進記憶體」→ 若領取後 autosave
  //   搶先寫了「沒票券」的槽,_lxpsMergeSlots 消耗型背包「只取最新槽」會把雲端授予的自選卷丟掉
  //   → 學生「標記領過(_gmcrClaimed)卻沒實際拿到券」,且收件箱已過濾不再顯示=領不回。
  // 安全不等式(★永不重複發):
  //   被丟 = 已發(課堂獎勵·讀「伺服器」收件箱權威 reward.backpack)
  //          − 已用(durable 帳本:_heroUnlockHistory source ticket_*_pick
  //                   / _treasureUnlockHistory source treasure_pick_ticket·皆 union 撐過 merge)
  //          − 現有(背包) − 已補(_gmcrRecoveredTickets 冪等標記)
  //   > 0 才補。① 已用掉的(lucky+used)其帳本 source 計數會抵掉→不補(不重複發)
  //            ② 補後 held↑+recovered↑ 雙記→即使再被舊版 client 丟,recovered 擋住不無限補
  //            ③ 之後再發新一批同型券,granted↑→只補新缺額(invariant 自洽)
  // 僅針對「自選卷」4 種;只補不扣;不採信 client 數量(讀伺服器收件箱);全程 try-catch 不影響登入。
  // ════════════════════════════════════════════════════════════════
  window._GMCR_PICK_TICKET_SRC = {
    'summon_ticket_ur_pick':       { ledger: '_heroUnlockHistory',     source: 'ticket_ur_pick',       label: 'UR自選召喚卷' },
    'summon_ticket_ssr_pick':      { ledger: '_heroUnlockHistory',     source: 'ticket_ssr_pick',      label: 'SSR自選召喚卷' },
    'summon_ticket_sr_pick':       { ledger: '_heroUnlockHistory',     source: 'ticket_sr_pick',       label: 'SR自選召喚卷' },
    'summon_ticket_treasure_pick': { ledger: '_treasureUnlockHistory', source: 'treasure_pick_ticket', label: '自選至寶召喚卷' }
  };
  window._fbReconcileGmClassRewardTickets = async function(){
    try{
      var _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
      if(!_uid || !_fbDb) return;
      // ① 讀「伺服器」收件箱(權威 reward),失敗(規則未部署/離線)→ 靜默,下次再試
      var _inbox = [];
      try{
        var _snap = await getDocs(collection(_fbDb, 'gmClassRewards', _uid, 'items'));
        _snap.forEach(function(d){ _inbox.push(Object.assign({ id: d.id }, d.data() || {})); });
      }catch(_eRd){ return; }
      if(!_inbox.length) return;
      // ② 讀主檔:_gmcrClaimed(只對「已領」對帳)/ _gmcrRecoveredTickets(冪等)/ 兩 durable 帳本(已用)/ _gmcrClaimLog
      var _pd = {};
      try{ var _ps = await getDocFromServer(doc(_fbDb, 'players', _uid)); if(_ps.exists()) _pd = _ps.data() || {}; }
      catch(_ePd){ return; }
      var _claimedSet = {};
      (Array.isArray(_pd._gmcrClaimed) ? _pd._gmcrClaimed : []).forEach(function(x){ _claimedSet[x] = 1; });
      var _recovered = (_pd._gmcrRecoveredTickets && typeof _pd._gmcrRecoveredTickets === 'object') ? Object.assign({}, _pd._gmcrRecoveredTickets) : {};
      // granted[X] = Σ 已領收件箱 reward.backpack[X](只算自選卷 key·只算 _gmcrClaimed 內的)
      // ★ v3.16.97 防護:① 跳過已撤銷(enabled:false)獎勵→不補回 GM 已撤回的券
      //   ② 近 30 天窗:舊批次的「英雄自選卷」跳過(_heroUnlockHistory 封頂 200 筆·過舊的 used 紀錄
      //      可能被擠掉→誤判沒用過→多補);「至寶自選卷」豁免此窗(_treasureUnlockHistory 永不到 200
      //      筆·used 永遠算得到·任何時間都安全)。對齊老師「寧可少補不重複發」。
      var _RECONCILE_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;   // 30 天
      var _nowR = Date.now();
      var _granted = {};
      _inbox.forEach(function(rw){
        if(!rw || !rw.id || !_claimedSet[rw.id]) return;     // 沒領的不對帳(會在收件箱正常顯示·走正常領取)
        if(rw.enabled === false) return;                     // ★ 防護①:已撤銷的不補
        var _bp = (rw.reward && rw.reward.backpack && typeof rw.reward.backpack === 'object') ? rw.reward.backpack : null;
        if(!_bp) return;
        var _isOld = !!(rw.at && (_nowR - rw.at) > _RECONCILE_WINDOW_MS);
        Object.keys(window._GMCR_PICK_TICKET_SRC).forEach(function(_k){
          // ★ 防護②:舊批次 + 帳本會封頂(英雄帳本)→ used 可能過期不可靠 → 跳過(至寶帳本不封頂→照算)
          if(_isOld && window._GMCR_PICK_TICKET_SRC[_k].ledger === '_heroUnlockHistory') return;
          var _q = Math.max(0, parseInt(_bp[_k], 10) || 0);
          if(_q > 0) _granted[_k] = (_granted[_k] || 0) + _q;
        });
      });
      if(!Object.keys(_granted).length) return;               // 從沒發過自選卷(或都被窗/撤銷過濾掉)→ 免對帳
      // used[X] = durable 帳本對應 source 計數(撐過 merge)
      var _countSrc = function(ledgerKey, src){
        var _arr = Array.isArray(_pd[ledgerKey]) ? _pd[ledgerKey] : [];
        var _c = 0;
        _arr.forEach(function(e){ if(e && e.source === src) _c++; });
        return _c;
      };
      // ③ 逐券種 shortfall = granted − used − held − recovered
      var _toGrant = {};
      Object.keys(_granted).forEach(function(_k){
        var _def = window._GMCR_PICK_TICKET_SRC[_k];
        var _used = _countSrc(_def.ledger, _def.source);
        var _held = (typeof backpackGet === 'function') ? (backpackGet(_k) || 0) : 0;
        var _rec  = Math.max(0, parseInt(_recovered[_k], 10) || 0);
        var _short = (_granted[_k] || 0) - _used - _held - _rec;
        if(_short > 0) _toGrant[_k] = _short;
      });
      if(!Object.keys(_toGrant).length) return;               // 都拿到/用掉了 → 不補(不重複發)
      // ④ 補:backpackAdd(即時記憶體+排程上雲)+ 冪等標記 + 救援紀錄(self-write·永遠可寫)
      var _labels = [];
      Object.keys(_toGrant).forEach(function(_k){
        var _n = _toGrant[_k];
        try{ if(typeof backpackAdd === 'function') backpackAdd(_k, _n); }catch(_eAdd){}
        _recovered[_k] = (Math.max(0, parseInt(_recovered[_k], 10) || 0)) + _n;
        _labels.push(window._GMCR_PICK_TICKET_SRC[_k].label + '×' + _n);
      });
      try{
        var _log = Array.isArray(_pd._gmcrClaimLog) ? _pd._gmcrClaimLog.slice() : [];
        _log.push({ rewardId: 'recover_ticket_' + Date.now(), label: '系統補發漏領自選卷',
                    merit: '', items: _labels.slice(0, 40), at: Date.now(), _recover: true });
        if(_log.length > 200) _log = _log.slice(-200);
        await setDoc(doc(_fbDb, 'players', _uid), { _gmcrRecoveredTickets: _recovered, _gmcrClaimLog: _log }, { merge: true });
      }catch(_eMark){ console.warn('[GM獎勵對帳] 寫冪等標記/紀錄失敗(背包已補·下次因 held 已有不會重補)', _eMark); }
      // ⑤ 即時提示玩家
      try{ if(typeof _showInGameToast === 'function') _showInGameToast('🎁 老師補發了你漏領的：' + _labels.join('、'), '#66dd88', 4500); }catch(_eToast){}
      try{ console.log('[GM獎勵對帳 v3.16.97] 補發漏領自選卷', _toGrant); }catch(_){}
    }catch(_eAll){ try{ console.warn('[GM獎勵對帳] 例外(略過·不影響登入)', _eAll); }catch(_){} }
  };

  // ★ v3.16.66 — 玩家:讀自己「已領取的 GM 獎勵紀錄」(_gmcrClaimLog·含獎項/事蹟/時間·新→舊)。
  //   供「🎁 GM獎勵」收件區下半「✅ 已領取紀錄」顯示(待領領完後不再空白)。
  window._fbReadMyGmClassRewardLog = async function(){
    const _uid = (window._fbUser && window._fbUser.uid) || window._gUserId || null;
    if(!_uid || !_fbDb) return [];
    try{
      const _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(!_ps.exists()) return [];
      const _pd = _ps.data() || {};
      const _log = Array.isArray(_pd._gmcrClaimLog) ? _pd._gmcrClaimLog.slice() : [];
      _log.sort(function(a, b){ return (b && b.at || 0) - (a && a.at || 0); });
      return _log;
    }catch(e){ console.warn('[GM獎勵] 讀已領紀錄失敗', e); return []; }
  };

  // ★ v3.16.66 — GM:讀某玩家「GM 獎勵領取紀錄」(權威·直接讀 gmClassRewardClaims·含 transaction 寫入的精確時間)。
  //   email / 學號(lsps...) → where('email') 反查 uid;其餘當 uid。再 where('uid') 撈該玩家所有認領文件(GM isAdmin 放行)。
  //   獎項名/事蹟從 gmClassRewards/{uid}/items 反查補(若原獎勵還在);回傳 { uid, email, claims:[{rewardId,at,items,label,merit}...] }(新→舊)。
  window._fbReadPlayerGmClassRewardClaims = async function(emailOrUid){
    if(!_fbDb) throw new Error('Firestore 尚未就緒');
    const _raw = String(emailOrUid || '').trim();
    if(!_raw) throw new Error('請提供 email 或 uid');
    let _uid = '', _email = '', _byEmail = '';
    if(_raw.indexOf('@') >= 0){ _byEmail = _raw.toLowerCase(); }
    else if(/^lsps\d+$/i.test(_raw)){ _byEmail = _raw.toLowerCase() + '@stu.lsps.tp.edu.tw'; }
    if(_byEmail){
      _email = _byEmail;
      const _q = query(collection(_fbDb, 'players'), where('email', '==', _email));
      const _snap = await getDocs(_q);
      if(_snap.empty) throw new Error('查無此玩家:' + _email);
      _snap.forEach(function(d){ if(!_uid){ _uid = d.id; } });
    } else {
      _uid = _raw;
      try{
        const _pSnap = await getDoc(doc(_fbDb, 'players', _uid));
        const _pEx = (typeof _pSnap.exists === 'function') ? _pSnap.exists() : !!_pSnap.exists;
        if(_pEx){ _email = (_pSnap.data() || {}).email || ''; }
      }catch(_){}
    }
    let _claims = [];
    try{
      const _cq = query(collection(_fbDb, 'gmClassRewardClaims'), where('uid', '==', _uid));
      const _cs = await getDocs(_cq);
      _cs.forEach(function(d){ _claims.push(Object.assign({ docId: d.id }, d.data() || {})); });
    }catch(e){ console.warn('[GM獎勵紀錄] 讀認領文件失敗(可能規則未部署)', e); }
    // 補獎項名/事蹟:從該玩家 gmClassRewards/{uid}/items 反查(若原獎勵未被 GM 刪除)
    let _itemMap = {};
    try{
      const _is = await getDocs(collection(_fbDb, 'gmClassRewards', _uid, 'items'));
      _is.forEach(function(d){ _itemMap[d.id] = d.data() || {}; });
    }catch(_e){}
    _claims.forEach(function(c){
      const _src = _itemMap[c.rewardId] || {};
      c.label = _src.label || '';
      c.merit = _src.merit || '';
      if((!c.items || !c.items.length) && Array.isArray(_src.itemsLabel)) c.items = _src.itemsLabel;
    });
    _claims.sort(function(a, b){ return (b && b.at || 0) - (a && a.at || 0); });
    return { uid: _uid, email: _email, claims: _claims };
  };

  // ★ v3.16.66 — GM:彈窗檢視某玩家 GM 獎勵領取紀錄(清楚列出領過哪些獎項 + 時間 + 事蹟)。
  window._fbShowPlayerGmClassRewardClaims = async function(emailOrUid){
    let _data;
    try{ _data = await window._fbReadPlayerGmClassRewardClaims(emailOrUid); }
    catch(e){ try{ alert('查詢失敗:' + (e && e.message ? e.message : e)); }catch(_){} return; }
    const _esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
    const _old = document.getElementById('_gm-gmcr-claims-popup'); if(_old) _old.remove();
    const _claims = Array.isArray(_data.claims) ? _data.claims : [];
    let _rows = '';
    if(!_claims.length){
      _rows = '<div style="text-align:center;color:#9a9aac;padding:24px;font-size:16px;">這位玩家還沒有領取過任何 GM 獎勵(或雲端規則尚未部署)。</div>';
    } else {
      _claims.forEach(function(c){
        const _dt = new Date(c && c.at ? c.at : 0);
        const _dstr = (c && c.at) ? ((_dt.getMonth() + 1) + '/' + _dt.getDate() + '/' + _dt.getFullYear() + ' ' + String(_dt.getHours()).padStart(2, '0') + ':' + String(_dt.getMinutes()).padStart(2, '0')) : '(無時間)';
        const _items = Array.isArray(c && c.items) ? c.items : [];
        const _meritHtml = (c && c.merit) ? ('<div style="font-size:13px;color:#ffd98c;margin-top:2px;">🏅 ' + _esc(c.merit) + '</div>') : '';
        _rows += '<div style="border-top:1px solid rgba(140,220,160,0.18);padding:9px 2px;">'
          + '<div style="font-size:12.5px;color:#9ad6b0;font-weight:700;margin-bottom:3px;">🕐 ' + _esc(_dstr) + '</div>'
          + '<div style="font-size:15px;color:#ffe066;font-weight:800;line-height:1.6;">🎁 ' + (_items.length ? _items.map(_esc).join('、') : '(獎勵內容)') + '</div>'
          + _meritHtml
          + '<button class="_gmcr-del-btn" data-rid="' + _esc(c && c.rewardId ? c.rewardId : '') + '" style="margin-top:7px;padding:5px 12px;font-size:12.5px;font-weight:800;background:rgba(120,40,40,0.5);border:1.5px solid #d66;color:#ffcaca;border-radius:7px;cursor:pointer;font-family:inherit;">🗑 刪除此筆(學生收件箱也清除)</button>'
          + '</div>';
      });
    }
    const _pop = document.createElement('div');
    _pop.id = '_gm-gmcr-claims-popup';
    _pop.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,12,0.78);backdrop-filter:blur(4px);padding:18px;font-family:"M PLUS Rounded 1c","Nunito",sans-serif;';
    _pop.innerHTML = '<div style="background:linear-gradient(160deg,rgba(16,34,22,0.98),rgba(24,52,34,0.98));border:2.5px solid rgba(140,220,160,0.8);border-radius:16px;padding:20px 22px;max-width:min(96vw,640px);max-height:90vh;overflow-y:auto;-webkit-overflow-scrolling:touch;box-shadow:0 10px 50px rgba(60,160,100,0.5);text-align:left;">'
      + '<div style="font-size:23px;font-weight:900;color:#bff0cf;text-align:center;letter-spacing:1px;margin-bottom:4px;">🎁 GM 獎勵領取紀錄</div>'
      + '<div style="font-size:13px;color:#9ad6b0;text-align:center;margin-bottom:12px;word-break:break-all;">' + _esc(_data.email || '(無 email)') + ' ・ uid:' + _esc(_data.uid || '') + '</div>'
      + '<div style="background:rgba(0,16,8,0.4);border:1px solid rgba(140,220,160,0.3);border-radius:10px;padding:10px 14px;margin-bottom:6px;">'
        + '<div style="font-size:14px;color:#cbeccb;">這位玩家總共領取過 <b style="color:#fff;font-size:17px;">' + _claims.length + '</b> 份 GM 獎勵(依時間新→舊):</div>'
      + '</div>'
      + _rows
      + '<button onclick="(function(){var e=document.getElementById(\'_gm-gmcr-claims-popup\');if(e)e.remove();})()" style="margin-top:14px;width:100%;padding:11px;font-size:15px;font-weight:800;background:rgba(60,120,80,0.4);border:1.5px solid #5cbf86;color:#cfeeda;border-radius:8px;cursor:pointer;font-family:inherit;">關閉</button>'
      + '</div>';
    _pop.onclick = function(ev){ if(ev.target === _pop) _pop.remove(); };
    document.body.appendChild(_pop);
    // ★ v3.16.83 — 逐筆「🗑 刪除此筆」鈕:GM 誤發回收後,連帶把學生「🎁 GM 獎勵」收件箱紀錄清乾淨(待領項 + 已領取紀錄)。
    try{
      Array.prototype.forEach.call(_pop.querySelectorAll('._gmcr-del-btn'), function(_b){
        _b.onclick = async function(){
          var _rid = _b.getAttribute('data-rid');
          if(!_rid){ try{ alert('此筆缺少獎勵代碼,無法刪除'); }catch(_){} return; }
          if(!confirm('確定刪除這筆 GM 獎勵紀錄?\n\n會一併從學生「🎁 GM 獎勵」收件箱移除(待領項 + 已領取紀錄)。\n\n⚠ 這只刪「紀錄」,不會自動扣回已經發出的獎勵 / 英雄。如需收回實際發出的東西,請另用「學生補償(負值扣回)」或「污染英雄刪除」工具。')) return;
          _b.disabled = true; _b.textContent = '刪除中…';
          try{
            if(typeof window._fbAdminDeleteGmClassReward !== 'function') throw new Error('_fbAdminDeleteGmClassReward 未載入(index.html 可能尚未更新)');
            await window._fbAdminDeleteGmClassReward(_data.uid, _rid);
            var _row = _b.parentElement; if(_row) _row.style.display = 'none';
            _b.textContent = '✅ 已刪除';
          }catch(_eDel){
            _b.disabled = false; _b.textContent = '🗑 刪除失敗,再試一次';
            try{ alert('刪除失敗:' + (_eDel && _eDel.message ? _eDel.message : _eDel)); }catch(_){}
          }
        };
      });
    }catch(_eWire){ console.warn('[GM獎勵刪除] 綁定刪除鈕失敗', _eWire); }
  };

  // ★ v3.16.83 — GM:刪除某玩家「一筆 GM 課堂獎勵」的所有痕跡(誤發回收後,避免學生收件箱還看得到)。
  //   清 ① 收件箱 items doc(刪不掉就改 enabled:false 隱藏待領)② 認領文件 claim doc ③ 玩家主檔 _gmcrClaimLog
  //   (收件箱「✅ 已領取紀錄」顯示來源·GM 對 players 全權必能寫)。_gmcrClaimed 待領抑制快取刻意保留:
  //   即使 items 沒刪成功,也不會讓該筆又冒出來變待領。⚠ 只刪「紀錄」,不自動扣回已入帳的獎勵/英雄(收回另用既有工具)。
  window._fbAdminDeleteGmClassReward = async function(uid, rewardId){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    if(!uid || !rewardId) throw new Error('uid / rewardId 不可為空');
    var _uid = String(uid), _rid = String(rewardId);
    var _itemGone = false;
    // ① 收件箱 items doc:先試刪除;規則不允許刪除時退而停用 enabled:false(待領清單 _fbReadMyGmClassRewards 會過濾掉)
    try{
      await deleteDoc(doc(_fbDb, 'gmClassRewards', _uid, 'items', _rid));
      _itemGone = true;
    }catch(_eItem){
      console.warn('[GM獎勵刪除] items 刪除失敗,改試停用', _eItem);
      try{ await setDoc(doc(_fbDb, 'gmClassRewards', _uid, 'items', _rid), { enabled: false }, { merge: true }); _itemGone = true; }
      catch(_eDis){ console.warn('[GM獎勵刪除] items 停用也失敗(可能規則未允許)', _eDis); }
    }
    // ② 認領文件 claim doc(best-effort;未領取/規則未允許皆無妨)
    try{ await deleteDoc(doc(_fbDb, 'gmClassRewardClaims', _uid + '_' + _rid)); }
    catch(_eClaim){ console.warn('[GM獎勵刪除] 認領文件刪除失敗(可能未領取或規則未允許)', _eClaim); }
    // ③ 清玩家主檔 _gmcrClaimLog(收件箱「已領取紀錄」)·_gmcrClaimed 待領抑制快取保留
    try{
      var _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(_ps.exists()){
        var _pd = _ps.data() || {};
        var _log = Array.isArray(_pd._gmcrClaimLog) ? _pd._gmcrClaimLog.slice() : [];
        var _newLog = _log.filter(function(e){ return !(e && e.rewardId === _rid); });
        if(_newLog.length !== _log.length){
          await setDoc(doc(_fbDb, 'players', _uid), { _gmcrClaimLog: _newLog }, { merge: true });
        }
      }
    }catch(_ePd){ console.warn('[GM獎勵刪除] 清玩家已領紀錄失敗', _ePd); }
    console.info('✅ [GM獎勵刪除] uid=' + _uid + ' rewardId=' + _rid + ' (itemGone=' + _itemGone + ')');
    return { ok: true, itemGone: _itemGone };
  };

  // ★ v3.17.6(老師需求 1)— 送禮記錄查詢(依「姓名/信箱/uid」或「獎項名稱/事蹟」關鍵字),
  //   交叉比對「gmClassRewardClaims 認領文件」→ 標記每筆:✅已領取(UID權威) / ❌未領取 / ❔未知。
  //   回傳 { keyword, total, rows:[ {uid,label,email,items,merit,at,rewardId,kind,claimed,claimedAt} ] }(新→舊)。
  window._fbAdminGiftAudit = async function(keyword, maxScan){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    var _kw = String(keyword || '').trim().toLowerCase();
    var _n = parseInt(maxScan, 10) || 400;
    var _logs = [];
    try{
      var _q;
      try{ _q = query(collection(_fbDb, 'gmGiftLog'), orderBy('at', 'desc'), limit(_n)); }
      catch(_e1){ _q = query(collection(_fbDb, 'gmGiftLog'), limit(_n)); }
      var _snap = await getDocs(_q);
      _snap.forEach(function(d){ var _x = d.data() || {}; _logs.push({ id:d.id, uid:_x.uid||'', label:_x.label||'', email:_x.email||'', items:Array.isArray(_x.items)?_x.items:[], by:_x.by||'', at:_x.at||0, merit:_x.merit||'', rewardId:_x.rewardId||'', kind:_x.kind||'' }); });
    }catch(e){ throw new Error('讀取送禮記錄失敗(可能 gmGiftLog 規則未部署):' + (e && e.message || e)); }
    var _matched = _logs.filter(function(r){
      if(!_kw) return true;
      var _hay = ((r.label||'') + ' ' + (r.email||'') + ' ' + (r.uid||'') + ' ' + (r.items||[]).join(' ') + ' ' + (r.merit||'')).toLowerCase();
      return _hay.indexOf(_kw) >= 0;
    });
    _matched.sort(function(a, b){ return (b.at||0) - (a.at||0); });
    var _rows = [], _checkCap = 80;
    for(var i = 0; i < _matched.length; i++){
      var r = _matched[i];
      var _claimed = null, _claimedAt = 0;
      if(r.rewardId && r.uid && _checkCap > 0){
        _checkCap--;
        try{
          var _cs = await getDocFromServer(doc(_fbDb, 'gmClassRewardClaims', r.uid + '_' + r.rewardId));
          if(_cs.exists()){ _claimed = true; var _cd = _cs.data() || {}; _claimedAt = _cd.at || 0; }
          else { _claimed = false; }
        }catch(_ec){ _claimed = null; }
      }
      _rows.push(Object.assign({}, r, { claimed: _claimed, claimedAt: _claimedAt }));
    }
    return { keyword: _kw, total: _matched.length, rows: _rows };
  };

  // ★ v3.17.6(老師需求 3)— 安全補發「已發送但遺失」的獎勵(學生雲端查無獲得該獎勵記錄才補)。
  //   最沒風險做法:補發前用「兩道權威訊號」把關,任一顯示已獲得即阻擋,絕不重複發:
  //     ① gmClassRewardClaims 認領文件存在  = 已認領入帳(UID 權威)→ 阻擋
  //     ②.5 玩家主檔 _gmcrClaimed 含本筆     = 領取流程「入帳前」就標記(rollback 會移除)→ 幾乎確定已入帳 → 阻擋
  //   兩者皆查無 → 真遺失 → 停用原收件箱該筆(避免同時領原筆+補發筆)+ 寫「新一筆」收件箱(新 rewardId,
  //   create-only 認領規則天然防重複領)→ 補發即權威化,不會被污染或重複。
  window._fbAdminResendLostGift = async function(uid, rewardId){
    if(!_fbDb) throw new Error('Firestore 未就緒');
    var _uid = String(uid || ''), _rid = String(rewardId || '');
    if(!_uid || !_rid) throw new Error('uid / rewardId 不可為空');
    // ① 權威認領文件檢查(已領取入帳 → 阻擋)
    try{
      var _cs = await getDocFromServer(doc(_fbDb, 'gmClassRewardClaims', _uid + '_' + _rid));
      if(_cs.exists()){
        return { ok:false, blocked:true, reason:'這位學生已有「UID 權威認領記錄」(已領取入帳),補發會造成重複,已阻擋。' };
      }
    }catch(_ec){ throw new Error('讀取認領記錄失敗,為安全起見中止補發:' + (_ec && _ec.message || _ec)); }
    // ①.5 玩家主檔 _gmcrClaimed 檢查(領取流程入帳前就標記·含此筆幾乎確定已入帳 → 阻擋)
    try{
      var _ps = await getDocFromServer(doc(_fbDb, 'players', _uid));
      if(_ps.exists()){
        var _pd = _ps.data() || {};
        if(Array.isArray(_pd._gmcrClaimed) && _pd._gmcrClaimed.indexOf(_rid) >= 0){
          return { ok:false, blocked:true, reason:'這位學生的領取記錄(主檔 _gmcrClaimed)已含本筆,幾乎確定已入帳,補發會重複,已阻擋。若確認真的沒拿到,請改用「登入自動對帳補回」或個別補償工具。' };
        }
      }
    }catch(_eps){ /* 讀不到主檔就靠認領文件把關 */ }
    // ② 讀原收件箱獎勵(取得 reward/itemsLabel/merit/label/email 原樣補發)
    var _orig;
    try{
      var _rs = await getDocFromServer(doc(_fbDb, 'gmClassRewards', _uid, 'items', _rid));
      if(!_rs.exists()) throw new Error('查無原始獎勵資料(收件箱該筆已刪),無法安全補發原內容');
      _orig = Object.assign({ id:_rs.id }, _rs.data() || {});
    }catch(e){ throw new Error('讀取原始獎勵失敗:' + (e && e.message || e)); }
    // ③ 停用原收件箱該筆(避免學生同時領到「原筆 + 補發筆」造成重複)
    try{ await setDoc(doc(_fbDb, 'gmClassRewards', _uid, 'items', _rid), { enabled:false }, { merge:true }); }
    catch(_eDis){ console.warn('[補發] 停用原收件箱失敗(續行,補發筆仍為新 rewardId)', _eDis); }
    // ④ 寫「新的一筆」收件箱(新 rewardId·create-only 認領規則天然防重複領)
    var _label = _orig.label || '', _email = _orig.email || '', _reward = _orig.reward || {}, _merit = _orig.merit || '';
    var _itemsLabel = Array.isArray(_orig.itemsLabel) ? _orig.itemsLabel : [];
    var _res;
    try{
      if(typeof window._fbWriteGmClassReward !== 'function') throw new Error('_fbWriteGmClassReward 未載入');
      _res = await window._fbWriteGmClassReward(_uid, _label, _email, _reward, _itemsLabel, ('（補發）' + _merit).slice(0, 120));
    }catch(e){ throw new Error('寫入補發獎勵失敗:' + (e && e.message || e)); }
    // ⑤ 送禮記錄(稽核軌跡·標補發)
    try{
      if(typeof window._fbWriteGmGiftLog === 'function'){
        var _by = (window._fbUser && window._fbUser.email) || 'admin';
        await window._fbWriteGmGiftLog({ uid:_uid, label:_label, email:_email, items:_itemsLabel, by:_by, merit:('補發:' + _merit), rewardId:(_res && _res.id) || '', kind:'resendLost' });
      }
    }catch(_eLog){ console.warn('[補發] 送禮記錄寫入失敗', _eLog); }
    console.info('✅ [補發] uid=' + _uid + ' 原rid=' + _rid + ' → 新rid=' + ((_res && _res.id) || '?'));
    return { ok:true, newRewardId:(_res && _res.id) || '', label:_label };
  };

  window._fbAdminFindPlayerByEmail = async function(input) {
    const _raw = String(input || '').trim();
    if(!_raw) throw new Error('輸入不可為空');

    let _type;
    let _resolvedInput = _raw;
    const _sidEmail = (typeof window._lxpsStudentIdToEmail === 'function') ? window._lxpsStudentIdToEmail(_raw) : null;
    if(_raw.includes('@')) _type = 'email';
    else if(/^[A-Za-z0-9-]{20,}$/.test(_raw)) _type = 'uid';
    else if(_sidEmail){
      // ★ v3.13.49 — 學號(lsps110046 或純 6 位)→ 完整 email
      _type = 'email';
      _resolvedInput = _sidEmail;
      console.log('[_fbAdminFindPlayerByEmail] 學號自動拼成 email:' + _resolvedInput);
    }
    else if(/^\d{6}$/.test(_raw)){
      // 6 位學號 → 自動拼成完整 email

      _type = 'email';
      _resolvedInput = 'lsps' + _raw + '@stu.lsps.tp.edu.tw';
      console.log('[_fbAdminFindPlayerByEmail] 6 位學號自動拼成:' + _resolvedInput);
    }
    else if(/^\d{5}$/.test(_raw)){
      // 5 位班級碼(年級1+班級2+座號2)→ 班級<10 時去前導 0 變回 4 碼
      _type = 'name';
      if(_raw[1] === '0'){
        _resolvedInput = _raw[0] + _raw.slice(2);
        console.log('[_fbAdminFindPlayerByEmail] 5 位班級碼規範化:' + _raw + ' → ' + _resolvedInput);
      }
    }
    else _type = 'name';

    try {
      // ── 路徑 A:email ──
      if(_type === 'email'){
        const _norm = _resolvedInput.toLowerCase();
        const q = query(collection(_fbDb, 'players'), where('email', '==', _norm));
        const snap = await getDocs(q);
        if(snap.empty) {
          return { found: false, email: _norm, reason: 'not_found' };
        }
        const d = snap.docs[0];
        return {
          found: true,
          uid: d.id,
          email: _norm,
          data: d.data() || {}
        };
      }

      // ── 路徑 B:uid(直接拉文件) ──
      if(_type === 'uid'){
        const _ref = doc(_fbDb, 'players', _raw);
        const _docSnap = await getDoc(_ref);
        if(!_docSnap.exists()){
          return { found: false, email: '(uid: ' + _raw + ')', reason: 'not_found' };
        }
        const _data = _docSnap.data() || {};
        return {
          found: true,
          uid: _raw,
          email: _data.email || '',
          data: _data
        };
      }

      // ── 路徑 C:姓名 / 班級碼(複用 _fbAdminFindPlayersByName) ──
      if(typeof window._fbAdminFindPlayersByName !== 'function'){
        throw new Error('_fbAdminFindPlayersByName 未載入,請重新整理');
      }
      const _r = await window._fbAdminFindPlayersByName(_resolvedInput);
      const _players = (_r && _r.players) || [];
      if(!_players.length){
        return { found: false, email: '(姓名: ' + _raw + ')', reason: 'not_found' };
      }
      if(_players.length === 1){
        const _p = _players[0];
        const _ref = doc(_fbDb, 'players', _p.uid);
        const _docSnap = await getDoc(_ref);
        if(!_docSnap.exists()){
          return {
            found: true,
            uid: _p.uid,
            email: _p.email || '',
            data: { displayName: _p.name || '', email: _p.email || '' }
          };
        }
        return {
          found: true,
          uid: _p.uid,
          email: _docSnap.data().email || _p.email || '',
          data: _docSnap.data() || {}
        };
      }
      // 多筆候選
      const _err = new Error(
        '姓名「' + _raw + '」找到 ' + _players.length + ' 位候選,請改輸入更精確的姓名或直接複製其中一位的 email/uid:\n\n'
        + _players.slice(0, 10).map((p, i) => (i+1) + '. ' + p.name + (p.email ? ' (' + p.email + ')' : '')).join('\n')
        + (_players.length > 10 ? '\n... 還有 ' + (_players.length - 10) + ' 位候選未列出' : '')
      );
      _err._multi = true;
      _err._candidates = _players;
      throw _err;
    } catch(e) {
      if(e && e._multi) throw e;
      console.error('[_fbAdminFindPlayerByEmail] 查詢失敗', _raw, e);
      const _err = new Error((_type === 'email' ? 'email' : (_type === 'uid' ? 'uid' : '姓名')) + ' 查詢失敗:' + (e.code || e.message || e));
      _err.code = e.code;
      _err._isPermissionDenied = (e.code === 'permission-denied');
      throw _err;
    }
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v3.11.35+(2026-05-29) — 按姓名查玩家(回傳陣列,姓名可能多筆同名)
  //
  //   策略:Firestore 不支援「子字串 contains」查詢,所以策略是:
  //     1. 先嘗試精確比對(players where name === 輸入)→ 快
  //     2. 若 0 筆 → fallback 全掃 players(最多 limit 500),做本地子字串/前綴比對
  //     3. 回傳前 20 筆候選 + 總筆數
  //
  //   ⚠ 全掃成本:500 reads,只在「找不到精確比對」才會跑,日常使用幾乎不會踩到
  //   ⚠ 名稱可能包含座號前綴(例如「5324王同學」),所以也支援「同學名稱不含座號」的模糊匹配
  // ════════════════════════════════════════════════════════════════════
  window._fbAdminFindPlayersByName = async function(name, opts){
    let _norm = (name || '').trim();
    if(!_norm) throw new Error('姓名不可為空');
    opts = opts || {};
    // ★ v3.12.4(2026-05-30) — maxScan 預設 500→1500
    // ★ v3.13.74 — 再提高到 3000:涵蓋「900 學生 + 歷年測試/重註冊帳號」總數可能超過 1500 的情況
    //   (真名搜尋已由階段 1.5 名冊優先處理;此上限只影響「遊戲暱稱」全掃 fallback)
    const _maxScan = parseInt(opts.maxScan, 10) || 3000;
    const _maxReturn = parseInt(opts.maxReturn, 10) || 30;

    // ★ v3.16.61 — 信箱直查(校外帳號:無真名、無學號,只能憑信箱找)。
    //   輸入含 @ 視為完整信箱 → 精確查 email 欄位(涵蓋 gmail 等校外帳號,亦適用直接貼校內完整信箱)。
    //   0 筆才往下走原本流程(學號/班級/姓名)。
    if(_norm.indexOf('@') > 0){
      const _emailQ = _norm.toLowerCase();
      try{
        const _qEm = query(collection(_fbDb, 'players'), where('email', '==', _emailQ));
        const _snapEm = await getDocs(_qEm);
        if(!_snapEm.empty){
          const _listEm = [];
          _snapEm.forEach(d => {
            const _data = d.data() || {};
            _listEm.push({
              uid: d.id,
              name: _data.displayName || _data.name || '',
              email: _data.email || '',
              knowledgeCoins: _data.knowledgeCoins || 0,
              unlockedCount: Array.isArray(_data.unlockedHeroes) ? _data.unlockedHeroes.length : 0,
              matchType: 'email_exact',
            });
          });
          console.log('[_fbAdminFindPlayersByName] ✅ 信箱直查 → ' + _listEm.length + ' 筆');
          return { found: true, matchType: 'email_exact', count: _listEm.length, players: _listEm };
        }
        console.log('[_fbAdminFindPlayersByName] 信箱直查 0 筆,fallback 走原本流程');
      }catch(e){ console.warn('[_fbAdminFindPlayersByName] 信箱直查失敗,fallback', e); }
    }

    // ★ v3.12.14 — 純數字輸入規範化(與 _fbAdminFindPlayerByEmail 同步)
    //   6 位純數字 = 力行國小學號 → 拼 email 直查
    //   5 位純數字 = 5 碼班級碼(年級1+班級2+座號2)→ 班級<10 時去前導 0 變 4 碼
    //   4 位純數字 = 4 碼班級碼,直接走原本班級比對
    // ★ v3.13.49 — 完整學號(含字母前綴, 如 lsps110046)也支援:用共用 helper 拼 email 直查
    const _sidEmailN = (typeof window._lxpsStudentIdToEmail === 'function') ? window._lxpsStudentIdToEmail(_norm) : null;
    if(_sidEmailN && /^[A-Za-z]/.test(_norm)){
      console.log('[_fbAdminFindPlayersByName] 完整學號 → 直查 email:' + _sidEmailN);
      try {
        const _qSid = query(collection(_fbDb, 'players'), where('email', '==', _sidEmailN));
        const _snapSid = await getDocs(_qSid);
        if(!_snapSid.empty){
          const _listSid = [];
          _snapSid.forEach(d => {
            const _data = d.data() || {};
            _listSid.push({
              uid: d.id, name: _data.name || '', email: _data.email || '',
              knowledgeCoins: _data.knowledgeCoins || 0,
              unlockedCount: Array.isArray(_data.unlockedHeroes) ? _data.unlockedHeroes.length : 0,
              matchType: 'student_id_email',
            });
          });
          console.log('[_fbAdminFindPlayersByName] ✅ 完整學號 email 直查 → ' + _listSid.length + ' 筆');
          return { found: true, matchType: 'student_id_email', count: _listSid.length, players: _listSid };
        }
        console.log('[_fbAdminFindPlayersByName] 完整學號 email 直查 0 筆,fallback 走原本流程');
      } catch(e){
        console.warn('[_fbAdminFindPlayersByName] 完整學號 email 直查失敗,fallback', e);
      }
    }
    if(/^\d{6}$/.test(_norm)){
      const _expectedEmail = ('lsps' + _norm + '@stu.lsps.tp.edu.tw').toLowerCase();
      console.log('[_fbAdminFindPlayersByName] 6 位學號 → 直查 email:' + _expectedEmail);
      try {
        const _qEmail = query(collection(_fbDb, 'players'), where('email', '==', _expectedEmail));
        const _snap = await getDocs(_qEmail);
        if(!_snap.empty){
          const _list = [];
          _snap.forEach(d => {
            const _data = d.data() || {};
            _list.push({
              uid: d.id,
              name: _data.name || '',
              email: _data.email || '',
              knowledgeCoins: _data.knowledgeCoins || 0,
              unlockedCount: Array.isArray(_data.unlockedHeroes) ? _data.unlockedHeroes.length : 0,
              matchType: 'student_id_email',
            });
          });
          console.log('[_fbAdminFindPlayersByName] ✅ 6 位學號 email 直查 → ' + _list.length + ' 筆');
          return { found: true, matchType: 'student_id_email', count: _list.length, players: _list };
        }
        console.log('[_fbAdminFindPlayersByName] 6 位學號 email 直查 0 筆,fallback 走原本流程');
      } catch(e){
        console.warn('[_fbAdminFindPlayersByName] 6 位學號 email 直查失敗,fallback', e);
      }
    } else if(/^\d{5}$/.test(_norm) && _norm[1] === '0'){
      const _reduced = _norm[0] + _norm.slice(2);
      console.log('[_fbAdminFindPlayersByName] 5 位班級碼規範化:' + _norm + ' → ' + _reduced);
      _norm = _reduced;
    }

    // ★ v3.12.4(2026-05-30) — 班級座號純數字搜尋判定:4-6 位純數字 = 班級座號
    const _isClassNum = /^\d{3,6}$/.test(_norm);
    console.log('[_fbAdminFindPlayersByName] 開始查詢:「' + _norm + '」 isClassNum=' + _isClassNum);

    try {
      // ── 階段 1:精確比對(快路徑) ──
      // ★ v3.16.61 — 修中文姓名搜不到根因:players doc 實際存「displayName」(Google 真名/暱稱),
      //   並無「name」欄位 → 原 where('name','==') 永遠 0 筆,中文名只能靠名冊反查(覆蓋不全)。
      //   改查 displayName,讓所有「displayName 等於該真名/暱稱」的玩家被精確命中。
      const _qExact = query(collection(_fbDb, 'players'), where('displayName', '==', _norm));
      const _snapExact = await getDocs(_qExact);
      if(!_snapExact.empty){
        const _list = [];
        _snapExact.forEach(d => {
          const _data = d.data() || {};
          _list.push({
            uid: d.id,
            name: _data.displayName || _data.name || '',
            email: _data.email || '',
            knowledgeCoins: _data.knowledgeCoins || 0,
            unlockedCount: Array.isArray(_data.unlockedHeroes) ? _data.unlockedHeroes.length : 0,
            matchType: 'exact',
          });
          if(_list.length >= _maxReturn) return;
        });
        console.log('[_fbAdminFindPlayersByName] ✅ 精確比對 → ' + _list.length + ' 筆');
        return { found: true, matchType: 'exact', count: _list.length, players: _list };
      }

      // ── 階段 1.5(★ v3.13.74 新增):名冊優先比對(修復「中文姓名搜不到」)──
      //   問題根因:中文真名靠「階段 2 全掃 getDocs(limit 1500)」配對 roster fullName,
      //            但 email/學號搜尋走 where('email','==') 過濾查詢(永遠命中);若 players
      //            文件總數 > 1500(900 學生 + 歷年測試/重註冊帳號),全掃會漏掉沒被掃到的學生。
      //   修法:先在 client 端的 _STUDENT_ROSTER(706 筆)比對真名/座號短碼標籤 → 拿到 email,
      //        再用 where('email','in',[...])(每批 30 筆)精確查那些玩家 doc,完全不受掃描上限影響。
      //   注意:仍保留階段 2 全掃,讓「遊戲暱稱」(非真名)也搜得到;此前置只負責真名/座號。
      if(!_isClassNum){
        try{
          const _ros = (window._STUDENT_ROSTER && typeof window._STUDENT_ROSTER === 'object') ? window._STUDENT_ROSTER : null;
          if(_ros){
            const _lcNormR = _norm.toLowerCase();
            const _hitEmails = [];
            Object.keys(_ros).forEach(_em => {
              const _e = _ros[_em] || {};
              const _full = String(_e.fullName || '');
              const _sur = String(_e.surname || '');
              const _label = (typeof window._formatRosterLabel === 'function') ? String(window._formatRosterLabel(_e) || '') : '';
              // 命中:真名 includes / 短碼標籤(如 5324蔣同學)includes / 姓 完全等於
              if((_full && _full.toLowerCase().includes(_lcNormR))
                 || (_label && _label.toLowerCase().includes(_lcNormR))
                 || (_sur && _sur === _norm)){
                _hitEmails.push(_em);
              }
            });
            console.log('[_fbAdminFindPlayersByName] 名冊優先比對「' + _norm + '」→ 名冊命中 ' + _hitEmails.length + ' 筆 email');
            if(_hitEmails.length){
              const _rosterPlayers = [];
              const _seenUid = new Set();
              // where('email','in', batch) 每批最多 30 筆
              for(let _bi = 0; _bi < _hitEmails.length && _bi < 300; _bi += 30){
                const _batch = _hitEmails.slice(_bi, _bi + 30);
                try{
                  const _qIn = query(collection(_fbDb, 'players'), where('email', 'in', _batch));
                  const _snapIn = await getDocs(_qIn);
                  _snapIn.forEach(d => {
                    if(_seenUid.has(d.id)) return;
                    _seenUid.add(d.id);
                    const _dt = d.data() || {};
                    const _emLc = String(_dt.email || '').toLowerCase().trim();
                    const _rfn = (_ros[_emLc] && _ros[_emLc].fullName) ? _ros[_emLc].fullName : '';
                    _rosterPlayers.push({
                      uid: d.id,
                      name: _dt.name || '',
                      email: _dt.email || '',
                      knowledgeCoins: _dt.knowledgeCoins || 0,
                      unlockedCount: Array.isArray(_dt.unlockedHeroes) ? _dt.unlockedHeroes.length : 0,
                      matchType: 'roster_fullname',
                      _rosterFullName: _rfn,
                    });
                  });
                }catch(_eIn){
                  console.warn('[_fbAdminFindPlayersByName] 名冊 email in 查詢失敗(批 ' + _bi + ')', _eIn);
                }
              }
              if(_rosterPlayers.length){
                // 真名長度短的(更精確)排前面
                _rosterPlayers.sort((a, b) => (a.name.length || 0) - (b.name.length || 0));
                console.log('[_fbAdminFindPlayersByName] ✅ 名冊優先 → 查到 ' + _rosterPlayers.length + ' 位玩家 doc');
                const _trunc = _rosterPlayers.length > _maxReturn;
                return {
                  found: true,
                  matchType: 'roster',
                  count: _rosterPlayers.length,
                  truncated: _trunc,
                  players: _rosterPlayers.slice(0, _maxReturn),
                };
              }
              console.log('[_fbAdminFindPlayersByName] 名冊命中 email 但查無對應玩家 doc(該生可能尚未登入/用其他帳號),fallback 全掃');
            }
          } else {
            console.warn('[_fbAdminFindPlayersByName] _STUDENT_ROSTER 未載入,跳過名冊優先,直接全掃');
          }
        }catch(_eR){
          console.warn('[_fbAdminFindPlayersByName] 名冊優先比對例外,fallback 全掃', _eR);
        }
        // ★ v3.16.62 — 設計師名冊備援:上面 _STUDENT_ROSTER(student_roster.js)若缺該生或未載入而沒 return,
        //   就用 index.html 內建的 STUDENT_DESIGNER_HEROES(含 fullName 真名·約 30+ 名設計過英雄的學生)再試一次。
        //   讓「設計過英雄、但不在 student_roster.js / 名冊未上傳」的學生(如高廷睿)仍可用中文真名搜到。
        try{
          const _dh = (typeof STUDENT_DESIGNER_HEROES === 'object' && STUDENT_DESIGNER_HEROES) ? STUDENT_DESIGNER_HEROES : null;
          if(_dh){
            const _lcN = _norm.toLowerCase();
            const _dEmails = [];
            Object.keys(_dh).forEach(function(_em){
              const _e = _dh[_em] || {};
              const _full = String(_e.fullName || '');
              const _nm2 = String(_e.name || '');
              if((_full && _full.toLowerCase().includes(_lcN))
                 || (_nm2 && _nm2.toLowerCase().includes(_lcN))){
                _dEmails.push(_em);
              }
            });
            if(_dEmails.length){
              console.log('[_fbAdminFindPlayersByName] 設計師名冊命中 ' + _dEmails.length + ' 筆 email,查玩家 doc');
              const _dPlayers = [];
              const _seenD = new Set();
              for(let _bi = 0; _bi < _dEmails.length && _bi < 300; _bi += 30){
                const _batch = _dEmails.slice(_bi, _bi + 30);
                try{
                  const _qIn = query(collection(_fbDb, 'players'), where('email', 'in', _batch));
                  const _snapIn = await getDocs(_qIn);
                  _snapIn.forEach(function(d){
                    if(_seenD.has(d.id)) return;
                    _seenD.add(d.id);
                    const _dt = d.data() || {};
                    const _emLc = String(_dt.email || '').toLowerCase().trim();
                    const _rfn = (_dh[_emLc] && _dh[_emLc].fullName) ? _dh[_emLc].fullName : '';
                    _dPlayers.push({
                      uid: d.id,
                      name: _dt.displayName || _dt.name || '',
                      email: _dt.email || '',
                      knowledgeCoins: _dt.knowledgeCoins || 0,
                      unlockedCount: Array.isArray(_dt.unlockedHeroes) ? _dt.unlockedHeroes.length : 0,
                      matchType: 'designer_fullname',
                      _rosterFullName: _rfn,
                    });
                  });
                }catch(_eIn){ console.warn('[_fbAdminFindPlayersByName] 設計師名冊 email in 查詢失敗(批 ' + _bi + ')', _eIn); }
              }
              if(_dPlayers.length){
                _dPlayers.sort(function(a, b){ return (a.name.length || 0) - (b.name.length || 0); });
                console.log('[_fbAdminFindPlayersByName] ✅ 設計師名冊備援 → 查到 ' + _dPlayers.length + ' 位玩家 doc');
                return {
                  found: true,
                  matchType: 'designer',
                  count: _dPlayers.length,
                  truncated: _dPlayers.length > _maxReturn,
                  players: _dPlayers.slice(0, _maxReturn),
                };
              }
              console.log('[_fbAdminFindPlayersByName] 設計師名冊命中 email 但查無對應玩家 doc(該生可能尚未登入),fallback 全掃');
            }
          }
        }catch(_eDh){ console.warn('[_fbAdminFindPlayersByName] 設計師名冊備援例外,fallback 全掃', _eDh); }
      }

      // ── 階段 2:模糊比對(全掃 fallback) ──
      console.log('[_fbAdminFindPlayersByName] 精確比對 0 筆,改全掃做子字串比對(maxScan=' + _maxScan + ')');
      const _qAll = query(collection(_fbDb, 'players'), limit(_maxScan));
      const _snapAll = await getDocs(_qAll);
      const _fuzzy = [];
      const _lcNorm = _norm.toLowerCase();
      _snapAll.forEach(d => {
        const _data = d.data() || {};
        // ★ v3.16.61 — 同階段1:玩家真名/暱稱存於 displayName(非 name)。原讀 _data.name 永遠空字串,
        //   下方 if(!_name) return 直接略過全部 doc → 連 roster fullName 比對都跑不到。改讀 displayName。
        const _name = String(_data.displayName || _data.name || '');
        if(!_name) return;
        const _lcName = _name.toLowerCase();
        // 命中條件:子字串 / 去座號前綴比對
        // 去座號前綴:如「5324王同學」→「王同學」(前 3~5 位數字,放寬)
        const _nameNoPrefix = _name.replace(/^\d{1,6}/, '');
        // ★ v3.12.4 — 也抓「姓名(真實姓名)」括號裡的內容
        //   例「5324王同學(王小明)」→ ['5324王同學', '王小明', '5324', '王同學']
        const _parenInner = (_name.match(/[\(（]([^\)）]+)[\)）]/) || [])[1] || '';
        const _classNum = (_name.match(/^(\d{1,6})/) || [])[1] || '';
        // ★ v3.12.14 — 用 email 反查 _STUDENT_ROSTER 拿 fullName(真實姓名)
        //   讓老師可輸入「高廷睿」、「許立」等中文真名直接搜到玩家
        const _emailLc = String(_data.email || '').toLowerCase().trim();
        let _rosterFullName = '';
        if(_emailLc && typeof window._getRosterEntry === 'function'){
          const _rosEntry = window._getRosterEntry(_emailLc);
          if(_rosEntry && typeof _rosEntry.fullName === 'string'){
            _rosterFullName = _rosEntry.fullName.trim();
          }
        }
        let _matchType = null;
        // 班級座號純數字查詢:優先匹配開頭數字
        if(_isClassNum){
          if(_classNum === _norm){
            _matchType = 'class_exact'; // 班級完全匹配:5324
          } else if(_classNum && _classNum.startsWith(_norm)){
            _matchType = 'class_prefix'; // 班級前綴:輸入 53 → 5324、5326 都中
          } else if(_classNum && _norm.startsWith(_classNum) && _classNum.length >= 3){
            _matchType = 'class_reverse'; // 反向:輸入 53241 但存的是 5324
          }
        }
        // 非數字或數字也找不到,走文字比對
        if(!_matchType){
          // ★ v3.12.14 — roster fullName 真名比對優先(精確度高,老師心中的真名)
          if(_rosterFullName && _rosterFullName.toLowerCase().includes(_lcNorm)){
            _matchType = 'roster_fullname_contains';
          } else if(_lcName.includes(_lcNorm)){
            _matchType = 'contains';
          // ★ v3.16.79 — 反向模糊比對(輸入「包含」暱稱)僅限短輸入(真名/部分中文名 _norm.length<=6);
          //   長信箱帳號字串(如 clarebox123jp,13 字)不再反向誤命中某學生短暱稱(box/clare/123…)
          //   → 根治「成績獎勵只輸入 clarebox123jp 卻把 UR 發到 jlu1201」。本尊仍由 email_contains 正確找到。
          } else if(_lcNorm.includes(_lcName) && _lcName.length >= 2 && _norm.length <= 6){
            _matchType = 'reverse_contains';
          } else if(_nameNoPrefix && _nameNoPrefix.toLowerCase().includes(_lcNorm)){
            _matchType = 'no_prefix_contains';
          } else if(_nameNoPrefix && _lcNorm.includes(_nameNoPrefix.toLowerCase()) && _nameNoPrefix.length >= 2 && _norm.length <= 6){
            _matchType = 'no_prefix_reverse';
          } else if(_parenInner && _parenInner.toLowerCase().includes(_lcNorm)){
            // ★ v3.12.4 — 真實姓名(括號內)子字串比對
            _matchType = 'real_name_contains';
          } else if(!_isClassNum && _emailLc && _lcNorm.length >= 3 && _emailLc.includes(_lcNorm)){
            // ★ v3.16.61 — 校外帳號可用信箱(或片段≥3字)模糊搜尋;純數字輸入不走此路(避免班級碼誤配信箱數字)
            _matchType = 'email_contains';
          }
        }
        if(!_matchType) return;
        _fuzzy.push({
          uid: d.id,
          name: _name,
          email: _data.email || '',
          knowledgeCoins: _data.knowledgeCoins || 0,
          unlockedCount: Array.isArray(_data.unlockedHeroes) ? _data.unlockedHeroes.length : 0,
          matchType: _matchType,
          _rosterFullName: _rosterFullName,
        });
      });
      // 排序:exact > class_exact > class_prefix > roster_fullname > contains > no_prefix > reverse > real_name
      const _typeRank = {
        exact: 0,
        class_exact: 1,
        class_prefix: 2,
        // ★ v3.12.14 — roster fullname 排在 contains 之前
        roster_fullname_contains: 3,
        contains: 4,
        no_prefix_contains: 5,
        class_reverse: 6,
        reverse_contains: 6,
        no_prefix_reverse: 8,
        real_name_contains: 9,
        email_contains: 9,
      };
      _fuzzy.sort((a, b) => {
        const _ra = _typeRank[a.matchType] ?? 10;
        const _rb = _typeRank[b.matchType] ?? 10;
        if(_ra !== _rb) return _ra - _rb;
        return a.name.length - b.name.length;
      });
      const _truncated = _fuzzy.length > _maxReturn;
      const _result = _fuzzy.slice(0, _maxReturn);
      console.log('[_fbAdminFindPlayersByName] 模糊比對掃 ' + _snapAll.size + ' 位 → 命中 ' + _fuzzy.length
        + ' 位(回傳前 ' + _result.length + ')');
      return {
        found: _result.length > 0,
        matchType: _result.length > 0 ? 'fuzzy' : 'not_found',
        count: _fuzzy.length,
        truncated: _truncated,
        scanned: _snapAll.size,
        players: _result,
      };
    } catch(e) {
      console.error('[_fbAdminFindPlayersByName] 查詢失敗', _norm, e);
      const _err = new Error('姓名查詢失敗:' + (e.code || e.message || e));
      _err.code = e.code;
      throw _err;
    }
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v3.11.34(2026-05-29) — 異常解鎖偵測 + 清除 + 玩家通知 API 群
  //
  //   解決問題:黑暗球結算重複領獎 BUG(v3.11.34 阶段 1 已修)導致一些玩家
  //             已經刷出多隻不該有的稀有英雄/至寶。需要管理員工具:
  //               1. 掃描短時間大量解鎖的玩家
  //               2. 列出該玩家爆出的英雄/至寶
  //               3. 管理員指定刪除異常項目(寫 audit log)
  //               4. 發送通知給玩家(說明原因 + 連結補償)
  //
  //   ⚠ 階段 4 會加更精準的「同 battleId 多解鎖」偵測規則
  //     — 老師指示:1 場 BOSS 戰最多 1 隻新解鎖 + 1 次經驗值,超過視為異常。
  //     本階段先用「短時間爆增」基本規則,階段 4 升級。
  //
  //   資料來源:players/{uid}._heroUnlockHistory[]   — advSaveUnlockedHero v3.11.10 已寫入
  //             players/{uid}._treasureUnlockHistory[] — 本階段新增 hook
  //   結構:    { name/id, at, source, battleId?, uid }
  // ════════════════════════════════════════════════════════════════════

  // ── API 1:掃描異常解鎖英雄玩家 ──
  //
  // ★ v3.12.14 — 只算「BOSS 戰來源」的解鎖,排除星空召喚/抽卡/任務等合法多解鎖路徑
  //   合法路徑(完全排除):summon_*, ticket_ssr/sr, event_quest, student_designer,
  //                       shop_purchase, compensation, admin_grant, admin_delete
  //   只把以下視為 BOSS 戰來源(才算可能異常):
  //     maokong_50pct  / darkorb_5pct / japan_boss_5pct / yamata_miko_5pct
  //     taiwan_clear   / japan_clear  / boss_drop      / wb_* / boss_*
  //   空 source = 老資料,保守當作可能 BOSS 來源(避免漏抓)
  const _BOSS_UNLOCK_SOURCES = new Set([
    'maokong_50pct',
    'darkorb_5pct',
    'japan_boss_5pct',
    'yamata_miko_5pct',
    'taiwan_clear',
    'japan_clear',
    'boss_drop',
    'wb_drop',
  ]);
  function _isBossUnlockSource(s){
    if(!s) return true; // 空 source = 老資料,保守視為 BOSS 來源
    if(_BOSS_UNLOCK_SOURCES.has(s)) return true;
    if(typeof s === 'string' && (s.startsWith('wb_') || s.startsWith('boss_'))) return true;
    return false;
  }

  window._fbAdminScanAbnormalUnlocks = async function(windowMs, threshold){
    windowMs  = parseInt(windowMs, 10)  || (60 * 60 * 1000);   // 預設 1 小時
    threshold = parseInt(threshold, 10) || 5;                  // 預設 ≥ 5 隻
    const _now = Date.now();
    const _cutoff = _now - windowMs;
    try{
      const snap = await getDocs(collection(_fbDb, 'players'));
      const _abnormal = [];
      snap.forEach(docSnap => {
        try{
          const d = docSnap.data() || {};
          let _hist = Array.isArray(d._heroUnlockHistory) ? d._heroUnlockHistory : null;
          if(!_hist && typeof d._heroUnlockHistory_s === 'string'){
            try{ _hist = JSON.parse(d._heroUnlockHistory_s); }catch(_){ _hist = null; }
          }
          if(!Array.isArray(_hist) || !_hist.length) return;
          const _recent = _hist.filter(h => h && typeof h.at === 'number' && h.at >= _cutoff);
          // ★ v3.11.34 — 過濾 admin_delete / admin_grant
          // ★ v3.12.14 — 進一步:只算 BOSS 戰來源,排除 summon_rare 等合法路徑
          const _realUnlocks = _recent.filter(h =>
            h
            && h.source !== 'admin_delete'
            && h.source !== 'admin_grant'
            && _isBossUnlockSource(h.source)
          );
          // ════════════════════════════════════════════════════════════
          // ★ v3.13.89(2026-06-09)— 短時間密集多解鎖偵測(龍王戰洩漏鐵證)
          //   災情:打完世界 BOSS(火山炎龍王)後,殘留 timer 的 checkWin 在清理後
          //   (stage 已回 maokong)多次觸發冒險勝利序列,數秒內接連解鎖多隻木柵英雄。
          //   這些解鎖各自的 battleId 可能不同(每次殘留觸發 = 不同 _advCurrentBattleId),
          //   所以上面「同 battleId 多解鎖」規則抓不到。但合法路徑「每場 BOSS 戰只解鎖 1 隻、
          //   且每場戰鬥需數分鐘」,絕不可能在 90 秒內解鎖 ≥2 隻 BOSS 來源英雄。
          //   → 「90 秒內 ≥2 隻 BOSS 來源解鎖」= 龍王戰洩漏鐵證(不受 threshold 限制即列入)。
          // ════════════════════════════════════════════════════════════
          const _TIGHT_MS = 90 * 1000;
          const _sortedByAt = _realUnlocks.slice()
            .filter(h => typeof h.at === 'number')
            .sort((a, b) => a.at - b.at);
          const _tightClusters = [];
          let _cluster = [];
          for(let _i = 0; _i < _sortedByAt.length; _i++){
            if(_cluster.length === 0){ _cluster = [_sortedByAt[_i]]; continue; }
            if(_sortedByAt[_i].at - _cluster[_cluster.length - 1].at <= _TIGHT_MS){
              _cluster.push(_sortedByAt[_i]);
            } else {
              if(_cluster.length >= 2) _tightClusters.push(_cluster);
              _cluster = [_sortedByAt[_i]];
            }
          }
          if(_cluster.length >= 2) _tightClusters.push(_cluster);
          const _tightClusterInfo = _tightClusters.map(c => ({
            startAt: c[0].at,
            endAt: c[c.length - 1].at,
            spanMs: c[c.length - 1].at - c[0].at,
            count: c.length,
            heroes: c.map(x => x.name),
          }));
          const _tightHeroNames = [];
          _tightClusters.forEach(c => c.forEach(x => { if(x.name) _tightHeroNames.push(x.name); }));

          // 命中「總量 ≥ threshold」 或 「短時間密集多解鎖鐵證」→ 列為異常
          if(_realUnlocks.length >= threshold || _tightClusterInfo.length > 0){
            const _byBattle = {};
            _realUnlocks.forEach(h => {
              const _bk = h.battleId || '(無 battleId)';
              if(!_byBattle[_bk]) _byBattle[_bk] = [];
              _byBattle[_bk].push(h);
            });
            const _multiPerBattle = Object.entries(_byBattle)
              .filter(([k, arr]) => k !== '(無 battleId)' && arr.length >= 2)
              .map(([k, arr]) => ({ battleId: k, count: arr.length, heroes: arr.map(a => a.name) }));
            _abnormal.push({
              uid: docSnap.id,
              email: (d.email || '').toLowerCase(),
              displayName: (d.displayName || ''),
              count: _realUnlocks.length,
              heroes: _realUnlocks.map(h => ({
                name: h.name,
                at: h.at,
                source: h.source || 'unknown',
                battleId: h.battleId || null
              })).sort((a,b) => b.at - a.at),
              multiPerBattle: _multiPerBattle,
              tightClusters: _tightClusterInfo,        // ★ v3.13.89 龍王戰洩漏鐵證
              tightClusterHeroes: _tightHeroNames,      // ★ v3.13.89 預設勾選+標紅用
            });
          }
        }catch(eRow){ console.warn('[_fbAdminScanAbnormalUnlocks] row 例外', eRow); }
      });
      _abnormal.sort((a, b) => b.count - a.count);
      console.log('[_fbAdminScanAbnormalUnlocks v3.12.14] 掃描完成 windowMs=' + windowMs
        + ' threshold=' + threshold + ' → ' + _abnormal.length + ' 位異常玩家'
        + '(只算 BOSS 戰來源,排除星空召喚/抽卡/任務等合法路徑)');
      return { ok: true, abnormal: _abnormal, scannedAt: _now, windowMs, threshold };
    }catch(e){
      console.error('[_fbAdminScanAbnormalUnlocks] 掃描失敗', e);
      throw e;
    }
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v5.130.0 —【三槽同寫單一真相】老師 2026-09-02 裁定甲
  // ────────────────────────────────────────────────────────────────────
  // 病灶(實查全檔 36 支雲端寫入函式):除 _fbCompensatePlayer / _fbStudentSurplusURRemove(v5.92.0)
  //   / _fbAdminRevokeURTickets(v5.93.0) 三支外,**其餘 GM 增刪工具全部只寫主檔**,
  //   saves/live 與 saves/safe 原封不動 ⇒ 兩個症狀其實是同一條鏈:
  //   ❶【要刪的角色一直又回來】live/safe 仍有該英雄 + heroLevels>1 + **沒有 admin_delete 帳本**;
  //      學生下次存檔時 _fbSave 對 _heroUnlockHistory(陣列)是「整包取代」,本機帳本會蓋掉
  //      主檔那唯一一筆 admin_delete ⇒ 稽核感知失去證據 ⇒ 三槽合併把它 union 回來,
  //      就算沒 union 到,_applySafeData 的「幻影救回」(heroLevels>1 或身上有至寶)也會主動 push 回去。
  //   ❷【要拿的角色/券一直沒拿到】同一條鏈的鏡像:補發只寫主檔,帳本被蓋掉之後,
  //      live 槽裡**較舊的 admin_delete 反而變成「最近一筆」** ⇒ 剛補發的角色又被 latest-wins 濾掉;
  //      券則因 playerBackpack 屬「消耗型只取最新槽」,較新的 live 沒有券 ⇒ 券蒸發。
  //
  // 修法:所有 GM 端增刪一律走本函式。builder 收到「該槽自己的資料」、回傳「該槽自己的 patch」
  //   ⇒ 三槽各自計算。★★ 不可改成「同一份 patch 寫三槽」★★ —— 那會把主檔的值倒灌進
  //   live/safe,把學生在別台剛練的等級/剛拿的道具整組蓋掉。
  // ⚠ 只有主檔蓋 _authoritativeRestoreAt(在線學生走既有 piece3 乾淨重載);live/safe 蓋了
  //   只會讓畫面重複閃(同 v5.92.0 裁定)。
  // ⚠ savedAt 預設不動:純移除不碰消耗型欄位,亂 bump 會讓剛寫的槽變「最新槽」,
  //   反而讓該槽較舊的背包/知識幣被當權威。只有動到 playerBackpack 的呼叫端才傳 bumpSavedAt:true。
  // ⚠ 主檔失敗 = 整支 throw(不留半套);live/safe 失敗只記紅字,回傳值帶得出來讓 UI 提醒老師重試。
  // ════════════════════════════════════════════════════════════════════
  window._LXPS_GROWTH_KEYS = ['heroLevels','heroExp','heroSkillLevels','heroStatPoints',
    'heroStatInvested','heroCapsuleInvested','heroBurstLevels','heroTraitLevel'];

  window._lxpsAdminApplyAllSlots = async function(uid, builder, opts){
    if(!uid) throw new Error('_lxpsAdminApplyAllSlots:缺少 uid');
    if(typeof builder !== 'function') throw new Error('_lxpsAdminApplyAllSlots:缺少 builder');
    opts = opts || {};
    var _label = String(opts.label || 'GM操作');
    var _now = Date.now();
    var _targets = [
      { key:'main', ref: doc(_fbDb, 'players', uid) },
      { key:'live', ref: doc(_fbDb, 'players', uid, 'saves', 'live') },
      { key:'safe', ref: doc(_fbDb, 'players', uid, 'saves', 'safe') }
    ];
    var _out = { ok:false, at:_now, label:_label, main:null, live:null, safe:null,
                 mainData:null, written:0, failed:0, absent:0 };
    for(var _i = 0; _i < _targets.length; _i++){
      var _t = _targets[_i];
      var _r = { slot:_t.key, exists:false, written:false, skipped:false, err:null };
      try{
        var _snap = null;
        try{ _snap = await getDocFromServer(_t.ref); }
        catch(_eSrv){ _snap = await getDoc(_t.ref); }   // 配額/離線時退回快取,總比整支失敗好
        var _ex = _snap && (typeof _snap.exists === 'function' ? _snap.exists() : _snap.exists);
        if(!_ex){
          if(_t.key === 'main') throw new Error('查無玩家主檔');
          _out.absent++; _out[_t.key] = _r; continue;   // 沒有這個槽 = 本來就沒東西可復活
        }
        _r.exists = true;
        var _d = _snap.data() || {};
        if(_t.key === 'main') _out.mainData = _d;
        var _patch = builder(_d, _t.key);
        if(!_patch || typeof _patch !== 'object' || Object.keys(_patch).length === 0){
          _r.skipped = true; _out[_t.key] = _r; continue;   // 該槽無事可做
        }
        if(_t.key === 'main'){
          if(opts.stampRestore !== false) _patch._authoritativeRestoreAt = _now;
          _patch._adminForceRestore = true;
          if(opts.rescueSignal) _patch._adminRescueSignal = opts.rescueSignal;
          if(opts.lastAction)   _patch._adminLastAction   = opts.lastAction;
        }
        if(opts.bumpSavedAt === true) _patch.savedAt = _now;
        await setDoc(_t.ref, _patch, { merge: true });
        _r.written = true; _out.written++;
      }catch(_eSlot){
        _r.err = (_eSlot && _eSlot.message) || String(_eSlot);
        _out.failed++;
        _out[_t.key] = _r;
        if(_t.key === 'main') throw _eSlot;             // 主檔失敗 = 整支失敗
        console.error('[三槽同寫 ' + _label + '] ' + _t.key + ' 槽寫入失敗 —— 該槽仍留有舊資料,'
          + '下次三槽合併可能把它撿回來,請重試一次', _eSlot);
        continue;
      }
      _out[_t.key] = _r;
    }
    _out.ok = !!(_out.main && _out.main.written);
    var _fmt = function(r){
      if(!r) return '?';
      if(!r.exists) return '無槽';
      if(r.err) return '❌';
      return r.skipped ? '－' : '✅';
    };
    console.info('[三槽同寫 ' + _label + '] uid=' + uid
      + ' 主檔=' + _fmt(_out.main) + ' live=' + _fmt(_out.live) + ' safe=' + _fmt(_out.safe));
    return _out;
  };

  // ── 共用讀取:同一份「_s 字串優先」口徑(對齊 _lxpsObjFromSlot / _applySafeData) ──
  function _lxpsSlotObj(d, key){
    try{
      if(typeof d[key+'_s'] === 'string'){
        var p = JSON.parse(d[key+'_s']);
        if(p && typeof p === 'object' && !Array.isArray(p)) return p;
      }
      if(d[key] && typeof d[key] === 'object' && !Array.isArray(d[key])) return d[key];
    }catch(_){}
    return null;
  }
  function _lxpsSlotArr(d, key){
    try{
      if(Array.isArray(d[key])) return d[key];
      if(typeof d[key+'_s'] === 'string'){ var p = JSON.parse(d[key+'_s']); if(Array.isArray(p)) return p; }
    }catch(_){}
    return null;
  }

  // ── 共用 patch:移除英雄(8 張養成表 + _s + 至寶解裝 + 每槽帳本) ──
  //   ⚠ 8 張養成表少清任何一張,_lxpsHeroFloorOntoMain 的 effort 判定就會把英雄撿回來
  //     (舊 _fbAdminBulkRemoveHeroes 只清 7 張,漏 heroCapsuleInvested)。
  //   ⚠ 帳本「一定寫」,即使該槽本來就沒有這隻 —— 那筆 admin_delete 才是「不復活」的唯一證據。
  // ★ v5.281.0 — 老師刪除/救援/發放也直接寫進該槽的永久擁有證明 heroOwnLedger_s
  //   理由:流水帳 _heroUnlockHistory 會被還沒更新的舊平板整包蓋掉(刪除證據跟著消失),
  //   舊版程式不認得 heroOwnLedger_s ⇒ 不會碰它(merge 寫入保留)⇒ 證據留得住,自動刪除/永久持有都靠得住。
  //   沒有 uid 不寫(分不出是誰的)。
  function _lxpsPatchOwnLedger(d, patch, list, at, src, uid, kind){
    try{
      var u12 = String(uid || '').slice(0, 12);
      if(!u12 || !list || !list.length || typeof window._lxpsHeroLedgerParse !== 'function') return;
      var L = window._lxpsHeroLedgerParse(d && d.heroOwnLedger_s) || { v:1, h:{} };
      list.forEach(function(n){
        if(!n) return;
        if(kind === 'rem'){ if(window._LXPS_HERO_REMOVE_SRC[String(src || '')]) window._lxpsHeroLedgerRem(L, n, at, src, u12); }
        else window._lxpsHeroLedgerAcq(L, n, window._lxpsAcqStamp(d, n, at, u12), src, u12);
      });
      patch.heroOwnLedger_s = JSON.stringify(L);
    }catch(_e){}
  }
  window._lxpsPatchOwnLedger = _lxpsPatchOwnLedger;
  // ★ v5.281.0(二審 H2)— 獲得(救援/發放/還原)的時間戳一定晚於這份存檔已知的本帳號移除:
  //   老師電腦與學生平板時鐘不一致時(平板走快寫了「不是我的」),救援才不會反而比移除早而失效。
  window._lxpsAcqStamp = function(d, name, at, u12){
    at = +at || Date.now();
    try{
      var mx = 0;
      var L0 = window._lxpsHeroLedgerParse(d && d.heroOwnLedger_s);
      var e0 = L0 && L0.h && L0.h[name];
      if(e0 && (!e0.ru || String(e0.ru) === u12)) mx = +e0.r || 0;
      var h = d ? (Array.isArray(d._heroUnlockHistory) ? d._heroUnlockHistory : (typeof d._heroUnlockHistory_s === 'string' ? JSON.parse(d._heroUnlockHistory_s) : [])) : [];
      (Array.isArray(h) ? h : []).forEach(function(e){
        if(e && e.name === name && window._LXPS_HERO_REMOVE_SRC[String(e.source || '')] && String(e.uid || '').slice(0, 12) === u12 && (+e.at || 0) > mx) mx = +e.at || 0;
      });
      if(mx >= at) at = mx + 1;
    }catch(_){}
    return at;
  };
  window._lxpsSlotRemoveHeroesPatch = function(d, names, meta){
    d = d || {}; meta = meta || {};
    var _list = (Array.isArray(names) ? names : []).filter(Boolean);
    if(!_list.length) return null;
    var _set = {}; _list.forEach(function(n){ _set[n] = 1; });
    var _now = (typeof meta.at === 'number') ? meta.at : Date.now();
    var _patch = {};
    var _unl = _lxpsSlotArr(d, 'unlockedHeroes');
    if(_unl){
      var _kept = _unl.filter(function(n){ return !_set[n]; });
      _patch.unlockedHeroes = _kept;
      try{ _patch.unlockedHeroes_s = JSON.stringify(_kept); }catch(_){}
    }
    window._LXPS_GROWTH_KEYS.forEach(function(k){
      var _src = _lxpsSlotObj(d, k);
      if(!_src) return;
      var _o = Object.assign({}, _src); var _hit = false;
      _list.forEach(function(n){ if(n in _o){ delete _o[n]; _hit = true; } });
      if(!_hit) return;
      _patch[k] = _o;
      try{ _patch[k+'_s'] = JSON.stringify(_o); }catch(_){}
    });
    var _tre = _lxpsSlotObj(d, 'taiwanTreasureData');
    if(_tre){
      var _tc = {}; var _tHit = false;
      Object.keys(_tre).forEach(function(id){
        var r = _tre[id];
        if(r && typeof r === 'object'){
          var c = Object.assign({}, r);
          if(c.equippedTo && _set[c.equippedTo]){ c.equippedTo = null; _tHit = true; }
          _tc[id] = c;
        } else { _tc[id] = r; }
      });
      if(_tHit){
        _patch.taiwanTreasureData = _tc;
        try{ _patch.taiwanTreasureData_s = JSON.stringify(_tc); }catch(_){}
      }
    }
    var _hist = _lxpsSlotArr(d, '_heroUnlockHistory');
    _hist = _hist ? _hist.slice() : [];
    _list.forEach(function(n){
      var _e = { name:n, at:_now, source:(meta.source || 'admin_delete'),
        adminAction:(meta.adminAction !== false),
        deletedBy:String(meta.by || 'admin'),
        reason:String(meta.reason || '').slice(0, 200),
        uid:String(meta.uid || '').slice(0, 12),
        slot:String(meta.slot || '') };
      if(meta.extra && typeof meta.extra === 'object') Object.assign(_e, meta.extra);   // 呼叫端專屬稽核標記(如 disownedByStudent)
      _hist.push(_e);
    });
    if(_hist.length > 300) _hist = _hist.slice(-300);
    _patch._heroUnlockHistory = _hist;
    try{ _patch._heroUnlockHistory_s = JSON.stringify(_hist); }catch(_){}
    _lxpsPatchOwnLedger(d, _patch, _list, _now, (meta.source || 'admin_delete'), meta.uid, 'rem');
    return _patch;
  };

  // ── 共用 patch:補發英雄(union + 等級保底不降級 + 每槽帳本) ──
  //   ⚠ 帳本一定要三槽都寫:別槽若留著較舊的 admin_delete,latest-wins 會把剛補發的角色再濾掉一次。
  window._lxpsSlotGrantHeroesPatch = function(d, names, meta){
    d = d || {}; meta = meta || {};
    var _list = (Array.isArray(names) ? names : []).filter(Boolean);
    if(!_list.length) return null;
    var _now = (typeof meta.at === 'number') ? meta.at : Date.now();
    var _patch = {};
    var _unl = _lxpsSlotArr(d, 'unlockedHeroes');
    _unl = _unl ? _unl.slice() : [];
    var _seen = {}; _unl.forEach(function(n){ if(n) _seen[n] = 1; });
    _list.forEach(function(n){ if(!_seen[n]){ _unl.push(n); _seen[n] = 1; } });
    _patch.unlockedHeroes = _unl;
    try{ _patch.unlockedHeroes_s = JSON.stringify(_unl); }catch(_){}
    var _lvo = Object.assign({}, _lxpsSlotObj(d, 'heroLevels') || {});
    var _lvMap = (meta.levels && typeof meta.levels === 'object') ? meta.levels : {};
    _list.forEach(function(n){
      var _want = Math.max(1, Math.min(50, Math.floor(Number(_lvMap[n]) || 1)));
      if(typeof _lvo[n] !== 'number' || _lvo[n] < _want) _lvo[n] = _want;   // 只保底,絕不降級
    });
    _patch.heroLevels = _lvo;
    try{ _patch.heroLevels_s = JSON.stringify(_lvo); }catch(_){}
    var _hist = _lxpsSlotArr(d, '_heroUnlockHistory');
    _hist = _hist ? _hist.slice() : [];
    _list.forEach(function(n){
      var _e = { name:n, at:_now, source:(meta.source || 'admin_grant'), adminAction:true,
        by:String(meta.by || 'admin'),
        reason:String(meta.reason || '').slice(0, 200),
        uid:String(meta.uid || '').slice(0, 12),
        slot:String(meta.slot || '') };
      if(meta.extra && typeof meta.extra === 'object') Object.assign(_e, meta.extra);   // 呼叫端專屬稽核標記(如 auditRestored)
      _hist.push(_e);
    });
    if(_hist.length > 300) _hist = _hist.slice(-300);
    _patch._heroUnlockHistory = _hist;
    try{ _patch._heroUnlockHistory_s = JSON.stringify(_hist); }catch(_){}
    _lxpsPatchOwnLedger(d, _patch, _list, _now, (meta.source || 'admin_grant'), meta.uid, 'acq');
    return _patch;
  };

  // ── 共用 patch:至寶增刪(mode:'remove' 整顆刪 / 'grant' 補發 Lv1;皆寫每槽帳本) ──
  window._lxpsSlotTreasurePatch = function(d, ids, meta){
    d = d || {}; meta = meta || {};
    var _list = (Array.isArray(ids) ? ids : []).filter(Boolean);
    if(!_list.length) return null;
    var _remove = (meta.mode === 'remove');
    var _now = (typeof meta.at === 'number') ? meta.at : Date.now();
    var _src = _lxpsSlotObj(d, 'taiwanTreasureData') || {};
    var _o = JSON.parse(JSON.stringify(_src));
    _list.forEach(function(id){
      if(_remove){ delete _o[id]; }
      else if(!_o[id]){ _o[id] = { lv:1, exp:0, equippedTo:null, invested:{ hp:0, atk:0, sp:0, spd:0 } }; }
    });
    var _patch = { taiwanTreasureData: _o };
    try{ _patch.taiwanTreasureData_s = JSON.stringify(_o); }catch(_){}
    var _hist = _lxpsSlotArr(d, '_treasureUnlockHistory');
    _hist = _hist ? _hist.slice() : [];
    _list.forEach(function(id){
      var _e = { id:id, at:_now, source:(meta.source || (_remove ? 'admin_delete' : 'admin_grant')),
        adminAction:true, by:String(meta.by || 'admin'),
        reason:String(meta.reason || '').slice(0, 200),
        uid:String(meta.uid || '').slice(0, 12),
        slot:String(meta.slot || '') };
      if(meta.extra && typeof meta.extra === 'object') Object.assign(_e, meta.extra);   // 呼叫端專屬稽核標記
      _hist.push(_e);
    });
    if(_hist.length > 300) _hist = _hist.slice(-300);
    _patch._treasureUnlockHistory = _hist;
    try{ _patch._treasureUnlockHistory_s = JSON.stringify(_hist); }catch(_){}
    return _patch;
  };

  // ── 共用 patch:背包增減(逐槽以該槽自己的存量夾 0~99;兩鍵同寫) ──
  //   ⚠ 呼叫端務必同時傳 bumpSavedAt:true —— 背包屬「消耗型只取最新槽」,不 bump 等於沒改。
  window._lxpsSlotBackpackPatch = function(d, deltas, meta){
    d = d || {}; meta = meta || {};
    if(!deltas || typeof deltas !== 'object') return null;
    var _keys = Object.keys(deltas);
    if(!_keys.length) return null;
    var _o = Object.assign({}, _lxpsSlotObj(d, 'playerBackpack') || {});
    var _applied = {};
    _keys.forEach(function(k){
      var _dv = Math.floor(Number(deltas[k]) || 0);
      if(!_dv) return;
      var _cur = Math.max(0, Math.floor(Number(_o[k]) || 0));
      var _next = Math.max(0, Math.min(99, _cur + _dv));
      if(_next === _cur) return;
      _applied[k] = _next - _cur;
      if(_next === 0){ delete _o[k]; } else { _o[k] = _next; }
    });
    if(!Object.keys(_applied).length) return null;
    if(meta.applied && typeof meta.applied === 'object'){
      Object.keys(_applied).forEach(function(k){ meta.applied[k] = _applied[k]; });
    }
    var _patch = { playerBackpack: _o };
    try{ _patch.playerBackpack_s = JSON.stringify(_o); }catch(_){}
    return _patch;
  };

  // ════════════════════════════════════════════════════════════════════
  // ★ v5.151.0 —【跨三槽「原始等級」canonical 真相】老師實錘「6213 魔劍姬 44 級救回變 26 級」
  //   根因:_fbStudentDisownHeroes / _fbAdminBulkRemoveHeroes / _fbAdminDeleteUnlockedHero
  //   移除英雄時,_auditRecoveredLevels 的暫存值是**逐槽各自看自己那槽的 heroLevels**
  //   (main/live/safe 三槽各跑一次 builder,每次只看得到「這一槽」的資料)。
  //   共用 iPad 環境下三槽等級本就常不同步(這正是 v5.130.0 整套三槽架構要處理的問題),
  //   於是同一隻英雄在三槽各自暫存出不同的「原等級」(例:main 44 / live 26 / safe 26)。
  //   之後「🛟 一鍵無損救回」同樣逐槽讀「這一槽自己的暫存」寫回「這一槽自己的 heroLevels」,
  //   三槽於是各自還原成不同等級;下次三槽合併時哪一槽 savedAt 較新就採用哪個值,
  //   時機不巧就會顯示救回後「降級」。
  //   ★ 修法:移除當下先讀三槽,取每隻英雄「heroLevels 與既有暫存」的跨槽最大值,
  //   當作唯一真相,三槽的 builder 一律暫存這同一個值(其餘欄位仍照舊各槽各自算,
  //   不違反「不可用同一份 patch 寫三槽」鐵律——那條鐵律是為了保護「還在練的欄位」,
  //   而這裡的英雄本體與等級正要在三槽一併移除,不存在「保護某槽正在練」的問題)。
  // ════════════════════════════════════════════════════════════════════
  window._lxpsCanonicalHeroLevels = async function(uid, names){
    var _list = (Array.isArray(names) ? names : []).filter(Boolean);
    var _out = {};
    if(!uid || !_list.length) return _out;
    var _refs = [
      doc(_fbDb, 'players', uid),
      doc(_fbDb, 'players', uid, 'saves', 'live'),
      doc(_fbDb, 'players', uid, 'saves', 'safe')
    ];
    for(var _i = 0; _i < _refs.length; _i++){
      try{
        var _snap = null;
        try{ _snap = await getDocFromServer(_refs[_i]); }catch(_eS){ _snap = await getDoc(_refs[_i]); }
        var _ex = _snap && (typeof _snap.exists === 'function' ? _snap.exists() : _snap.exists);
        if(!_ex) continue;
        var _d = _snap.data() || {};
        var _lvSrc = (_d.heroLevels && typeof _d.heroLevels === 'object') ? _d.heroLevels : {};
        var _stash = (_d._auditRecoveredLevels && typeof _d._auditRecoveredLevels === 'object') ? _d._auditRecoveredLevels : {};
        _list.forEach(function(n){
          var _cand = Math.max(
            (typeof _lvSrc[n] === 'number') ? _lvSrc[n] : 0,
            (typeof _stash[n] === 'number') ? _stash[n] : 0
          );
          if(_cand > (_out[n] || 0)) _out[n] = _cand;
        });
      }catch(_eSlot){ /* 該槽讀取失敗不影響其他槽,寧可少採信一槽也不整支失敗 */ }
    }
    _list.forEach(function(n){ if(!(_out[n] > 0)) _out[n] = 1; });
    return _out;
  };

