  // ════════════════════════════════════════════════════════════════════
  // ★ v3.13.39(2026-06-04) — 帳號汙染掃描:找出「瞬間解鎖大量 SSR」的帳號
  // ─────────────────────────────────────────────────────────────────────
  // 老師需求:共用平板把上一位學生的整批 SSR union 進下一位帳號 → 瞬間多出二十隻 SSR。
  // 偵測原理:跨帳號 union 只塞進 unlockedHeroes,不會產生 _heroUnlockHistory 解鎖事件。
  //   → 疑似汙染 = roster 內的 SSR 之中「找不到任何合法解鎖紀錄」的那些。
  //   (正常抽到/打到的 SSR 都會有 _heroUnlockHistory 紀錄;admin_delete 來源不算合法擁有)
  //   門檻 threshold:疑似 SSR ≥ N 才列出(預設 5,老師可調)。SSR 本就稀有,
  //   一個正常學生不會同時擁有一大票「沒有解鎖紀錄」的 SSR。
  // ⚠ 邊界:v3.11.10 之前解鎖的 SSR 沒有歷史紀錄 → 可能被列入「疑似」;
  //   故本工具只「列出候選 + 顯示英雄名」,實際收回需 GM 看名單確認(見 admin_panel.js)。
  // ════════════════════════════════════════════════════════════════════
  window._fbAdminScanInflatedRosters = async function(opts){
    opts = opts || {};
    const _threshold = parseInt(opts.threshold, 10) || 5;
    const _ssrSet = new Set(window.SUMMON_RARE_HEROES || []);
    if(!_ssrSet.size){
      console.warn('[_fbAdminScanInflatedRosters] window.SUMMON_RARE_HEROES 未就緒,無法判定 SSR');
      return { ok:false, reason:'no_ssr_set' };
    }
    const snap = await getDocs(collection(_fbDb, 'players'));
    const _out = [];
    snap.forEach(docSnap => {
      try{
        const d = docSnap.data() || {};
        const _unlocked = Array.isArray(d.unlockedHeroes) ? d.unlockedHeroes : [];
        if(!_unlocked.length) return;
        let _hist = Array.isArray(d._heroUnlockHistory) ? d._heroUnlockHistory : null;
        if(!_hist && typeof d._heroUnlockHistory_s === 'string'){
          try{ _hist = JSON.parse(d._heroUnlockHistory_s); }catch(_){ _hist = null; }
        }
        const _legitNames = new Set();
        if(Array.isArray(_hist)){
          _hist.forEach(h => { if(h && h.name && h.source !== 'admin_delete') _legitNames.add(h.name); });
        }
        const _ssrInRoster = _unlocked.filter(n => _ssrSet.has(n));
        const _suspected = _ssrInRoster.filter(n => !_legitNames.has(n));
        if(_suspected.length >= _threshold){
          const _hl = (d.heroLevels && typeof d.heroLevels === 'object') ? d.heroLevels : {};
          const _maxLv = Math.max(0, ...Object.values(_hl).map(v => v || 0));
          _out.push({
            uid: docSnap.id,
            name: d.displayName || '',
            email: d.email || '',
            totalUnlocked: _unlocked.length,
            ssrInRoster: _ssrInRoster.length,
            ssrWithHistory: _ssrInRoster.length - _suspected.length,
            suspectedCount: _suspected.length,
            suspected: _suspected,
            historyCount: Array.isArray(_hist) ? _hist.length : 0,
            knowledgeCoins: d.knowledgeCoins || 0,
            maxHeroLv: _maxLv,
          });
        }
      }catch(_e){ /* 單筆失敗略過 */ }
    });
    _out.sort((a,b) => b.suspectedCount - a.suspectedCount);
    console.log('[_fbAdminScanInflatedRosters] 掃描完成,門檻 ' + _threshold + ' → 命中 ' + _out.length + ' 個帳號');
    return { ok:true, threshold:_threshold, count:_out.length, players:_out };
  };

  // ── 批次收回多隻英雄(汙染清除用)──
  //   清 unlockedHeroes + 5 大養成表(對齊 _fbAdminDeleteUnlockedHero 的欄位,只是一次清多隻),
  //   寫 admin_delete 稽核,並寫 _adminRescueSignal(反污染:學生下次開遊戲會自動清本地殘留 +
  //   以雲端為準,配合 v3.13.39 union 熔斷,確保本地那批 SSR 不會再被併回來)。
  //   走 updateDoc 直接寫主文件(繞過 _fbSaveLive 健康度守門,因為這是管理員授權的縮減)。
  window._fbAdminBulkRemoveHeroes = async function(uid, heroNames, opts){
    if(!uid) throw new Error('必須提供 uid');
    const _list = Array.isArray(heroNames) ? heroNames.filter(Boolean) : [];
    if(!_list.length) return { ok:false, reason:'no_heroes' };
    opts = opts || {};
    const _removeSet = new Set(_list);
    const _adminEmail = (window._fbUser && window._fbUser.email) || 'admin';
    // ★★ v5.130.0(老師裁定甲)— 改走三槽同寫單一真相 ★★
    //   舊版只寫主檔:UR 稽核那顆「🗑 刪除勾選的 UR」用的就是本函式,
    //   live/safe 兩槽完全沒動 ⇒ 學生下次登入被合併/幻影救回撿回來 ⇒ 老師實測的「刪了又回來」。
    //   ★ 同時修好舊版少清一張養成表的缺口:舊版只清 7 張(漏 heroCapsuleInvested),
    //     而 _lxpsHeroFloorOntoMain 的 effort 判定會讀膠囊投資 ⇒ 漏清那張也足以讓英雄復活。
    try{
      const _now = Date.now();
      // ★ v5.151.0 — 移除前先算跨三槽 canonical 原等級,避免三槽各自暫存出不同等級
      //   (老師實錘「6213 魔劍姬 44 級救回變 26 級」根因:舊版逐槽只看自己那槽的 heroLevels)
      const _canon = await window._lxpsCanonicalHeroLevels(uid, _list);
      const _res130 = await window._lxpsAdminApplyAllSlots(uid, function(d, slot){
        const _p = window._lxpsSlotRemoveHeroesPatch(d, _list, {
          at: _now, by: _adminEmail, uid: uid, slot: slot,
          reason: opts.reason || '帳號汙染暴增英雄收回'
        });
        if(!_p) return null;
        // ★ v5.151.0 — 三槽一律暫存同一個 canonical 原等級到 _auditRecoveredLevels
        //   (v3.17.2「🛟 一鍵無損救回」讀存檔那條救星,三槽現在還原出同一個值)
        var _stash = (d._auditRecoveredLevels && typeof d._auditRecoveredLevels === 'object') ? Object.assign({}, d._auditRecoveredLevels) : {};
        _list.forEach(function(n){
          var _lv = (typeof _canon[n] === 'number') ? _canon[n] : 1;
          if(typeof _stash[n] !== 'number' || _stash[n] < _lv) _stash[n] = _lv || 1;
        });
        _p._auditRecoveredLevels = _stash;
        return _p;
      }, {
        label: 'GM批次收回英雄',
        rescueSignal: { ts:_now, by:_adminEmail, fromSlot:'admin_scrub', version:1 },
        lastAction: { type:'bulk_remove_polluted', count:_list.length, at:_now, by:_adminEmail, reason: opts.reason || '' }
      });
      const _d = _res130.mainData || {};
      const _unlocked = (Array.isArray(_d.unlockedHeroes) ? _d.unlockedHeroes : []).filter(n => !_removeSet.has(n));
      // 保護至寶清單(僅供回報顯示;解除裝備已由 patch builder 逐槽各自處理)
      const _protectedTreasures = [];
      try{
        const _treV = (_d.taiwanTreasureData && typeof _d.taiwanTreasureData === 'object') ? _d.taiwanTreasureData : {};
        Object.keys(_treV).forEach(function(_tid){
          const _rec = _treV[_tid];
          if(_rec && _rec.equippedTo && _removeSet.has(_rec.equippedTo)) _protectedTreasures.push(_tid);
        });
      }catch(_eTv){}
      console.log('[_fbAdminBulkRemoveHeroes v5.130.0] ✅ uid=' + uid + ' 收回 ' + _list.length
        + ' 隻(保護至寶 ' + _protectedTreasures.length + ' 個):', _list);
      // ★ v3.16.7 — 學生自助審查「不是我的」回收的投資補償金額(僅 opts.compensate 時回傳,呼叫端用 _fbCompensatePlayer 正規發放)
      var _auditCompCoins = 0;
      if(opts && opts.compensate){
        _list.forEach(function(_hn){
          var _lv = (_d.heroLevels && typeof _d.heroLevels[_hn] === 'number') ? _d.heroLevels[_hn] : 1;
          _auditCompCoins += Math.min(30000, Math.max(800, (Number(_lv) || 1) * 600));
        });
      }
      return { ok:true, uid, removed:_list.length, remaining:_unlocked.length, heroes:_list,
               protectedTreasures:_protectedTreasures, compensateCoins:_auditCompCoins, slots:_res130 };
    }catch(e){
      console.error('[_fbAdminBulkRemoveHeroes] 失敗', e);
      return { ok:false, reason:(e && (e.code||e.message)) || 'exception' };
    }
  };

