      var recs = names.map(function(n){ return { name:n, at:now, source:'admin_grant', uid:String(uid).slice(0,12) }; });
      var patch = { _auditPendingHeroes: F.arrayRemove.apply(F, names), _heroUnlockHistory: F.arrayUnion.apply(F, recs), _authoritativeRestoreAt: now };
      try{ await F.updateDoc(ref, patch); }
      catch(_eU){ await F.setDoc(ref, patch, { merge:true }); }   // 欄位不存在 → 退 setDoc merge
      return true;
