  //   凍結效果:可裝備、戰鬥照常;但不可獲得經驗升級/用至寶經驗卷軸/投資素質點,待 GM 審核。
  //   清單 players/{uid}._auditPendingTreasures(陣列·arrayUnion 加入·GM 審核時移除);_applySafeData 載入到 window._auditPendingTreasureSet。
  //   ⚠ 日本三神器(tengu/shutendoji/tamamo)是任務物品非至寶,審查/判定/移除一律排除(window._isJapanTreasureKey)。
  window._auditPendingTreasureSet = (window._auditPendingTreasureSet instanceof Set) ? window._auditPendingTreasureSet : new Set();
  window._isAuditPendingTreasure = function(k){ try{ return !!(k && window._auditPendingTreasureSet && window._auditPendingTreasureSet.has(k)); }catch(_){ return false; } };
  window._fbMarkAuditPendingTreasure = function(keys){
    try{
      if(!keys || !keys.length) return;
      var _ks = [];
      keys.forEach(function(k){ if(k && !(window._isJapanTreasureKey && window._isJapanTreasureKey(k))){ window._auditPendingTreasureSet.add(k); _ks.push(k); } });
      if(!_ks.length) return;
      if(typeof window._lxpsCloudInstantUnlock === 'function' && window._fbFns && typeof window._fbFns.arrayUnion === 'function'){
        window._lxpsCloudInstantUnlock({ _auditPendingTreasures: window._fbFns.arrayUnion.apply(window._fbFns, _ks) }, '待審查至寶 ' + _ks.length + ' 個');
      }
    }catch(e){ console.warn('[待審查至寶標記] 例外', e); }
  };

  // ★ v3.16.31 — 讀雲端至寶帳本(供圖鑑審查掃描「持有但查無紀錄」的至寶)。讀取失敗回 null(不掃描·避免無證據誤判)。
  window._fbGetCloudTreasureHistory = async function(uid){
    try{
      if(!uid) return [];
      const _snap = await getDoc(doc(_fbDb, 'players', uid));
      if(!_snap.exists()) return [];
      const _d = _snap.data() || {};
      if(Array.isArray(_d._treasureUnlockHistory)) return _d._treasureUnlockHistory;
      if(typeof _d._treasureUnlockHistory_s === 'string'){ try{ const _p = JSON.parse(_d._treasureUnlockHistory_s); if(Array.isArray(_p)) return _p; }catch(_){} }
      return [];
    }catch(e){ console.warn('[_fbGetCloudTreasureHistory] 失敗', e); return null; }
  };

  // ★ v3.16.31 — GM 審核「待審查至寶」(由 admin_panel.js 救援卡呼叫):
  //   通過 → 清 _auditPendingTreasures 解凍 + 寫合法紀錄(admin_grant·之後不再被審查)+ 蓋 _authoritativeRestoreAt 讓玩家端重載生效。
  //   不通過 → 清 pending + 移出 taiwanTreasureData(連 _s 整包覆蓋·避免 _applySafeData 採信舊 _s 復活)+ 解除裝備
  //            + 標 audit_error_recovered(可逆≠刪除·_applySafeData 載入會剔除本機殘留·重抽/自選/冒險解鎖會寫新紀錄自動正式解鎖)+ 蓋 restore。
  //   ★ 鐵則:可逆、uid 閘(寫 players/{傳入uid})、寧漏不誤刪;連 _s 整包覆蓋(map merge:true 是landmine)。
  window._fbAdminApproveAuditTreasures = async function(uid, keys){
    try{
      if(!uid || !keys || !keys.length || !window._fbDb || !window._fbFns) return false;
      var F = window._fbFns, ref = F.doc(window._fbDb, 'players', uid), now = Date.now();
      var recs = keys.map(function(k){ return { id:k, at:now, source:'admin_grant', uid:String(uid).slice(0,12) }; });
      var patch = { _auditPendingTreasures: F.arrayRemove.apply(F, keys), _treasureUnlockHistory: F.arrayUnion.apply(F, recs), _authoritativeRestoreAt: now };
      try{ await F.updateDoc(ref, patch); }
      catch(_eU){ await F.setDoc(ref, patch, { merge:true }); }
      return true;
    }catch(e){ console.warn('[GM至寶審核通過] 失敗', e); return false; }
  };
  window._fbAdminRejectAuditTreasures = async function(uid, keys){
    try{
      if(!uid || !keys || !keys.length || !window._fbDb || !window._fbFns) return false;
      // ★★ v5.130.0(老師裁定甲)— 改走三槽同寫單一真相 ★★
      //   舊版只寫主檔 ⇒ live/safe 至寶殘留 + 沒有 audit_error_recovered 帳本 ⇒ 被駁回的至寶
      //   會被三槽合併/幻影救回撿回來(至寶身上還可能帶 equippedTo 連英雄一起救活)。
      var now = Date.now();
      await window._lxpsAdminApplyAllSlots(uid, function(d, slot){
        var p = window._lxpsSlotTreasurePatch(d, keys, {
          at:now, mode:'remove', by:'admin_audit', uid:uid, slot:slot,
          source:'audit_error_recovered'
        });
        if(!p) return null;
        if(slot === 'main'){
          p._auditPendingTreasures = window._fbFns.arrayRemove.apply(window._fbFns, keys);   // 待審清單只存在主檔
        }
        return p;
      }, { label:'GM審核不通過至寶' });
      return true;
    }catch(e){ console.warn('[GM至寶審核不通過] 失敗', e); return false; }
  };

