    _grants.sort(function(a, b){ return (b.at || 0) - (a.at || 0); });

    // ── ③ 每張券的下落（ticketLedger：ev/item/n/at/result）──
    var _led = [];
    try{
      if(typeof window._fbLoadTicketLedger === 'function') _led = await window._fbLoadTicketLedger(uid) || [];
    }catch(_e4){ _warn.push('召喚卷帳本讀取失敗：' + ((_e4 && _e4.message) || _e4)); }
    var _KIND = {
      'summon_ticket_ur_pick':       { k:'ur',      nm:'👑 UR 自選卷' },
      'summon_ticket_treasure_pick': { k:'tre',     nm:'💠 自選至寶卷' },
      'summon_ticket_ssr_pick':      { k:'ssrPick', nm:'🌟 SSR 自選卷' }
    };
    var _uses = [];
    var _usedN = { ur:0, tre:0, ssrPick:0 };
