    var _left = {
      ur:  (parseInt(_bag['summon_ticket_ur_pick'], 10) || 0) + (parseInt(_bag['gm_summon_ticket_ur_pick'], 10) || 0),
      tre: (parseInt(_bag['summon_ticket_treasure_pick'], 10) || 0) + (parseInt(_bag['gm_summon_ticket_treasure_pick'], 10) || 0),
      ssrPick: (parseInt(_bag['summon_ticket_ssr_pick'], 10) || 0) + (parseInt(_bag['gm_summon_ticket_ssr_pick'], 10) || 0)
    };
    // ★ v5.133.0（老師需求「更精確看到自選至寶/自選SSR的來源」）— 手上的券依鍵分列：
    //   gm_ 前綴鍵＝老師發放通道專用（v3.17.6 起三個獎勵產生器一律發 gm_ 鍵）；
    //   非 gm_ 鍵＝鬥技場兌換、v3.17.6 前的舊發放、或 _useGmTicket 換券殘留
    //   ⇒ 老師一眼分辨「手上這張是不是我發的」。
    var _lk = function(k){ return parseInt(_bag[k], 10) || 0; };
    var _leftDetail = {
      ur:      { gm: _lk('gm_summon_ticket_ur_pick'),       base: _lk('summon_ticket_ur_pick') },
      tre:     { gm: _lk('gm_summon_ticket_treasure_pick'), base: _lk('summon_ticket_treasure_pick') },
      ssrPick: { gm: _lk('gm_summon_ticket_ssr_pick'),      base: _lk('summon_ticket_ssr_pick') }
    };
    // 老師直接發的 UR 英雄（不佔券額度）
    var _grantedHeroes = {};
    _grants.forEach(function(g){ (g.heroes || []).forEach(function(h){ _grantedHeroes[h] = 1; }); });
    // 應有 UR 隻數 = 老師直接發的 + UR 券已使用張數
    var _shouldUR = Object.keys(_grantedHeroes).length + _usedN.ur;
    var _surplusUR = Math.max(0, _ownedUR.length - _shouldUR);
    // 券換到的 UR（有明確結果的）→ 供老師區分「這隻是券換的、那隻查無來源」
    var _fromTicket = {};
    _uses.forEach(function(u){ if(u.kind === 'ur' && u.result) _fromTicket[u.result] = u.at; });
    // ★ 培育快照：派發「UR 角色數量確認」時要帶（退還培育資源用，與 GM 端同一組欄位）
    var _pick = function(o, n){ return (o && typeof o === 'object' && o[n] != null) ? o[n] : null; };
    var _num = function(v){ var x = parseInt(v, 10); return isNaN(x) ? 0 : x; };
    // heroSkillLevels[n] 可能是數字（單技能）或 { s1, s2 } 物件 → 兩種都吃
    var _skLv = function(n, which){
      var _v = _pick(_d.heroSkillLevels, n);
      if(_v && typeof _v === 'object') return _num(_v[which]);
      return (which === 's1') ? _num(_v) : 0;
    };
    var _snapOf = function(n){
      var _inv = _pick(_d.heroStatInvested, n) || {};
      return {
        name: n,
        lv:       Math.max(1, _num(_pick(_d.heroLevels, n)) || 1),
        exp:      Math.max(0, _num(_pick(_d.heroExp, n))),
        capsule:  { hp:_num(_inv.hp), atk:_num(_inv.atk), sp:_num(_inv.sp), spd:_num(_inv.spd) },
        s1:       Math.max(0, _skLv(n, 's1')),
        s2:       Math.max(0, _skLv(n, 's2')),   // ★ v5.129.0 補：漏了 s2，技能2 的退款會少算
        burst:    Math.max(0, _num(_pick(_d.heroBurstLevels, n))),
        invested: Math.max(0, _num(_pick(_d.heroStatPoints, n)))
      };
    };

    // ════════════════════════════════════════════════════════════════
    // ★★ v5.129.0【自我複查修正】改用與「全體稽核中心」完全相同的判定口徑 ★★
    // ────────────────────────────────────────────────────────────────
    //   v5.127/128 的第一版用「ticketLedger 的 use 筆數」推算應有隻數 —— 那是**第二套口徑**，
    //   而且四個地方都會低估學生的合法額度：
    //     ① 完全沒算合法的額度加項：稽核補發授權 `_urQuotaAdjust`、🏟 鬥技場兌換
    //     ② 沒認 `_heroUnlockHistory` 的 GM 給予類來源
    //        （admin_grant / compensation / student_designer / event_quest）
    //     ③ ticketLedger 只留最後 500 筆，舊紀錄被截掉 ⇒「已使用」被少算
    //     ④ ticketLedger 是**學生端寫的**，本來就不該當判定依據
    //   ⇒ 四項全部指向同一個後果：**把合法取得的 UR 判成「查無來源」⇒ 誤收**。
    //     而我上一輪才對老師說「與全體稽核共用同一把尺」，實際上只共用了解析器。
    //   ⇒ 改為與全體稽核逐字對齊：`_heroUnlockHistory` 逐隻歸因（gm／ticket／unknown），
    //     額度 = 三來源發出 + 稽核補發授權 + 鬥技場兌換，
    //     超額 = max(0, 券換取隻數 − 額度) + 查無來源隻數。
    //   ⚠ ticketLedger 降級為**純展示**（老師要的「每張券換到什麼、什麼時候」），不參與判定。
    // ════════════════════════════════════════════════════════════════
    var _srcCat = function(x){
      try{ if(typeof window._lxpsRareSrcCat === 'function') return window._lxpsRareSrcCat(x); }catch(_){}
      var t = String(x == null ? '' : x);
      if(!t) return 'other';
      if(t === 'admin_delete') return 'deleted';
      if(t.indexOf('summon') === 0 || t.indexOf('ticket') === 0) return 'summon';
      if(t === 'admin_grant' || t === 'compensation' || t === 'student_designer' || t === 'event_quest') return 'gm';
      return 'other';
    };
    var _hist = [];
    try{
      if(Array.isArray(_d._heroUnlockHistory)) _hist = _d._heroUnlockHistory;
      else if(typeof _d._heroUnlockHistory_s === 'string'){
        var _hp = JSON.parse(_d._heroUnlockHistory_s); if(Array.isArray(_hp)) _hist = _hp;
      }
    }catch(_){}
    var _lastRec = {};
    _hist.forEach(function(r){
      if(!r || !r.name) return;
      var _p0 = _lastRec[r.name];
      if(!_p0 || ((r.at || 0) >= (_p0.at || 0))) _lastRec[r.name] = r;
    });
    // 額度加項：稽核補發授權 + 🏟 鬥技場兌換（都是合法來源，漏算就會冤枉學生）
    var _quotaAdj = Math.max(0, parseInt(_d._urQuotaAdjust, 10) || 0);
    var _arenaTk = 0;
    try{
      var _ar = Array.isArray(_d._arenaExchangeLog) ? _d._arenaExchangeLog : [];
      _ar.forEach(function(x){
        if(!x) return;
        if(String(x.item || x.key || '').indexOf('ur_pick') >= 0) _arenaTk += Math.abs(parseInt(x.n, 10) || 1);
      });
    }catch(_){}
    var _urQuota = _grantedN.ur + _quotaAdj + _arenaTk;

    var _urDetail = _ownedUR.map(function(n){
      var _r = _lastRec[n];
      var _src = _r ? String(_r.source || '') : '';
      var _o = _snapOf(n);
      // ★ 與全體稽核完全相同的三分法
      if(_grantedHeroes[n] || _srcCat(_src) === 'gm'){ _o.origin = 'gm';      _o.src = '老師直接發放'; }
      else if(_src === 'ticket_ur_pick'){              _o.origin = 'ticket';  _o.src = 'UR 自選卷兌換'; }
      else {                                           _o.origin = 'unknown'; _o.src = ''; }
      _o.at = (_r && typeof _r.at === 'number') ? _r.at : (_fromTicket[n] || 0);
      _o.rawSrc = _src;
      _o.byGmDirect = (_o.origin === 'gm') ? 1 : 0;
      _o.noSrc = (_o.origin === 'unknown');
      return _o;
    });
    // ★ v5.143.0 — 券 tid ↔ 英雄／至寶 互相對上（純展示；判定引擎零改動）
    //   解鎖帳本從 v5.143.0 起在券換取的紀錄上寫 tid；這裡把「每張券的下落」表的 use 紀錄依 tid 反查是哪隻／哪件。
    var _tidHit = {};   // tid → [顯示名]
    try{
      _hist.forEach(function(r){
        if(!r || !r.tid || !r.name) return;
        String(r.tid).split(',').forEach(function(t){ t = t.trim(); if(!t) return; (_tidHit[t] = _tidHit[t] || []).push(String(r.name)); });
      });
      var _treH = [];
      if(Array.isArray(_d._treasureUnlockHistory)) _treH = _d._treasureUnlockHistory;
      else if(typeof _d._treasureUnlockHistory_s === 'string'){ try{ var _tp = JSON.parse(_d._treasureUnlockHistory_s); if(Array.isArray(_tp)) _treH = _tp; }catch(_){} }
      _treH.forEach(function(r){
        if(!r || !r.tid || !r.id) return;
        var _nm = String(r.id);
        try{ var _tdb = window.TAIWAN_TREASURES; if(_tdb && _tdb[r.id] && _tdb[r.id].name) _nm = _tdb[r.id].name; }catch(_){}
        String(r.tid).split(',').forEach(function(t){ t = t.trim(); if(!t) return; (_tidHit[t] = _tidHit[t] || []).push('💎' + _nm); });
      });
      _uses.forEach(function(u){
        if(!u.tid) return;
        var _got = [];
        u.tid.split(',').forEach(function(t){ t = t.trim(); if(t && _tidHit[t]) _got = _got.concat(_tidHit[t]); });
        u.tidHit = _got.join('、');
      });
    }catch(_eTid){ try{ console.warn('[單人查核] tid 反查失敗（不影響判定）', _eTid); }catch(_){} }
    _urDetail.forEach(function(x){ try{ var _r2 = _lastRec[x.name]; x.tid = (_r2 && _r2.tid) ? String(_r2.tid) : ''; }catch(_){ x.tid = ''; } });
    var _ticketOwned  = _urDetail.filter(function(x){ return x.origin === 'ticket'; });
    var _unknownOwned = _urDetail.filter(function(x){ return x.origin === 'unknown'; });
    var _gmOwned      = _urDetail.filter(function(x){ return x.origin === 'gm'; });
    _ticketOwned.sort(function(a, b){ return (a.at || 0) - (b.at || 0); });
    var _overTicket = Math.max(0, _ticketOwned.length - _urQuota);
    // ════════════════════════════════════════════════════════════════
    // ★★ v5.251.0(老師 2026-10-13 實錘 6217:「他已經召喚出兩支我給他的 UR 召喚卷」)★★
    //   舊口徑把「查無來源」一律算超額 ⇒ 老師發 2 張、學生用 2 張換了 2 隻,
    //   只因為是解鎖帳本上線前換的(帳本來源 legacy_grandfather / 空白),就被標成「多 2 隻」⇒ 叫老師刪合法英雄。
    //   新口徑:查無來源的 UR 先拿「券額度扣掉券換取後剩下的」去抵(推定是用老師發的券換的),
    //     抵得完 = 合法(綠勾·標「舊帳推定券換」);抵不完的才是真正查無來源的超額。
    //   ⇒ 只會比舊口徑少判、不會多判(學生保護方向)。全體稽核中心(_fbAdminScanURTicketAudit)本輪未改。
    // ════════════════════════════════════════════════════════════════
    //   順序:查無來源的舊帳一定早於有 ticket_ur_pick 紀錄的(解鎖帳本上線前換的)⇒ 依時間先佔額度,
    //   超出的是「最後才換到」的那幾隻(較可能是用殘留券換的),標 overQuota 讓老師一眼看出該收哪隻。
    _unknownOwned.sort(function(a, b){ return (a.at || 0) - (b.at || 0); });
    var _legacyCovered = Math.min(_unknownOwned.length, _urQuota);
    _unknownOwned.slice(0, _legacyCovered).forEach(function(x){
      x.origin = 'legacy'; x.noSrc = false; x.legacyCovered = true;
      x.src = '舊帳無紀錄・推定用老師發的券換的(在券額度內)';
    });
    var _unknownLeft = _unknownOwned.length - _legacyCovered;
