      try{ if(typeof window._fbReconcileRedeemCodeTickets === 'function') window._fbReconcileRedeemCodeTickets(); }catch(_){}
      try{ if(typeof window._fbReconcileGlobalRewardTickets === 'function') window._fbReconcileGlobalRewardTickets(); }catch(_){}
      console.log('✅ 已登入:', user.displayName);

