      try{
        setTimeout(function(){
          try{ if(typeof window._maybeShowStyleOnboarding === 'function') window._maybeShowStyleOnboarding(); }
          catch(_eSo){ console.warn('[風格選擇首登] 觸發例外', _eSo); }
        }, 1500);
      }catch(_eSoT){ console.warn('[風格選擇首登] 排程失敗', _eSoT); }
      // ★ v3.15.99 — 登入到關卡頁後,首次登入(未建會員資料)自動彈「會員資料建立」表單
